_FRONTEND_SOURCES = {'frontend.settings': '"""Server-only frontend configuration; never return these values to the browser."""\nimport os\nimport re\nfrom dataclasses import dataclass, field\nfrom urllib.parse import urlsplit\n\nimport requests\nimport streamlit as st\n\n\nclass ConfigurationError(requests.RequestException):\n    """Intentionally contains no URL, key, password or upstream response."""\n\n\ndef secret(name, default=""):\n    value = os.environ.get(name)\n    if value is not None:\n        return value\n    try:\n        return str(st.secrets.get(name, default))\n    except (FileNotFoundError, KeyError, st.errors.StreamlitSecretNotFoundError):\n        return default\n\n\n@dataclass(frozen=True)\nclass Settings:\n    api_url: str = field(repr=False)\n    key_id: str = field(repr=False)\n    signing_secret: str = field(repr=False)\n    password_hash: str = field(repr=False)\n    local_http: bool = False\n\n\ndef load_settings():\n    url = secret("FINQ_API_URL", "http://127.0.0.1:8000").strip().rstrip("/")\n    try:\n        parsed = urlsplit(url)\n        port = parsed.port\n    except ValueError:\n        raise ConfigurationError("The app connection needs setup.") from None\n    local = parsed.hostname in {"127.0.0.1", "localhost", "::1"}\n    allow_local = secret("FINQ_ALLOW_LOCAL_HTTP").lower() in {"1", "true", "yes"}\n    if (parsed.scheme not in {"http", "https"} or not parsed.hostname or parsed.username or parsed.password\n            or parsed.query or parsed.fragment or parsed.path not in {"", "/"}\n            or (parsed.scheme != "https" and not (local and allow_local))\n            or any(c.isspace() for c in url) or (port is not None and not 1 <= port <= 65535)):\n        raise ConfigurationError("The app connection needs secure setup.")\n    key_id = secret("FINQ_API_KEY_ID")\n    signing_secret = secret("FINQ_API_SIGNING_SECRET")\n    if not re.fullmatch(r"[A-Za-z0-9_-]{1,64}", key_id) or len(signing_secret.encode("utf-8")) < 32:\n        raise ConfigurationError("The app connection needs setup.")\n    return Settings(url, key_id, signing_secret, secret("FINQ_APP_PASSWORD_HASH"), local and parsed.scheme == "http")\n', 'frontend.transport': '"""Authenticated server-to-server API calls, including exact multipart bytes."""\nimport hashlib\nimport hmac\nimport re\nimport secrets\nimport time\nfrom urllib.parse import urlsplit\n\nimport requests\n\nfrom frontend.settings import ConfigurationError, load_settings\nfrom frontend.seller_cache import SELLER_RESEARCH_PAUSED\n\n\nMAX_BODY = 11 * 1024 * 1024\n\n\ndef sign_prepared(prepared, key_id, signing_secret, *, timestamp=None, nonce=None):\n    body = prepared.body or b""\n    if isinstance(body, str):\n        body = body.encode("utf-8")\n        prepared.body = body\n        prepared.headers["Content-Length"] = str(len(body))\n    if not isinstance(body, bytes) or len(body) > MAX_BODY:\n        raise requests.RequestException("The upload is too large. Use a file smaller than 10 MB.")\n    timestamp = str(int(time.time()) if timestamp is None else timestamp)\n    nonce = nonce or secrets.token_hex(16)\n    canonical = "\\n".join(["finq-v1", prepared.method.upper(), prepared.path_url, timestamp, nonce,\n                            hashlib.sha256(body).hexdigest()])\n    signature = hmac.new(signing_secret.encode("utf-8"), canonical.encode("utf-8"), hashlib.sha256).hexdigest()\n    prepared.headers.update({"X-Finq-Key-Id": key_id, "X-Finq-Timestamp": timestamp,\n                             "X-Finq-Nonce": nonce, "X-Finq-Signature": signature})\n    return prepared\n\n\ndef request(method, path, **kwargs):\n    if SELLER_RESEARCH_PAUSED and method.upper() == "POST" and isinstance(path, str) and (\n            path.split("?", 1)[0].rstrip("/") == "/customer-briefs"\n            or re.fullmatch(r"/campaigns/[^/]+/customer-brief/?", path.split("?", 1)[0])):\n        raise requests.RequestException("Seller research is paused. The saved product brief is kept.")\n    settings = load_settings()\n    # Paths are application-defined. Never turn this into an arbitrary URL proxy.\n    parsed = urlsplit(path)\n    if (not isinstance(path, str) or not path.startswith("/") or path.startswith("//")\n            or parsed.scheme or parsed.netloc or parsed.fragment or "\\\\" in path\n            or re.search(r"[\\x00-\\x20\\x7f]", path)):\n        raise ConfigurationError("The requested action is unavailable.")\n    timeout = kwargs.pop("timeout", 20)\n    if set(kwargs) - {"params", "data", "json", "files"}:\n        raise ConfigurationError("The requested action is unavailable.")\n    with requests.Session() as session:\n        # Ignore ambient proxy/netrc settings; never send the signing key elsewhere.\n        session.trust_env = False\n        prepared = session.prepare_request(requests.Request(method.upper(), settings.api_url + path, **kwargs))\n        sign_prepared(prepared, settings.key_id, settings.signing_secret)\n        try:\n            response = session.send(prepared, timeout=timeout, allow_redirects=False, verify=True)\n        except requests.RequestException:\n            raise requests.RequestException("The app is temporarily unavailable. Please try again shortly.") from None\n    if 300 <= response.status_code < 400:\n        raise requests.RequestException("The app connection needs setup.")\n    return response\n\n\ndef get(path, **kwargs):\n    return request("GET", path, **kwargs)\n', 'frontend.access': '"""A private-workspace login in front of every API request and report view."""\nfrom collections import deque\nimport hashlib\nimport hmac\nimport re\nimport threading\nimport time\n\nimport streamlit as st\n\nfrom frontend.settings import ConfigurationError, load_settings\n\n\nABSOLUTE_SESSION_SECONDS = 8 * 3600\nIDLE_SESSION_SECONDS = 30 * 60\nATTEMPT_WINDOW_SECONDS = 15 * 60\n_attempts = deque()\n_lock = threading.RLock()\n\n\ndef valid_password_hash(value):\n    return bool(re.fullmatch(r"pbkdf2_sha256\\$600000\\$[0-9a-f]{32}\\$[0-9a-f]{64}", value or ""))\n\n\ndef verify_password(password, encoded):\n    if not valid_password_hash(encoded) or not isinstance(password, str) or len(password) > 1024:\n        return False\n    _, iterations, salt, expected = encoded.split("$")\n    actual = hashlib.pbkdf2_hmac("sha256", password.encode("utf-8"), bytes.fromhex(salt), int(iterations)).hex()\n    return hmac.compare_digest(actual, expected)\n\n\ndef _retry_after(now):\n    with _lock:\n        while _attempts and _attempts[0] <= now - ATTEMPT_WINDOW_SECONDS:\n            _attempts.popleft()\n        return max(0, int(_attempts[0] + ATTEMPT_WINDOW_SECONDS - now) + 1) if len(_attempts) >= 5 else 0\n\n\ndef _claim_attempt(now):\n    with _lock:\n        if _retry_after(now):\n            return False\n        _attempts.append(now)\n        return True\n\n\ndef _logout():\n    st.session_state.clear()\n\n\ndef _session_valid(settings, state, now):\n    fingerprint = hashlib.sha256((settings.api_url + settings.key_id + settings.signing_secret + settings.password_hash).encode()).hexdigest()\n    return (state.get("fingerprint") == fingerprint and 0 <= now - state.get("created", 0) < ABSOLUTE_SESSION_SECONDS\n            and 0 <= now - state.get("active", 0) < IDLE_SESSION_SECONDS)\n\n\ndef require_session():\n    """Fragments must not keep making calls after login expires or keys rotate."""\n    try:\n        valid = _session_valid(load_settings(), st.session_state.get("_access") or {}, time.time())\n    except ConfigurationError:\n        valid = False\n    if not valid:\n        st.session_state.clear()\n        st.rerun()\n\n\n@st.fragment(run_every=30)\ndef session_watchdog():\n    require_session()\n\n\ndef require_access():\n    try:\n        settings = load_settings()\n        if not valid_password_hash(settings.password_hash):\n            raise ConfigurationError("Sign-in needs setup.")\n    except ConfigurationError:\n        st.title("Intent to Outreach")\n        st.error("The app needs secure connection and sign-in setup. Contact your administrator.")\n        st.stop()\n    fingerprint = hashlib.sha256((settings.api_url + settings.key_id + settings.signing_secret + settings.password_hash).encode()).hexdigest()\n    now = time.time()\n    state = st.session_state.get("_access") or {}\n    authenticated = _session_valid(settings, state, now)\n    if authenticated:\n        st.session_state._access = {**state, "active": now}\n        session_watchdog()\n        with st.sidebar:\n            st.button("Sign out", key="_sign_out", on_click=_logout)\n        return\n    if state:\n        st.session_state.clear()\n    st.title("Intent to Outreach")\n    st.caption("Sign in to your team\'s campaign workspace.")\n    wait = _retry_after(now)\n    if wait:\n        st.warning(f"Too many sign-in attempts. Try again in {(wait + 59) // 60} minutes.")\n    with st.form("workspace_login", clear_on_submit=True):\n        password = st.text_input("Workspace password", type="password", key="_login_password")\n        submitted = st.form_submit_button("Sign in", type="primary", disabled=bool(wait))\n    if submitted and _claim_attempt(now):\n        okay = verify_password(password, settings.password_hash)\n        st.session_state.pop("_login_password", None)\n        if okay:\n            with _lock:\n                if now in _attempts:\n                    _attempts.remove(now)\n            st.session_state.clear()\n            st.session_state._access = {"fingerprint": fingerprint, "created": now, "active": now}\n            st.rerun()\n        st.error("The password was not accepted.")\n    st.stop()\n', 'frontend.presentation': '"""Non-secret presentation values; the backend remains authoritative."""\nimport ipaddress\nimport re\nfrom urllib.parse import urlsplit\n\n\ntry:\n    from frontend.settings import secret\nexcept ModuleNotFoundError:\n    from settings import secret\n\n# The narrow client guard is intentional defense against a mismatched older API.\n# Actual envelope enforcement belongs to the backend, never this UI.\n# Addresses come from Streamlit Secrets so they are not stored in source control:\n#   FINQ_TEST_RECIPIENTS = "first@example.com,second@example.com"\n#   FINQ_SENDERS = "sender@example.com=Sender Name,other@example.com=Other Name"\n# Missing values keep sending locked rather than guessing.\nTEST_RECIPIENTS = tuple(x.strip().lower() for x in secret("FINQ_TEST_RECIPIENTS").split(",") if x.strip())\nTEST_RECIPIENT = TEST_RECIPIENTS[0] if TEST_RECIPIENTS else ""\nTEST_RECIPIENT_LABEL = " and ".join(TEST_RECIPIENTS) or "the approved test inboxes"\nSENDER_NAMES = {}\nfor _pair in secret("FINQ_SENDERS").split(","):\n    _email, _, _name = _pair.partition("=")\n    if _email.strip():\n        SENDER_NAMES[_email.strip().lower()] = _name.strip() or _email.strip().lower()\nSENDERS = tuple(SENDER_NAMES)\n\nINTERNAL_REPORT_FIELDS = frozenset({\n    "Revenue Confidence", "Revenue Explanation", "Revenue Estimate USD", "Topic ID", "Metro Country", "Metro State",\n    "Model Roles", "model_roles", "Campaign ID", "Campaign Id", "campaign_id", "Run ID", "Run Id", "run_id",\n    "Export Version", "export_version", "Policy Version", "policy_version", "Prompt Version", "prompt_version",\n    "Repair Attempt", "repair_attempt", "attempt",\n})\n\n\ndef normalize_customer_website(value):\n    """Immediate form feedback only; API repeats authoritative validation."""\n    if not isinstance(value, str) or not value.strip():\n        raise ValueError("Enter a public seller website.")\n    value = value.strip()\n    if any(c.isspace() for c in value) or "@" in value or "*" in value:\n        raise ValueError("Enter a public seller website.")\n    try:\n        parsed = urlsplit(value if "://" in value else "//" + value)\n        if parsed.scheme and parsed.scheme.lower() not in {"http", "https"}:\n            raise ValueError()\n        hostname = (parsed.hostname or "").rstrip(".").lower().encode("idna").decode("ascii")\n        parsed.port\n    except (ValueError, UnicodeError):\n        raise ValueError("Enter a public seller website.") from None\n    hostname = hostname.removeprefix("www.")\n    try:\n        ipaddress.ip_address(hostname)\n    except ValueError:\n        pass\n    else:\n        raise ValueError("Enter a public seller website.")\n    labels = hostname.split(".")\n    private = ("localhost", "local", "localdomain", "internal", "lan", "home", "home.arpa", "onion", "invalid")\n    if (len(hostname) > 253 or len(labels) < 2\n            or any(not re.fullmatch(r"[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?", part) for part in labels)\n            or not re.fullmatch(r"(?:[a-z]{2,63}|xn--[a-z0-9-]+)", labels[-1])\n            or any(hostname == p or hostname.endswith("." + p) for p in private)):\n        raise ValueError("Enter a public seller website.")\n    return "https://" + hostname\n', 'frontend.state': '"""Wizard state transformations, independent of Streamlit widgets."""\nimport re\nimport unicodedata\n\nDEFAULT_DRAFT = {\n    "industries": [], "sizes": [], "revenue_tiers": [], "topics": [], "countries": [],\n    "fill_revenue": True, "include_unknown_revenue": True,\n    "company_score_min": 70, "company_score_max": 100,\n    "metro_score_min": 70, "metro_score_max": 100,\n    "suppressed_domains": [], "suppression_list_ids": [], "exclude_edu": False,\n    "topic_mappings": [],\n}\n\ndef migrate_draft(old, options):\n    """Clear obsolete filters and translate the former employee categories."""\n    draft = {key: old.get(key, value.copy() if isinstance(value, list) else value)\n             for key, value in DEFAULT_DRAFT.items()}\n    draft.update(fill_revenue=True, include_unknown_revenue=True)\n    notices = []\n    valid_tiers = {tier["id"] for tier in options["revenue_tiers"]}\n    retained = [tier for tier in draft["revenue_tiers"] if tier in valid_tiers]\n    if old.get("revenue_bands") or retained != draft["revenue_tiers"]:\n        notices.append("Revenue tiers have changed. Your old revenue selections were cleared; please select the new tiers.")\n    draft["revenue_tiers"] = retained\n    labels = options["size_bands"]\n    aliases = {"1-9": [0], "10-49": [1], "50-199": [2], "200-999": [3, 4],\n               "200-499": [3], "500-999": [4], "1000-4999": [5], "5000-10000": [6], "10000+": [7]}\n    sizes = []\n    for value in draft["sizes"]:\n        if value in labels:\n            sizes.append(value)\n            continue\n        compact = re.sub(r"[\\s,]", "", value.replace("–", "-").replace("—", "-").replace("â€“", "-"))\n        sizes.extend(labels[index] for index in aliases.get(compact, []) if index < len(labels))\n    draft["sizes"] = list(dict.fromkeys(sizes))\n    if draft["sizes"] != old.get("sizes", []):\n        notices.append("Employee selections were updated. The old 200–999 group is now Medium and Medium-Large.")\n    draft["countries"] = [country for country in draft["countries"] if country in options["countries"]]\n    return draft, notices\n\ndef regional_countries(regions, selected_regions, manual_additions=(), manual_removals=()):\n    base = {country for region in selected_regions for country in regions.get(region, [])}\n    return sorted((base | set(manual_additions)) - set(manual_removals))\n\ndef update_country_overrides(previous, current, additions, removals):\n    added = set(current) - set(previous)\n    removed = set(previous) - set(current)\n    return sorted((set(additions) | added) - removed), sorted((set(removals) | removed) - added)\n\ndef search_payload(draft):\n    """Never send obsolete UI-only state or removed persona filters."""\n    return {**{key: draft[key] for key in DEFAULT_DRAFT},\n            "fill_revenue": True, "include_unknown_revenue": True}\n\n\n# Pasted lists: commas (with or without spaces), new lines, tabs, semicolons or pipes.\n_LIST_SEPARATORS = re.compile(r"[\\r\\n\\t;|]+")\n\n\ndef _paste_key(text):\n    """Spacing, case, quotes and comma/arrow/dash spacing never block a match."""\n    text = unicodedata.normalize("NFKC", str(text)).casefold().strip().strip("\\"\'\\u201c\\u201d\\u2018\\u2019").strip()\n    text = re.sub(r"\\s*,\\s*", ",", text)\n    text = re.sub(r"\\s*>\\s*", ">", text)\n    text = re.sub(r"\\s*-\\s*", "-", text)\n    return re.sub(r"\\s+", " ", text)\n\n\ndef _option_aliases(options, format_func=None):\n    """Exact values/labels always match; short forms only when unambiguous.\n\n    Short forms: the label before its parenthesis ("XLarge"), the text inside it\n    ("$1B+", "10,000+ Employees") and the last level of a hierarchy ("Banking").\n    """\n    exact, loose = {}, {}\n    for option in options:\n        label = str(format_func(option)) if format_func else str(option)\n        for name in (str(option), label):\n            exact.setdefault(_paste_key(name), option)\n        inner = re.search(r"\\(([^()]*)\\)\\s*$", label)\n        for alias in (re.split(r"\\s*\\(", label, maxsplit=1)[0], label.rsplit(">", 1)[-1],\n                      inner.group(1) if inner else ""):\n            key = _paste_key(alias)\n            if key:\n                loose.setdefault(key, set()).add(option)\n    aliases = dict(exact)\n    for key, found in loose.items():\n        if key not in aliases and len(found) == 1:\n            aliases[key] = next(iter(found))\n    return aliases\n\n\ndef resolve_pasted(values, options, format_func=None):\n    """Turn pasted list entries into real options.\n\n    Returns (selected options in order, unmatched entries). Labels that contain\n    commas themselves ("Energy, Utilities & Waste", "XLarge (5,000 - 10,000\n    Employees)") are rebuilt by preferring the longest run of pieces that\n    matches an option.\n    """\n    known = list(options)\n    valid = set(known)\n    aliases, widest = None, 1\n    resolved, unmatched = [], []\n    for value in values or []:\n        if value in valid:\n            resolved.append(value)\n            continue\n        if aliases is None:\n            aliases = _option_aliases(known, format_func)\n            widest = max((key.count(",") for key in aliases), default=0) + 1\n        for chunk in _LIST_SEPARATORS.split(str(value)):\n            pieces = chunk.split(",")\n            i = 0\n            while i < len(pieces):\n                for j in range(min(len(pieces), i + widest), i, -1):\n                    key = _paste_key(",".join(pieces[i:j]))\n                    if key in aliases:\n                        resolved.append(aliases[key])\n                        i = j\n                        break\n                else:\n                    if pieces[i].strip():\n                        unmatched.append(pieces[i].strip())\n                    i += 1\n    return list(dict.fromkeys(resolved)), list(dict.fromkeys(unmatched))\n', 'frontend.progress': '"""Measured search progress, with a conservative legacy response fallback."""\nimport math\nimport re\n\nTERMINAL = {"complete", "cancelled", "failed"}\nCOUNT_KEYS = ("accounts", "topic_rows", "metro_rows")\nFILTER_STAGES = {"preview", "exclusions", "details", "metros", "geography", "revenue"}\nSTAGE_LABELS = {\n    "queued": "Waiting to start", "preview": "Finding topic matches",\n    "exclusions": "Checking account eligibility", "details": "Applying company filters",\n    "week_alignment": "Checking the reporting week", "metros": "Checking metro scores",\n    "geography": "Filtering surge countries", "revenue": "Checking company revenue",\n    "previous_week": "Comparing last week\'s scores", "mapping": "Mapping offerings and summarizing accounts",\n    "excel": "Preparing your Excel report", "complete": "Your report is ready",\n    "cancelled": "Search cancelled", "failed": "Search needs attention",\n    "awaiting_revenue_confirmation": "Waiting for revenue confirmation",\n}\n\n\ndef measured_count(value):\n    if isinstance(value, bool) or not isinstance(value, (int, float)):\n        return None\n    return int(value) if math.isfinite(value) and value >= 0 and value == int(value) else None\n\n\ndef display_count(value):\n    value = measured_count(value)\n    return f"{value:,}" if value is not None else "—"\n\n\ndef duration(seconds):\n    if isinstance(seconds, bool) or not isinstance(seconds, (int, float)) or not math.isfinite(seconds):\n        return "—"\n    hours, remainder = divmod(max(0, int(seconds)), 3600)\n    minutes, seconds = divmod(remainder, 60)\n    if hours:\n        return f"{hours}h {minutes:02d}m"\n    return f"{minutes}m {seconds:02d}s" if minutes else f"{seconds}s"\n\n\ndef legacy_stage(job):\n    status = job.get("status", "queued")\n    if status in TERMINAL or status in {"queued", "awaiting_revenue_confirmation"}:\n        return status\n    message = job.get("message", "").casefold()\n    for needle, stage in (("revenue", "revenue"), ("last week", "previous_week"),\n                          ("four-sheet", "excel"), ("formatting", "excel"),\n                          ("offerings", "mapping"), ("summaries", "mapping"),\n                          ("surge location", "geography"), ("metro", "metros"),\n                          ("company details", "details"), ("finding accounts", "preview")):\n        if needle in message:\n            return stage\n    return "running"\n\n\ndef _counts(values):\n    return {key: measured_count((values or {}).get(key)) for key in COUNT_KEYS}\n\n\ndef _legacy_checkpoints(job):\n    counts = job.get("counts") or {}\n    checkpoints = []\n    for stage, label, fields in (\n        ("preview", "Initial topic matches", {"accounts": "preview_accounts", "topic_rows": "preview_topic_rows"}),\n        ("details", "Company filters", {"topic_rows": "detail_topic_rows"}),\n        ("geography", "Metro scores & geography", {"accounts": "accounts_after_geography"}),\n    ):\n        if any(value in counts for value in fields.values()):\n            checkpoints.append({"id": stage, "label": label,\n                                "counts": _counts({key: counts.get(value) for key, value in fields.items()}), "removed": {}})\n    return checkpoints\n\n\ndef _legacy_revenue(job, stage):\n    counts = job.get("counts") or {}\n    cached, uncached = measured_count(counts.get("revenue_cached")), measured_count(counts.get("revenue_uncached"))\n    total = cached + uncached if cached is not None and uncached is not None else None\n    completed = None\n    match = re.search(r"Revenue:\\s*([\\d,]+)\\s*/\\s*([\\d,]+)\\s*companies", job.get("message", ""), re.IGNORECASE)\n    if match:\n        completed, total = (int(value.replace(",", "")) for value in match.groups())\n    elif total is not None:\n        if stage in {"previous_week", "mapping", "excel", "complete"}:\n            completed = total\n        elif job.get("status") == "awaiting_revenue_confirmation":\n            completed = cached\n    if total is None:\n        return None\n    return {"completed": min(completed, total) if completed is not None else None, "total": total, "cached": cached,\n            "research_completed": max(0, completed - cached) if completed is not None and cached is not None else None,\n            "research_total": uncached}\n\n\ndef progress_view(job, *, now, observed_at=None, request=None):\n    stage = legacy_stage(job)\n    stage_label = STAGE_LABELS.get(stage, "Search in progress")\n    checkpoints = _legacy_checkpoints(job)\n    current, sources = _counts({}), {key: "Not available yet" for key in COUNT_KEYS}\n    for checkpoint in checkpoints:\n        if checkpoint["id"] == "preview":\n            continue  # Initial matches never claim that accounts survived filters.\n        for key, value in checkpoint["counts"].items():\n            if value is not None:\n                current[key], sources[key] = value, checkpoint["label"]\n    elapsed = max(0, now - observed_at) if observed_at is not None else None\n    elapsed_label, stage_elapsed = "Tracking for", None\n    revenue = _legacy_revenue(job, stage)\n    telemetry = job.get("telemetry") or {}\n    if telemetry.get("version") == 1:\n        stages = {item["id"]: item for item in telemetry.get("stages", [])}\n        stage = telemetry.get("current_stage") or stage\n        stage_info = stages.get(stage, {})\n        stage_label = STAGE_LABELS.get(stage) or stage_info.get("label") or "Search in progress"\n        stage_elapsed, elapsed = stage_info.get("elapsed_seconds"), telemetry.get("elapsed_seconds")\n        elapsed_label = "Elapsed"\n        checkpoint_id = telemetry.get("counts_stage")\n        current = _counts(telemetry.get("current_counts")) if checkpoint_id != "preview" else _counts({})\n        checkpoint_label = STAGE_LABELS.get(checkpoint_id) or stages.get(checkpoint_id, {}).get("label") or "Latest results"\n        sources = {key: checkpoint_label if current[key] is not None else "Not available yet" for key in COUNT_KEYS}\n        checkpoints = [{"id": item["id"], "label": STAGE_LABELS.get(item["id"]) or item.get("label") or item["id"],\n                        "counts": _counts(item["counts"]), "removed": item.get("removed") or {}}\n                       for item in telemetry.get("stages", [])\n                       if item["id"] in FILTER_STAGES and item.get("counts") is not None]\n        if telemetry.get("revenue"):\n            revenue = {key: measured_count(telemetry["revenue"].get(key)) for key in\n                       ("completed", "total", "cached", "research_completed", "research_total")}\n            if revenue["total"] is None:\n                revenue = None\n    if job.get("status") in TERMINAL or job.get("status") == "awaiting_revenue_confirmation":\n        stage_label = STAGE_LABELS[job["status"]]\n    if stage == "exclusions" and request is not None:\n        domains = bool(request.get("suppressed_domains") or request.get("suppression_list_ids"))\n        edu = bool(request.get("exclude_edu"))\n        stage_label = ("Applying domain and education exclusions" if domains and edu else\n                       "Applying your domain exclusions" if domains else "Excluding .edu domains" if edu else\n                       "Checking account eligibility")\n        if not domains and not edu:\n            checkpoints = [item for item in checkpoints if item["id"] != "exclusions"]\n    if job.get("result_counts") is not None:\n        current = _counts(job["result_counts"])\n        sources = {key: "Final report" if current[key] is not None else "Not available yet" for key in COUNT_KEYS}\n        if checkpoints:\n            checkpoints.append({"id": "complete", "label": "Final report", "counts": current.copy(), "removed": {}})\n    exclusions = []\n    for key, label in (("suppressed_accounts", "suppressed accounts"), ("edu_excluded_accounts", ".edu accounts"),\n                       ("missing_metro_rows_excluded", "missing/invalid metro entries"),\n                       ("metro_range_rows_excluded", "metro entries outside the score range"),\n                       ("duplicate_metro_rows_removed", "duplicate metro observations")):\n        value = measured_count((job.get("counts") or {}).get(key))\n        if value:\n            exclusions.append(f"{value:,} {label}")\n    return {"stage": stage, "stage_label": stage_label, "current": current, "sources": sources,\n            "checkpoints": checkpoints, "elapsed_seconds": elapsed, "elapsed_label": elapsed_label,\n            "stage_elapsed_seconds": stage_elapsed, "revenue": revenue, "exclusions": exclusions}\n\n\ndef journey_rows(view):\n    rows = []\n    for checkpoint in view["checkpoints"]:\n        removed = checkpoint.get("removed") or {}\n        measured_losses = [(measured_count(removed.get(key)), label) for key, label in\n                           (("accounts", "accounts"), ("topic_rows", "topic rows"), ("metro_rows", "metros"))]\n        losses = [f"{value:,} {label}" for value, label in measured_losses if value is not None and value > 0]\n        loss_text = " · ".join(losses) if losses else ("0" if any(value is not None for value, _ in measured_losses) else "—")\n        rows.append({"Filter step": checkpoint["label"], "Accounts": display_count(checkpoint["counts"].get("accounts")),\n                     "Topic rows": display_count(checkpoint["counts"].get("topic_rows")),\n                     "Metro observations": display_count(checkpoint["counts"].get("metro_rows")), "Removed at this step": loss_text})\n    return rows\n', 'frontend.controls': '"""Shared confirmation and request feedback for stopping work."""\nfrom __future__ import annotations\n\nimport time\nimport streamlit as st\n\n\ndef cancel_control(api, path, scope, *, label="Cancel build", noun="campaign preparation", cancelling=False,\n                   terminal=False, payload=None, message=None, confirm_note=None, pending_note=None):\n    """A click asks; only an explicit Yes dispatches one cancellation request."""\n    key = f"cancel_state_{scope}"\n    error_key = f"cancel_error_{scope}"\n    state = st.session_state.get(key) or {}\n    if terminal:\n        st.session_state.pop(key, None)\n        st.session_state.pop(error_key, None)\n        return False\n    if cancelling or state.get("phase") in {"requesting", "sent"}:\n        st.info(message or "Cancelling — no new work will start. Waiting for the current request to stop or finish safely.")\n        if state.get("phase") == "requesting":\n            # Record the dispatch before the request so a rerun cannot duplicate it.\n            st.session_state[key] = {**state, "phase": "sent"}\n            response = api("POST", path, json=payload or {}, timeout=10, error_state=error_key)\n            if response is None or getattr(response, "ok", True) is False:\n                st.session_state[key] = {**state, "phase": "failed"}\n                st.rerun()\n            st.rerun()\n        st.caption(pending_note or "Completed results are kept. This screen will confirm when preparation has stopped.")\n        return True\n    if state.get("phase") == "failed":\n        st.warning("Cancellation has not been confirmed. Preparation may still be running.")\n        if st.button("Retry cancellation", key=f"cancel_retry_{scope}"):\n            st.session_state[key] = {"phase": "requesting", "requested_at": time.time()}\n            st.rerun()\n        return False\n    if state.get("phase") != "confirm":\n        if st.button(label, key=f"cancel_open_{scope}"):\n            st.session_state[key] = {"phase": "confirm"}\n            st.rerun()\n        return False\n    with st.container(border=True):\n        st.write(f"Cancel {noun}?")\n        st.caption(confirm_note or "Completed results will remain available.")\n        yes, no = st.columns(2)\n        if yes.button("Yes, cancel", type="primary", key=f"cancel_yes_{scope}"):\n            st.session_state[key] = {"phase": "requesting", "requested_at": time.time()}\n            st.rerun()\n        if no.button("No, keep going", key=f"cancel_no_{scope}"):\n            st.session_state.pop(key, None)\n            st.rerun()\n    return False\n', 'frontend.campaigns': '"""Compact campaign controls, isolated from the six-screen account wizard."""\n\nfrom copy import deepcopy\nimport hashlib\nimport json\nimport math\nimport re\nimport time\nimport uuid\n\nimport pandas as pd\nimport streamlit as st\n\nfrom frontend.presentation import normalize_customer_website, TEST_RECIPIENT_LABEL\nfrom frontend import access\nfrom frontend.seller_cache import SELLER_RESEARCH_PAUSED, restore_seller, persist_seller\nfrom frontend.product_mapping import (render_editor, confirm_mapping, render_source, website_prompt,\n                                      invalidate_products, source_state, render_manual_editor, current_rows)\nfrom frontend.controls import cancel_control\nfrom frontend.buyer_personas import snapshot_persona_preferences, persona_preferences_active, persona_preparation_fields, persona_preparation_ready\nfrom frontend.topic_mapping import uploaded_mapping_payload\n\n\nTERMINAL = {"complete", "completed", "partial", "failed", "cancelled", "interrupted", "data_pending"}\nBRIEF_READY = {"complete", "approved"}\nBRIEF_ACTIVE = {"running", "queued"}\nTAXONOMY = ["diagnostic", "supporting", "broad", "ambiguous"]\n\n\n# Display-only stage names; typical seconds only shape the in-stage bar movement.\nBRIEF_STAGES = (("research", "Researching the seller\'s website", 150),\n                ("extraction", "Extracting products and capabilities", 75),\n                ("alignment", "Matching your offering mapping", 45))\nBRIEF_TIPS = (\n    "Two searches run at the same time: one maps the seller\'s full product catalog, the other digs into what each product actually does.",\n    "Starting with the seller\'s own product pages, not directories or news coverage.",\n    "Every product claim has to be backed by a quote from the seller\'s website.",\n    "Your topic-to-offering mapping is kept exactly as you supplied it. Research never adds or changes a mapping.",\n    "Products found beyond your mapping are listed for reference. Emails are only written about your mapped offerings.",\n    "Emails match your mapping to products by name. If you rename a mapped offering next, keep it identical to your mapping file (capitals don\'t matter).",\n    "Emails can only claim capabilities listed in the Capabilities table. You can add, edit or remove rows before confirming.",\n    "A sub-offering label in your mapping is treated as another name for its parent product, not a separate product.",\n    "Every source keeps its link, so you can open the exact page behind any capability on the next screen.",\n    "The confirmed products guide account research, contact roles and every email in this campaign.",\n    "The same website, topics and mapping reuse finished research, so repeat runs open much faster.",\n    "Nothing is sent from here. You confirm the products next, then review the whole campaign before anything goes to Apollo.",\n)\n\n\ndef _clock(seconds):\n    minutes, seconds = divmod(max(0, int(seconds or 0)), 60)\n    return f"{minutes}m {seconds:02d}s" if minutes else f"{seconds}s"\n\n\ndef _brief_progress(record, compact=False, *, stages=BRIEF_STAGES):\n    """Stage-based progress reported by the backend; never a promised finish time."""\n    progress = record.get("progress") or {}\n    keys = [key for key, _, _ in stages]\n    stage = progress.get("stage")\n    index = keys.index(stage) if stage in keys else 0\n    within = 1 - math.exp(-float(progress.get("stage_elapsed_seconds") or 0) / stages[index][2])\n    fraction = min(0.97, (index + 0.9 * within) / len(stages)) if stage in keys else 0.02\n    label = stages[index][1] if stage in keys else "Starting seller research"\n    st.progress(fraction, text=f"Step {index + 1} of {len(stages)} · {label}")\n    details = [f"Elapsed {_clock(record.get(\'elapsed_seconds\'))}"]\n    if progress.get("sources"):\n        details.append(f"{int(progress[\'sources\']):,} sources found")\n    if progress.get("products"):\n        details.append(f"{int(progress[\'products\']):,} products identified")\n    st.caption(" · ".join(details))\n    if compact:\n        return\n    for position, (_, name, _) in enumerate(stages):\n        if position < index:\n            st.markdown(f"✅ {name}")\n        elif position == index:\n            st.markdown(f"⏳ **{name}**")\n        else:\n            st.markdown(f"⬜ {name}")\n\n\ndef render_product_research_loading(record, *, preview=False):\n    stages = BRIEF_STAGES\n    if preview:\n        stages = (*BRIEF_STAGES[:2], ("alignment", "Preparing products for review", BRIEF_STAGES[2][2]))\n    with st.container(border=True):\n        _brief_progress(record, stages=stages)\n    if preview:\n        st.info("Review the seller details and products before continuing.", icon="💡")\n        st.caption("The page updates automatically.")\n    else:\n        elapsed = float(record.get("elapsed_seconds") or 0)\n        st.info(BRIEF_TIPS[int(elapsed // 8) % len(BRIEF_TIPS)], icon="💡")\n        st.caption("This usually takes a few minutes. The page updates automatically; you can leave it open.")\n\n\nGENERIC_RESEARCH_MESSAGE = "Product research didn\'t finish this time. Retry to continue; nothing was lost."\nGENERIC_EMAIL_MESSAGE = ("The email schedule is still being confirmed with Apollo. Check its status and try again "\n                         "shortly; nothing will be sent twice.")\nGENERIC_MESSAGE = "This step didn\'t finish as expected. Please retry; your selections are kept."\n# Internal wording that should never reach users (developer diagnostics, data-model terms).\n_TECHNICAL = re.compile(\n    r"invented|\\breferences?\\b|schema|\\bJSON\\b|receipt|checkpoint|normali[sz]ed|manifest|ledger|sqlstate|"\n    r"digest|envelope|structured|model stage|continuation|\\bOpus\\b|\\bSol\\b|bounded|identit(?:y|ies)|"\n    r"provider|payload|taxonomy|KeyError|ValueError|Traceback|Exception|\\bHTTP \\d{3}\\b|"\n    r"logical|idempoten|claim reference|alignment|operation key|upload operation", re.I)\n_RESEARCH_CONTEXT = re.compile(r"customer|product|brief|research|offering|capabilit|claim|catalog|fact|topic", re.I)\n_EMAIL_CONTEXT = re.compile(r"email|schedule|sequence|sender|mailbox|upload|deliver|send|test contact|template", re.I)\n_CONTACT_CONTEXT = re.compile(r"person|people|contact|enrich|reveal|seniority|buying role|title", re.I)\nGENERIC_CONTACT_MESSAGE = "Contact sourcing didn\'t finish this time. Retry to continue; contacts already verified are kept."\n\n\ndef _safe_message(message):\n    if not _TECHNICAL.search(message):\n        return message\n    if _EMAIL_CONTEXT.search(message):\n        return GENERIC_EMAIL_MESSAGE\n    if _CONTACT_CONTEXT.search(message):\n        return GENERIC_CONTACT_MESSAGE\n    if _RESEARCH_CONTEXT.search(message):\n        return GENERIC_RESEARCH_MESSAGE\n    return GENERIC_MESSAGE\n\n\ndef public_service_message(value):\n    """Describe known pipeline failures without altering customer facts or copy."""\n    message = str(value or "")\n    replacements = {\n        "Configure the Anthropic API key for required Opus campaign stages.": "Company research needs setup before you can build a campaign.",\n        "Install the configured Anthropic SDK before running campaigns.": "Company research needs setup before you can build a campaign.",\n        "Configure the OpenAI API key for required Sol campaign stages.": "Email drafting needs setup before you can build a campaign.",\n        "Campaign tasks support only the required Opus and Sol models.": "Campaign preparation is unavailable until its setup is corrected.",\n        "Opus did not complete the structured stage.": "Research did not finish. Retry to continue.",\n        "Sol did not complete the structured stage.": "Writing did not finish. Retry to continue.",\n        "Opus research ended without a complete result.": "Research did not finish. Retry to continue.",\n        "Customer website research requires Anthropic and OpenAI credentials.": "Product research needs setup before it can start.",\n        "Backend is shutting down.": "The service is temporarily unavailable. Try again shortly.",\n        "Campaign complete; sending was simulated. No emails were sent.": "Campaign processing finished. No emails were sent.",\n        "Simulation successful - no emails were sent": "No emails were sent.",\n        "The model stage exceeded its ten-minute deadline.": "This step took too long to finish. Retry to continue.",\n        "Provider returned invalid structured JSON.": "This step returned an unusable result. Retry to continue.",\n        "Provider returned an unsupported response object.": "This step returned an unusable result. Retry to continue.",\n        "Research exceeded its three continuation limit.": "Research did not finish. Retry to continue.",\n        "Waiting for aligned current/helper data for the requested week. No paid work has started.": "Waiting for the requested week\'s intent data to be ready. Paid research has not started.",\n        "Apollo API key is not configured.": "Contact sourcing needs setup before it can start.",\n        "Apollo endpoint is not authorized.": "Contact sourcing is unavailable until its setup is corrected.",\n        "Apollo returned invalid JSON.": "Contact sourcing returned an unusable result. Retry to continue.",\n        "Apollo returned an unexpected response.": "Contact sourcing returned an unusable result. Retry to continue.",\n        "Apollo enrichment response omitted its match records.": "Contact verification returned incomplete results. Retry to continue.",\n        "Apollo enrichment identity/count mismatch; no negative results were cached.": "Contact verification returned inconsistent results. Unverified contacts have been excluded.",\n        "Apollo search returned an invalid people list.": "Contact sourcing returned an unusable result. Retry to continue.",\n        "Apollo enrichment failed after dispatch; billing is unknown and these person IDs will not be revealed again in this run.": "Contact verification failed and may have incurred a charge. These contacts will not be checked again in this run.",\n        "Apollo connection failed; reveal billing is unknown.": "Contact verification could not connect and may have incurred a charge.",\n        "Apollo is in a provider-requested cooldown; retry later.": "Contact sourcing is temporarily unavailable. Retry later.",\n        "The database connection was interrupted and could not be restored. Your filters are unchanged. Retry the search.": "The search connection was interrupted. Your filters are unchanged. Retry the search.",\n        "The database query exceeded its time limit. Your filters are unchanged. Retry, or select fewer topics.": "The search took too long to finish. Your filters are unchanged. Retry, or select fewer topics.",\n        "The database request failed. Your filters are unchanged. Retry the search; the local service log contains diagnostic details.": "The search could not load intent data. Your filters are unchanged. Retry the search.",\n        "OpenAI enrichment failed. Check the API key, quota, and connectivity, then retry.": "Revenue research could not finish. Check that research access and credits are available, then retry.",\n        "Search could not finish. Check the local service and try again.": "Search could not finish. Try again shortly.",\n        "This campaign, preview or source search is unavailable.": "This item is no longer available, usually because the service was updated. Start a new search to continue.",\n        "This search expired or the backend restarted. Start a new search.": "This report is no longer available. Start a new search.",\n        "This search expired or the backend restarted.": "This report is no longer available. Start a new search.",\n        "The database is still reconnecting. Please retry shortly.": "The search connection is still reconnecting. Please retry shortly.",\n        "Database request failed.": "The search could not load intent data. Please retry.",\n        "Previous-week table unavailable.": "Last week\'s data is unavailable, so score comparisons cannot be shown.",\n        "The current table does not contain exactly one week. Retry after the data refresh.": "The intent update contains mixed or missing reporting dates. Retry once the update is complete.",\n        "Score and detail tables are on different weeks. Retry after the data refresh.": "Intent scores and company details are from different reporting weeks. Retry once the update is complete.",\n        "Validating current and helper reporting weeks": "Checking reporting dates",\n        "The source is still on an older reporting week. This search read it directly; old-week intent data is not being reused from cache.": "The latest available intent data is still from an older reporting week. This report uses that week; try again after the next update.",\n        "More than 200,000 metro rows: Excel formatting may take several minutes and substantial memory.": "This report has more than 200,000 metro rows. Preparing the Excel download may take several minutes.",\n        "Formatting the four-sheet workbook in memory": "Preparing your four-sheet report",\n        "Reused this campaign version\'s completed reporting week.": "This campaign already has completed results for this reporting week.",\n        "Cancelling; in-flight provider requests may finish before stopping.": "Cancelling. Work already underway may take a little time to stop.",\n        "Campaign models or prompts changed. Start a new run so the saved run keeps its original policy version.": "Campaign preparation has been updated. Start a new run to continue; your earlier results remain available.",\n        "The original intent workbook expired or the backend restarted. Saved campaign results remain available; run a weekly review for a new full workbook.": "The full report download has expired. Run a new account search to prepare a current report.",\n        "The source reporting week changed. Start a new weekly review; this interrupted run cannot mix reporting periods.": "The reporting week changed. Start a new account search to continue with current data.",\n        "The reporting week changed while reloading. Retry with a new weekly review.": "The reporting week changed. Start a new account search to continue with current data.",\n    }\n    for original, replacement in replacements.items():\n        message = message.replace(original, replacement)\n    message = message.replace("The weekly account search ", "The account search ")\n    message = re.sub(r"Required (opus|sol) provider request failed( \\(HTTP \\d+\\))?; no model fallback was used\\.",\n        lambda match: f"{\'Research\' if match[1] == \'opus\' else \'Writing\'} could not finish{match[2] or \'\'}. Retry to continue.", message)\n    message = re.sub(r"Configure ((?:Anthropic|OpenAI|Apollo)(?:, (?:Anthropic|OpenAI|Apollo))*) credentials locally before starting the campaign\\.",\n        lambda match: "Setup is needed for " + ", ".join({"Anthropic": "company research", "OpenAI": "email drafting", "Apollo": "contact sourcing"}[name]\n            for name in match[1].split(", ")) + " before building the campaign.", message)\n    message = re.sub(r"\\bApollo (?=(?:API key|endpoint|is in a provider-requested cooldown|connection failed|enrichment|rate limit|request failed|returned|retry limit|search returned)\\b)",\n                     "Contact service ", message)\n    message = re.sub(r"(?:Invalid provider (?:result|list length|text length|numeric range)|Provider (?:omitted required fields|added unsupported fields)) at [\\w.$\\[\\]-]+\\.",\n                     "This step returned an unusable result. Retry to continue.", message)\n    message = re.sub(r"^The revenue (?:response|estimate|tier|amount)[^.]*\\.(?: Please retry\\.)?$",\n                     "Revenue research returned an incomplete result. Retry the search; companies already checked are kept.",\n                     message)\n    return _safe_message(message)\n\n\ndef fingerprint(value):\n    return hashlib.sha256(json.dumps(value, sort_keys=True, default=str).encode()).hexdigest()[:16]\n\n\ndef _call(api, method, path, **kwargs):\n    response = api(method, path, **kwargs)\n    return response.json() if response is not None else None\n\n\ndef _split(value):\n    return list(dict.fromkeys(part.strip() for part in str(value or "").split(";") if part.strip()))\n\n\ndef brief_tables(brief, topics):\n    """Editable projections keep source evidence and explicit mappings separate."""\n    offerings, capabilities = [], []\n    for item in brief.get("offerings") or []:\n        offerings.append({"Offering": item.get("name", ""), "Description": item.get("description", ""),\n                          "Sub-offerings": "; ".join(sub.get("name", "") for sub in item.get("sub_offerings") or [])})\n        capabilities += [{"Offering": item.get("name", ""), "Capability": cap.get("text", ""),\n                          "Source IDs": "; ".join(cap.get("source_ids") or [])} for cap in item.get("capabilities") or []]\n    classified = {item.get("topic"): item for item in brief.get("taxonomy") or []}\n    taxonomy = [{"Topic": topic, "Classification": classified.get(topic, {}).get("classification", "ambiguous"),\n                 "Reason": classified.get(topic, {}).get("reason", "Review the role this topic plays for your offering.")}\n                for topic in dict.fromkeys(topics)]\n    return offerings, capabilities, taxonomy\n\n\ndef assemble_brief(original, name, description, offerings, capabilities, taxonomy):\n    brief = deepcopy(original)\n    brief.update(customer_name=str(name).strip(), description=str(description).strip())\n    previous = {item.get("name"): item for item in original.get("offerings") or []}\n    assembled = []\n    for row in offerings:\n        label = str(row.get("Offering") or "").strip()\n        if not label:\n            continue\n        item = deepcopy(previous.get(label, {}))\n        item.update(id=item.get("id") or "off_" + fingerprint(label), name=label,\n                    description=str(row.get("Description") or "").strip())\n        if "Sub-offerings" in row:\n            existing_subs = {sub.get("name"): sub for sub in item.get("sub_offerings") or []}\n            item["sub_offerings"] = [existing_subs.get(sub) or {"id": "sub_" + fingerprint([label, sub]), "name": sub, "description": ""}\n                                     for sub in _split(row.get("Sub-offerings"))]\n        else:\n            # Column not shown: keep the researched sub-offerings, which mapped\n            # sub-offering labels are matched against when emails are written.\n            item["sub_offerings"] = item.get("sub_offerings") or []\n        existing_caps = {}\n        for cap in item.get("capabilities") or []:\n            existing_caps.setdefault(cap.get("text"), []).append(cap)\n        item["capabilities"] = []\n        for cap in capabilities:\n            text = str(cap.get("Capability") or "").strip()\n            if str(cap.get("Offering") or "").strip() != label or not text:\n                continue\n            value = deepcopy(existing_caps[text].pop(0)) if existing_caps.get(text) else {}\n            value.update(id=value.get("id") or "cap_" + fingerprint([label, text]), text=text,\n                         source_ids=_split(cap.get("Source IDs")))\n            item["capabilities"].append(value)\n        assembled.append(item)\n    brief["offerings"] = assembled\n    brief["taxonomy"] = [{"topic": str(row.get("Topic") or "").strip(),\n                           "classification": row.get("Classification") if row.get("Classification") in TAXONOMY else "ambiguous",\n                           "reason": str(row.get("Reason") or "").strip()} for row in taxonomy if row.get("Topic")]\n    return brief\n\n\ndef _brief_editor(draft):\n    record = st.session_state.get("campaign_brief_record") or {}\n    return render_editor(record, draft)\n\n\ndef _clear_sender_overrides():\n    for key in ("campaign_sender", "campaign_sender_name", "campaign_sender_company",\n                "campaign_sender_signature", "campaign_sender_cta"):\n        st.session_state.pop(key, None)\n\n\ndef customer_context_enabled(options):\n    capabilities = options.get("campaigns") or {}\n    return bool(capabilities.get("enabled") and capabilities.get("customer_context_version", 0) >= 2)\n\n\ndef customer_website():\n    record = st.session_state.get("campaign_brief_record") or {}\n    return st.session_state.get("campaign_context_website", record.get("website") or (record.get("brief") or {}).get("website", ""))\n\n\ndef customer_website_valid():\n    try:\n        normalize_customer_website(customer_website())\n        return True\n    except ValueError:\n        return False\n\n\ndef brief_request(draft, website, *, manual=False):\n    """Order-independent identity for the website, topics and explicit mappings."""\n    mappings = {json.dumps(row, sort_keys=True): row for row in draft.get("topic_mappings") or []}\n    return {"website": "" if manual else normalize_customer_website(website),\n            "topics": sorted(set(draft.get("topics") or [])),\n            "mappings": [mappings[key] for key in sorted(mappings)]}\n\n\ndef brief_matches(record, draft, website=None):\n    """A saved brief is reusable only for exactly this seller and topic mapping."""\n    if not record:\n        return False\n    manual = record.get("source") == "manual_upload"\n    if manual and (record.get("website") or (record.get("brief") or {}).get("website")\n                   or website is not None and str(website).strip()):\n        return False\n    try:\n        requested = brief_request(draft, customer_website() if website is None else website, manual=manual)\n        saved = brief_request({"topics": record.get("topics") or [],\n                               "topic_mappings": record.get("mappings") or []},\n                              record.get("website") or (record.get("brief") or {}).get("website", ""), manual=manual)\n    except ValueError:\n        return False\n    if saved == requested:\n        return True\n    # A catalog refresh may retire topics without changing the approved seller.\n    # Only those retired relationships may disappear; user edits still need review.\n    catalog = (st.session_state.get("topic_catalog_cache") or {}).get("data") or {}\n    names = catalog.get("topics")\n    if (catalog.get("status") != "ready" or catalog.get("source") != "taxonomy"\n            or not re.fullmatch(r"[0-9a-f]{64}", str(catalog.get("sha256") or ""))\n            or not isinstance(names, list) or not names\n            or any(not isinstance(name, str) or not name.strip() for name in names)):\n        return False\n    topic_key = lambda value: " ".join(str(value or "").split()).casefold()\n    lookup = {topic_key(name): name for name in names}\n    if any(topic_key(topic) not in lookup for topic in requested["topics"]):\n        return False\n    def canonical_selection(value, *, remove_missing):\n        topics = [lookup[topic_key(topic)] for topic in value["topics"] if topic_key(topic) in lookup]\n        rows = []\n        for row in value["mappings"]:\n            topic = lookup.get(topic_key(row.get("topic")))\n            if topic is None:\n                if remove_missing:\n                    continue\n                return None\n            rows.append({**row, "topic": topic})\n        return brief_request({"topics": topics, "topic_mappings": rows}, value["website"], manual=manual)\n    projected = canonical_selection(saved, remove_missing=True)\n    wanted = canonical_selection(requested, remove_missing=False)\n    return bool(projected and projected["topics"] and projected == wanted)\n\n\ndef _brief_context_is_stale(capabilities, draft):\n    record = st.session_state.get("campaign_brief_record") or {}\n    if not record:\n        return False\n    if not brief_matches(record, draft):\n        return True\n    current = capabilities.get("customer_context_version", 2)\n    previous = st.session_state.get("campaign_brief_context_version", 2)\n    return previous != current and record.get("status") != "approved"\n\n\ndef _sync_brief_input(draft):\n    st.session_state.campaign_context_website = customer_website()\n    try:\n        payload = brief_request(draft, customer_website())\n    except ValueError:\n        payload = {"website": customer_website(), "topics": sorted(set(draft.get("topics") or [])),\n                   "mappings": draft.get("topic_mappings") or []}\n    signature = fingerprint(payload)\n    previous = st.session_state.get("campaign_brief_input_signature")\n    old = st.session_state.get("campaign_brief_record") or {}\n    if (old and (old.get("source") == "manual_upload" or not brief_matches(old, draft))) or (not old and previous and previous != signature):\n        if old.get("id") or old.get("brief_id"):\n            st.session_state.campaign_brief_supersedes = old.get("id") or old.get("brief_id")\n        for key in ("campaign_brief_record", "campaign_brief_edit", "campaign_brief_seed", "campaign_brief_dirty",\n                    "campaign_brief_attempt_signature", "campaign_brief_request_error", "campaign_brief_status_error",\n                    "campaign_brief_context_version", "campaign_brief_attempt_context_version", "campaign_brief_saved_context",\n                    "campaign_created_for_job", "campaign_download", "campaign_download_signature",\n                    "campaign_run_id", "campaign_run_base_job_id", "campaign_run_snapshot", "campaign_active_id", "campaign_brief_review_panel"):\n            st.session_state.pop(key, None)\n        st.session_state.campaign_brief_revision = st.session_state.get("campaign_brief_revision", 0) + 1\n        invalidate_products()\n    st.session_state.campaign_brief_input_signature = signature\n    return payload, signature\n\n\ndef start_customer_research(api, options, draft, retry=False, regenerate=False):\n    """Start only after an explicit source/website submission or retry."""\n    if not customer_context_enabled(options):\n        return False\n    if not customer_website_valid() or not draft.get("topics"):\n        st.error("Enter a valid seller website and upload your intent topic mapping first.")\n        return False\n    payload, signature = _sync_brief_input(draft)\n    capabilities = options.get("campaigns") or {}\n    context_version = capabilities.get("customer_context_version", 2)\n    record = st.session_state.get("campaign_brief_record") or {}\n    if (not retry and not regenerate and record.get("status") in (BRIEF_READY | BRIEF_ACTIVE)\n            and not _brief_context_is_stale(capabilities, draft)):\n        return True\n    st.session_state.campaign_brief_attempt_signature = signature\n    st.session_state.campaign_brief_attempt_context_version = context_version\n    payload["retry"] = retry or regenerate\n    if regenerate:\n        payload["regenerate"] = True\n    if st.session_state.get("campaign_brief_supersedes"):\n        payload["supersedes_id"] = st.session_state.campaign_brief_supersedes\n    response = _call(api, "POST", "/customer-briefs", json=payload, error_state="campaign_brief_request_error")\n    if not response:\n        return False\n    identity = response.get("brief_id") or response.get("id")\n    # Request identity remains available even if a proxy returns a compact status.\n    context = {key: deepcopy(payload[key]) for key in ("website", "topics", "mappings")}\n    st.session_state.campaign_brief_record = {**context, **response, "id": identity}\n    st.session_state.campaign_brief_context_version = context_version\n    st.session_state.pop("campaign_brief_saved_context", None)\n    st.session_state.campaign_brief_revision = st.session_state.get("campaign_brief_revision", 0) + 1\n    for key in ("campaign_brief_edit", "campaign_brief_seed", "campaign_brief_dirty", "campaign_brief_status_error", "campaign_brief_supersedes"):\n        st.session_state.pop(key, None)\n    persist_seller()\n    return True\n\n\ndef products_confirmed(options):\n    """Require explicit approval of products for the current seller/topic mapping."""\n    if not customer_context_enabled(options):\n        return True\n    record = st.session_state.get("campaign_brief_record") or {}\n    state = st.session_state.get("product_mapping") or {}\n    draft = st.session_state.get("draft") or {}\n    identity = record.get("id") or record.get("brief_id")\n    manual = record.get("source") == "manual_upload"\n    if (state.get("mode") == "upload" and not manual) or (state.get("mode") == "auto" and manual):\n        return False\n    if not draft.get("topics") or not draft.get("topic_mappings"):\n        return False\n    reviewed = ((state.get("generation_phase") == "ready" and state.get("table_loaded"))\n                or state.get("approved_brief_id") == identity)\n    return (record.get("status") == "approved" and bool(record.get("brief"))\n            and brief_matches(record, draft) and state.get("live_flow_version") == 1\n            and reviewed and state.get("brief_id") == identity\n            and not st.session_state.get("campaign_brief_dirty", False))\n\n\ndef render_product_status(options):\n    """One quiet status line while the user works on other steps; never the brief itself."""\n    if not customer_context_enabled(options):\n        return\n    status = (st.session_state.get("campaign_brief_record") or {}).get("status")\n    if status in BRIEF_ACTIVE:\n        st.caption("⏳ Researching the seller\'s products in the background. You\'ll review and confirm them on the next step.")\n    elif status == "approved":\n        st.caption("✅ Products confirmed.")\n    elif status in BRIEF_READY:\n        st.caption("✅ Products researched. Review and confirm them on the next step.")\n    elif status in {"failed", "cancelled", "unavailable"}:\n        st.caption("Seller research is paused. The saved status is kept." if SELLER_RESEARCH_PAUSED else\n                   "Product research didn\'t finish. You can retry it on the next step.")\n\n\ndef _product_research_wait(api, brief_id):\n    @st.fragment(run_every=2)\n    def waiting():\n        access.require_session()\n        current = st.session_state.get("campaign_brief_record") or {}\n        if (current.get("id") or current.get("brief_id")) != brief_id:\n            st.rerun()\n        if not brief_matches(current, st.session_state.get("draft") or {}):\n            st.rerun()\n        updated = _call(api, "GET", f"/customer-briefs/{brief_id}", error_state="campaign_brief_status_error")\n        if updated:\n            current = {**current, **updated, "id": brief_id}\n            st.session_state.campaign_brief_record = current\n            persist_seller()\n        elif (st.session_state.get("campaign_brief_status_error") or {}).get("status") == 404:\n            current.update(status="unavailable", brief={}, error="This product research is no longer available. Retry to prepare it again.")\n            st.session_state.campaign_brief_record = current\n            st.rerun()\n        if current.get("status") not in BRIEF_ACTIVE and (current.get("status") not in BRIEF_READY or "brief" in current):\n            st.rerun()\n        render_product_research_loading(current)\n        if st.session_state.get("campaign_brief_status_error"):\n            st.warning("Research status is temporarily unavailable. Showing the last confirmed update.")\n\n    waiting()\n\n\ndef _render_manual_product_confirmation(api, options, draft):\n    capabilities = options.get("campaigns") or {}\n    if capabilities.get("manual_product_brief_version", 0) < 1:\n        st.info("Product uploads are temporarily unavailable. Reconnect and try again.")\n        return\n    edited, changed, valid = render_manual_editor(draft)\n    if edited is None:\n        return\n    name_ok = bool(str(edited.get("customer_name") or "").strip())\n    if not name_ok:\n        st.warning("Add the seller name to continue.")\n    if st.button("Confirm Offerings", type="primary", disabled=not name_ok or not valid,\n                 key="products_confirm_manual"):\n        payload = {"brief": edited, "topics": sorted(set(draft.get("topics") or [])),\n                   "mappings": brief_request(draft, "", manual=True)["mappings"]}\n        manual = st.session_state.manual_product_draft\n        submission = manual.get("submission") or {}\n        if submission.get("body") != payload:\n            submission = {"request_id": uuid.uuid4().hex, "body": deepcopy(payload)}\n            manual["submission"] = submission\n        # Save before dispatch, so reload after a lost response retries one request.\n        persist_seller()\n        existing = st.session_state.get("campaign_brief_record") or {}\n        if (not changed and existing.get("source") == "manual_upload" and existing.get("status") == "approved"\n                and brief_matches(existing, draft)):\n            response = existing\n        else:\n            submission["uncertain"] = True\n            persist_seller()\n            response = _call(api, "POST", "/customer-briefs/manual",\n                json={"request_id": submission["request_id"], **payload}, error_state="manual_products_save_error")\n            error_status = (st.session_state.get("manual_products_save_error") or {}).get("status")\n            if response is None and error_status is not None and 400 <= error_status < 500:\n                submission["uncertain"] = False\n            persist_seller()\n        if response:\n            identity = response.get("id") or response.get("brief_id")\n            if not identity or response.get("source") != "manual_upload" or response.get("status") != "approved":\n                st.error("Products could not be confirmed. Try again.")\n                return\n            submission["uncertain"] = False\n            st.session_state.pop("manual_products_save_error", None)\n            st.session_state.campaign_brief_record = {**response, "id": identity}\n            st.session_state.campaign_context_website = ""\n            st.session_state.campaign_brief_context_version = capabilities.get("customer_context_version", 2)\n            st.session_state.campaign_brief_edit = {"id": identity, "brief": response.get("brief") or edited}\n            st.session_state.campaign_brief_dirty = False\n            st.session_state.campaign_brief_revision = st.session_state.get("campaign_brief_revision", 0) + 1\n            for key in ("campaign_brief_input_signature", "campaign_brief_supersedes", "campaign_brief_seed",\n                        "campaign_brief_request_error", "campaign_brief_status_error", "campaign_created_for_job"):\n                st.session_state.pop(key, None)\n            confirmed = response.get("brief") or edited\n            manual.update(approved_id=identity,\n                brief={key: deepcopy(confirmed.get(key, [] if key in {"offerings", "taxonomy", "facts", "sources", "gaps"} else ""))\n                       for key in ("customer_name", "website", "description", "offerings", "taxonomy", "facts", "sources", "gaps")},\n                rows=current_rows(confirmed), revision=manual.get("revision", 0) + 1)\n            manual.pop("seed_key", None)\n            manual.pop("seed_rows", None)\n            if (set(response.get("topics") or []) != set(payload["topics"])\n                    or response.get("mappings") != payload["mappings"]):\n                st.session_state.pop("topic_catalog_cache", None)\n            state = source_state()\n            state.update(brief_id=identity, approved_brief_id=identity, mode="upload", rows=deepcopy(manual["rows"]),\n                         generation_phase="ready", table_loaded=True)\n            confirm_mapping()\n            st.session_state.step = 4\n            st.session_state.notice = "Products confirmed."\n            persist_seller()\n            st.rerun()\n    error = st.session_state.get("manual_products_save_error") or {}\n    if error:\n        st.error(public_service_message(error.get("message") or "Products could not be saved. Try again."))\n\n\ndef render_product_confirmation(api, options, draft):\n    """Choose a source, prepare the matching seller, then approve the actual brief."""\n    st.subheader("Seller Offerings")\n    if not customer_context_enabled(options):\n        st.info("Product research is unavailable. Check the campaign connection and try again.")\n        return\n    state = render_source(regenerate=lambda: start_customer_research(api, options, draft, regenerate=True))\n    if state.get("mode") not in {"auto", "upload"}:\n        persist_seller()\n        return\n    if state.get("mode") == "upload":\n        _render_manual_product_confirmation(api, options, draft)\n        return\n    if state.get("generation_phase") == "website":\n        website = website_prompt(state)\n        if website:\n            state["website"] = website\n            st.session_state.campaign_context_website = website\n            st.session_state.pop("campaign_website", None)\n            if start_customer_research(api, options, draft):\n                # _sync may have replaced old products after the domain changed.\n                source_state()["generation_phase"] = "research"\n                persist_seller()\n                st.rerun()\n        request_error = st.session_state.get("campaign_brief_request_error") or {}\n        if request_error:\n            st.error(public_service_message(request_error.get("message") or "Product research couldn\'t start. Try again."))\n        persist_seller()\n        return\n    record = st.session_state.get("campaign_brief_record") or {}\n    brief_id = record.get("id") or record.get("brief_id")\n    status = record.get("status")\n    if brief_id and (status in BRIEF_ACTIVE or (status in BRIEF_READY and "brief" not in record)):\n        st.caption(f"Researching {record.get(\'website\') or customer_website()}.")\n        _product_research_wait(api, brief_id)\n        return\n    if status in BRIEF_READY and record.get("brief"):\n        request_error = st.session_state.get("campaign_brief_request_error") or {}\n        if request_error:\n            st.error(public_service_message(request_error.get("message") or "Product research couldn\'t start. Try again."))\n        edited, changed, mapping_ready = _brief_editor(draft)\n        if edited is None:\n            return\n        name_ok = bool(str(edited.get("customer_name") or "").strip())\n        if not name_ok:\n            st.warning("Add the seller name to continue.")\n        if st.button("Confirm Offerings", type="primary", disabled=not name_ok or not mapping_ready,\n                     key=f"products_confirm_{brief_id}"):\n            response = _call(api, "PUT", f"/customer-briefs/{brief_id}", json={"brief": edited})\n            if response:\n                st.session_state.campaign_brief_record = {**record, **response, "id": brief_id}\n                st.session_state.campaign_brief_edit = {"id": brief_id, "brief": response.get("brief") or edited}\n                st.session_state.campaign_brief_dirty = False\n                st.session_state.pop("campaign_brief_seed", None)\n                st.session_state.campaign_brief_revision = st.session_state.get("campaign_brief_revision", 0) + 1\n                st.session_state.step = 4\n                st.session_state.notice = "Products confirmed."\n                confirm_mapping()\n                persist_seller()\n                st.rerun()\n        return\n    request_error = st.session_state.get("campaign_brief_request_error") or {}\n    failure = public_service_message(record.get("error") or request_error.get("message") or "")\n    if not re.search(r"needs setup|already running|no longer available|temporarily unavailable|Try again shortly", failure):\n        failure = "Product research didn\'t finish this time. Retry to prepare the product details."\n    st.error(failure)\n    if st.button("Retry product research", type="primary", key="products_start", disabled=not customer_website_valid()):\n        if start_customer_research(api, options, draft, retry=True):\n            source_state()["generation_phase"] = "research"\n            persist_seller()\n            st.rerun()\n\n\n\ndef _campaign_list(api, refresh=False):\n    cached = st.session_state.get("campaign_list_cache")\n    if refresh or cached is None or time.monotonic() - cached["at"] > 30:\n        response = _call(api, "GET", "/campaigns", error_state="campaign_list_error")\n        cached = {"at": time.monotonic(), "items": response.get("campaigns", []) if response is not None else (cached or {}).get("items", [])}\n        st.session_state.campaign_list_cache = cached\n    return cached["items"] if cached else []\n\n\ndef _campaign_name_candidate(default):\n    return str(st.session_state.get("campaign_new_name", default) or "").strip()[:200]\n\n\ndef _available_campaign_name(name, campaigns):\n    def normalized(value):\n        return " ".join(str(value or "").split()).casefold()\n\n    taken = {normalized(item.get("name")) for item in campaigns}\n    if not name or normalized(name) not in taken:\n        return name\n    numbered = re.fullmatch(r"(.+?) \\+(\\d+)", name)\n    base, number = (numbered[1], int(numbered[2]) + 1) if numbered else (name, 1)\n    while True:\n        suffix = f" +{number}"\n        candidate = base[:200 - len(suffix)].rstrip() + suffix\n        if normalized(candidate) not in taken:\n            return candidate\n        number += 1\n\n\ndef campaign_name_input(api, default, *, reuse=False):\n    """Check new names against fresh history; keep an existing request\'s name stable."""\n    name = _campaign_name_candidate(default)\n    ready = reuse\n    if not reuse:\n        response = _call(api, "GET", "/campaigns", error_state="campaign_name_check_error")\n        items = response.get("campaigns") if isinstance(response, dict) else None\n        if isinstance(items, list) and all(isinstance(item, dict) for item in items):\n            ready = True\n            st.session_state.campaign_list_cache = {"at": time.monotonic(), "items": items}\n            st.session_state.pop("campaign_list_error", None)\n            available = _available_campaign_name(name, items)\n            if available != name:\n                st.session_state.campaign_name_notice = {"original": name, "name": available}\n                name = available\n    # Resolve before creating the widget so its displayed value matches the submission.\n    st.session_state.campaign_new_name = name\n    name = st.text_input("Campaign name", key="campaign_new_name", max_chars=200,\n                         help="Each campaign needs its own name. Existing names get the next available +number.")\n    notice = st.session_state.get("campaign_name_notice") or {}\n    if notice.get("name") == name:\n        st.info(f"“{notice[\'original\']}” already exists. Using “{name}”.")\n    else:\n        st.session_state.pop("campaign_name_notice", None)\n    if not ready:\n        st.warning("Couldn\'t check existing campaign names. Retry the name check before building.")\n        if st.button("Retry name check", key="campaign_name_recheck"):\n            st.rerun()\n    return name.strip(), ready\n\n\ndef _activate_run(campaign_id, response):\n    run_id = response.get("run_id") or response.get("id")\n    if not run_id:\n        return\n    st.session_state.campaign_active_id = campaign_id\n    st.session_state.campaign_run_id = run_id\n    st.session_state.campaign_run_base_job_id = response.get("base_job_id")\n    st.session_state.pop("campaign_run_snapshot", None)\n    st.session_state.pop("campaign_download", None)\n    st.session_state.pop("campaign_download_signature", None)\n    st.session_state.pop("campaign_control_error", None)\n    st.session_state.pop("campaign_status_error", None)\n\n\ndef _leave_build_workspace():\n    st.query_params.pop("build", None)\n    for key in ("campaign_build_id", "campaign_build_snapshot", "campaign_build_selected_run"):\n        st.session_state.pop(key, None)\n\n\n_SAVED_VIEW_KEYS = (\n    "campaign_active_id", "campaign_run_id", "campaign_run_base_job_id", "campaign_run_snapshot",\n    "campaign_download", "campaign_download_signature", "campaign_control_error", "campaign_status_error",\n    "campaign_recovery_discovery", "campaign_recovery_discovery_error",\n)\n\n\ndef _open_saved_campaign(campaign_id, run):\n    # Borrow the run viewer without replacing the current build or wizard draft.\n    if not st.session_state.get("campaign_library_view"):\n        st.session_state.campaign_library_return = {\n            key: deepcopy(st.session_state[key]) for key in _SAVED_VIEW_KEYS if key in st.session_state}\n    for key in _SAVED_VIEW_KEYS:\n        st.session_state.pop(key, None)\n    st.session_state.campaign_library_view = campaign_id\n    st.session_state.campaign_active_id = campaign_id\n    if run:\n        _activate_run(campaign_id, run)\n\n\ndef _return_from_saved_campaign():\n    if not st.session_state.get("campaign_library_view"):\n        return\n    for key in _SAVED_VIEW_KEYS:\n        st.session_state.pop(key, None)\n    st.session_state.update(st.session_state.pop("campaign_library_return", {}))\n    st.session_state.pop("campaign_library_view", None)\n\n\ndef _forget_deleted_campaign(campaign_id):\n    previous = st.session_state.get("campaign_library_return") or {}\n    if previous.get("campaign_active_id") == campaign_id:\n        st.session_state.campaign_library_return = {}\n    if st.session_state.get("campaign_library_view") == campaign_id:\n        _return_from_saved_campaign()\n    if st.session_state.get("campaign_active_id") == campaign_id:\n        for key in _SAVED_VIEW_KEYS:\n            st.session_state.pop(key, None)\n    if (st.session_state.get("campaign_build_snapshot") or {}).get("campaign_id") == campaign_id:\n        _leave_build_workspace()\n    if ((st.session_state.get("campaign_saved_details") or {}).get("campaign") or {}).get("id") == campaign_id:\n        st.session_state.pop("campaign_saved_details", None)\n\n\ndef render_saved_campaigns_sidebar(api, options, draft):\n    capabilities = options.get("campaigns") or {}\n    if not capabilities.get("enabled"):\n        return\n    with st.sidebar:\n        st.divider()\n        if st.session_state.get("campaign_library_view"):\n            label = "Back to current campaign" if st.session_state.get("campaign_build_id") and st.session_state.get("step") == 6 else "Back to setup"\n            if st.button(label, icon=":material/arrow_back:", width="stretch", key="campaign_sidebar_back"):\n                _return_from_saved_campaign()\n                st.rerun()\n        elif st.session_state.get("campaign_build_id") and st.session_state.get("step") != 6:\n            if st.button("View current campaign", width="stretch", key="campaign_sidebar_current"):\n                st.session_state.step = 6\n                st.rerun()\n        _saved_campaigns(api, capabilities, draft, st.session_state.get("job_id"), st.session_state.get("job_progress_snapshot"))\n\n\ndef render_saved_campaign_view(api, options, draft):\n    identity = st.session_state.get("campaign_library_view")\n    campaign = (st.session_state.get("campaign_saved_details") or {}).get("campaign") or {}\n    if campaign.get("id") != identity:\n        campaign = next((item for item in (st.session_state.get("campaign_list_cache") or {}).get("items", [])\n                         if item.get("id") == identity), {})\n    st.subheader(campaign.get("name") or "Saved campaign")\n    if st.session_state.get("campaign_run_id"):\n        render_campaign_workspace(api, options, draft)\n    else:\n        st.info("This campaign has no saved runs yet.")\n\n\ndef _saved_campaigns(api, capabilities, draft, job_id=None, job=None):\n    title, refresh = st.columns([5, 1], vertical_alignment="center")\n    title.markdown("**Saved campaigns**")\n    refresh_requested = refresh.button("", icon=":material/refresh:", type="tertiary", width="stretch",\n                                       key="campaign_sidebar_refresh", help="Refresh saved campaigns")\n    items = _campaign_list(api, refresh=refresh_requested)\n    if st.session_state.get("campaign_list_error"):\n        st.warning("Saved campaigns could not refresh. Try the refresh button again.")\n    if not items:\n        if not st.session_state.get("campaign_list_error"):\n            st.caption("Campaign history appears here after the first campaign is created.")\n        return\n    lookup = {item["id"]: item for item in items}\n    if st.session_state.get("campaign_saved_selection") not in {"", *lookup}:\n        st.session_state.pop("campaign_saved_selection", None)\n    selected = st.selectbox("Saved campaign", [""] + list(lookup), key="campaign_saved_selection",\n        format_func=lambda value: (lookup[value].get("name") or value) if value else "Select a campaign")\n    if not selected:\n        return\n    if st.button("Open campaign", type="primary", width="stretch", key="campaign_sidebar_open"):\n        response = _call(api, "GET", f"/campaigns/{selected}")\n        if response:\n            st.session_state.campaign_saved_details = response\n            known_build = st.session_state.get("campaign_build_snapshot") or {}\n            if st.session_state.get("campaign_build_id") and known_build.get("campaign_id") == selected:\n                _return_from_saved_campaign()\n                st.session_state.step = 6\n            else:\n                runs = response.get("runs") or []\n                latest = max(runs, key=lambda item: str(item.get("created_at") or item.get("started_at") or ""), default=None)\n                _open_saved_campaign(selected, latest)\n            st.rerun()\n    details = st.session_state.get("campaign_saved_details") or {}\n    if (details.get("campaign") or {}).get("id") == selected and details.get("runs"):\n        runs = {item["id"]: item for item in sorted(details["runs"],\n                key=lambda item: str(item.get("created_at") or item.get("started_at") or ""), reverse=True)}\n        run_key = f"campaign_past_run_{selected}"\n        if st.session_state.get(run_key) not in runs:\n            st.session_state.pop(run_key, None)\n        run_numbers = {run_id: index for index, run_id in enumerate(runs, 1)}\n        chosen = st.selectbox("Past run", list(runs), key=f"campaign_past_run_{selected}",\n            format_func=lambda value: f"Run {run_numbers[value]} - {runs[value].get(\'reporting_week\') or runs[value].get(\'week\') or \'Week unavailable\'} - {runs[value].get(\'status\', \'saved\').replace(\'_\', \' \')}")\n        if st.button("View selected run", width="stretch", key="campaign_sidebar_run"):\n            _open_saved_campaign(selected, runs[chosen])\n            st.rerun()\n    with st.popover("Delete saved campaign"):\n        st.caption("Deletes this campaign\'s saved settings, summaries, contacts, drafts and run history.")\n        if st.button("Delete this campaign", key="campaign_delete_confirm"):\n            response = _call(api, "DELETE", f"/campaigns/{selected}")\n            if response is not None:\n                st.session_state.pop("campaign_list_cache", None)\n                _forget_deleted_campaign(selected)\n                st.session_state.pop("campaign_saved_selection", None)\n                st.rerun()\n\n\ndef contact_phase_label(snapshot):\n    phases = snapshot.get("contact_phase_counts") or {}\n    labels = {"exact": "Searching original locations", "nearby": "Checking nearby locations",\n              "company": "Checking other locations at this company"}\n    active = [phase for phase in labels if int(phases.get(phase) or 0) > 0]\n    if not active:\n        return "Finding and verifying contacts"\n    return labels[max(active, key=lambda phase: int(phases[phase]))]\n\n\ndef _campaign_start(api, capabilities, job_id, job, draft):\n    if not job_id or not job or job.get("status") != "complete":\n        return\n    accounts = (job.get("result_counts") or {}).get("accounts", 0)\n    st.markdown("**Build the outreach package**")\n    st.caption(f"{accounts:,} accounts · Up to {accounts * 5:,} contacts in total · Maximum 5 per company")\n    coverage = ("Search signal locations first, then nearby locations and elsewhere in the same company when needed."\n                if capabilities.get("contact_coverage") == "signal_nearby_company" else "Contacts stay within surge metros.")\n    if capabilities.get("delivery_mode") == "apollo_native":\n        st.caption(f"{coverage} Review the finished emails and approve their schedule before starting in Apollo. Test emails go only to {TEST_RECIPIENT_LABEL}.")\n    else:\n        st.caption(f"{coverage} This step prepares email drafts.")\n    record = st.session_state.get("campaign_brief_record") or {}\n    stale = _brief_context_is_stale(capabilities, draft)\n    dirty = st.session_state.get("campaign_brief_dirty", False)\n    usable = products_confirmed({"campaigns": capabilities}) and not stale\n    missing = [label for key, label in (("anthropic_configured", "company research"), ("openai_configured", "draft writing"),\n                                      ("apollo_configured", "contact sourcing")) if not capabilities.get(key)]\n    if not accounts:\n        missing = []\n    if stale:\n        st.info("Update the product brief before preparing new email drafts.")\n        if dirty:\n            st.caption("Confirm your product edits on Seller Offerings before continuing.")\n        if st.button("Review seller offerings"):\n            st.session_state.step = 3\n            st.rerun()\n    if not usable and not stale:\n        st.info("Confirm the products on Seller Offerings before building a campaign.")\n    elif record.get("status") in BRIEF_ACTIVE:\n        st.caption("You can build now. Campaign preparation will wait for the product brief to finish.")\n    if missing:\n        st.warning("Setup is needed for " + ", ".join(missing) + " before building the campaign.")\n    snapshot = st.session_state.get("campaign_run_snapshot") or {}\n    active = bool(st.session_state.get("campaign_run_id") and snapshot.get("status") not in TERMINAL)\n    preferences = snapshot_persona_preferences(st.session_state.get("buyer_personas"))\n    default_name = (record.get("brief") or {}).get("customer_name") or "Account campaign"\n    mapping_upload = uploaded_mapping_payload(draft)\n    mapping_ready = bool(mapping_upload) and capabilities.get("uploaded_topic_mapping_version", 0) >= 1\n    if not mapping_upload:\n        st.info("Upload your topic, offering and sub-offering mapping on Select Intent Topics before building.")\n    elif not mapping_ready:\n        st.info("Topic mapping preparation is temporarily unavailable. Refresh and try again.")\n    identity_parts = [job_id, record.get("id") or record.get("brief_id"), {}, _campaign_name_candidate(default_name)]\n    if persona_preferences_active(preferences):\n        identity_parts.append(preferences)\n    if mapping_upload:\n        identity_parts.append(mapping_upload)\n    created = st.session_state.get("campaign_created_for_job") or {}\n    reuse = bool(created.get("id") and created.get("signature") == fingerprint(identity_parts))\n    name, name_ready = campaign_name_input(api, default_name, reuse=reuse)\n    personas_ready = persona_preparation_ready(capabilities, preferences)\n    persona_fields = persona_preparation_fields(capabilities, preferences)\n    can_build = usable and not missing and not active and bool(name) and name_ready and mapping_ready and personas_ready\n    if st.button("Build campaign", type="primary", disabled=not can_build) and can_build:\n        identity_parts = [job_id, record.get("id") or record.get("brief_id"), {}, name]\n        if persona_preferences_active(preferences):\n            identity_parts.append(preferences)\n        identity_parts.append(mapping_upload)\n        identity = fingerprint(identity_parts)\n        if created.get("signature") != identity:\n            campaign = _call(api, "POST", "/campaigns", json={"name": name.strip(),\n                "brief_id": record.get("id") or record.get("brief_id"), "sender": {},\n                "uploaded_topic_mapping": mapping_upload, **persona_fields})\n            if campaign is None:\n                return\n            created = {"signature": identity, "id": campaign["id"], "name": campaign.get("name") or name}\n            st.session_state.campaign_created_for_job = created\n            if created["name"] != name:\n                st.session_state.notice = f"That campaign name was taken. Saved as {created[\'name\']}."\n                st.info(st.session_state.notice)\n            st.session_state.pop("campaign_list_cache", None)\n        response = _call(api, "POST", f"/campaigns/{created[\'id\']}/runs", json={"job_id": job_id})\n        if response:\n            _activate_run(created["id"], {"base_job_id": job_id, **response})\n            st.rerun()\n\n\ndef _control(api, run_id, action):\n    if action not in {"retry", "cancel", "redraft"}:\n        return\n    response = _call(api, "POST", f"/campaign-runs/{run_id}/{action}", json={}, error_state="campaign_control_error")\n    if response is not None:\n        if action in {"retry", "redraft"} and response.get("run_id"):\n            _activate_run(st.session_state.get("campaign_active_id"),\n                          {"base_job_id": st.session_state.get("campaign_run_base_job_id"), **response})\n        else:\n            st.session_state.pop("campaign_run_snapshot", None)\n            st.session_state.pop("campaign_download_signature", None)\n        st.rerun()\n\n\ndef _revenue_continue(api, job_id):\n    response = _call(api, "POST", f"/jobs/{job_id}/confirm-revenue", error_state="campaign_control_error")\n    if response is not None:\n        st.session_state.pop("campaign_run_snapshot", None)\n        st.rerun()\n\n\ndef _refresh_status():\n    st.session_state.pop("campaign_run_snapshot", None)\n    st.session_state.pop("campaign_status_error", None)\n\n\ndef recovery_active(snapshot):\n    """Recovery belongs to the same run and never grants delivery approval."""\n    return bool((snapshot.get("recovery") or {}).get("active"))\n\n\ndef _setup_blocker(message):\n    """Keep configuration and access problems actionable outside Coverage."""\n    return bool(re.search(\n        r"needs? setup|not configured|configure\\b|credentials?|API key|authenticat|unauthori[sz]ed|"\n        r"forbidden|permission denied|quota|credits?|billing|\\bHTTP (?:401|402|403)\\b",\n        str(message or ""), re.I))\n\n\ndef _preparation_notice(message):\n    safe = public_service_message(message)\n    if _setup_blocker(message) and safe in {GENERIC_MESSAGE, GENERIC_RESEARCH_MESSAGE, GENERIC_CONTACT_MESSAGE}:\n        return "Campaign preparation needs setup. Check service credentials and available credits."\n    return safe\n\n\ndef _recovery_successor(api, run_id, snapshot):\n    """Discover explicitly started recovery on ordinary renders, without a timer."""\n    counts = snapshot.get("counts") or {}\n    if snapshot.get("status") not in TERMINAL or counts.get("contacts", 0) <= counts.get("drafts", counts.get("sequences", 0)):\n        return None\n    campaign_id = snapshot.get("campaign_id") or st.session_state.get("campaign_active_id")\n    if not campaign_id:\n        return None\n    cached = st.session_state.get("campaign_recovery_discovery") or {}\n    if cached.get("run_id") != run_id or time.monotonic() - cached.get("at", 0) >= 30:\n        response = _call(api, "GET", f"/campaigns/{campaign_id}", error_state="campaign_recovery_discovery_error")\n        candidates = [item for item in (response or {}).get("runs", [])\n                      if item.get("repair_of_run_id") == run_id and item.get("id") != run_id\n                      and item.get("campaign_id", campaign_id) == campaign_id]\n        successor = max(candidates, key=lambda item: str(item.get("created_at") or ""), default=None)\n        cached = {"run_id": run_id, "at": time.monotonic(), "successor": successor}\n        st.session_state.campaign_recovery_discovery = cached\n    return cached.get("successor")\n\n\ndef _open_recovery(campaign_id, successor):\n    _activate_run(campaign_id, successor)\n    st.rerun()\n\n\ndef _run_status(api, capabilities, *, continuous=False):\n    run_id = st.session_state.get("campaign_run_id")\n    if not run_id:\n        return\n    saved = st.session_state.get("campaign_run_snapshot") or {}\n    polling = (saved.get("status") not in TERMINAL or recovery_active(saved)\n               or bool(saved.get("cancellation_pending_requests")))\n\n    @st.fragment(run_every=2 if polling else None)\n    def live():\n        access.require_session()\n        snapshot = st.session_state.get("campaign_run_snapshot") or {}\n        if polling or not snapshot:\n            response = _call(api, "GET", f"/campaign-runs/{run_id}", error_state="campaign_status_error")\n            if response:\n                st.session_state.campaign_run_snapshot = response\n                snapshot = response\n                if response.get("base_job_id"):\n                    st.session_state.campaign_run_base_job_id = response["base_job_id"]\n                if (polling and snapshot.get("status") in TERMINAL and not recovery_active(snapshot)\n                        and not snapshot.get("cancellation_pending_requests")):\n                    st.rerun()\n            elif not snapshot:\n                failure = st.session_state.get("campaign_status_error") or {}\n                st.error(public_service_message(failure.get("message") or "Campaign status is temporarily unavailable."))\n                st.button("Refresh status", on_click=_refresh_status)\n                return\n        status, counts = snapshot.get("status", "running"), snapshot.get("counts") or {}\n        recovering = recovery_active(snapshot)\n        drafts = counts.get("drafts", counts.get("sequences", 0))\n        total = counts.get("accounts_total", counts.get("accounts", 0))\n        completed = counts.get("accounts_completed", counts.get("completed", 0) + counts.get("failed", 0))\n        left, right = st.columns([4, 1])\n        stage = status if status in TERMINAL else snapshot.get("stage") or status\n        stage_label = {"queued": "Waiting to start", "waiting_for_customer_context": "Preparing the product brief",\n                    "waiting_for_data": "Waiting for current intent data", "data_pending": "Waiting for current intent data",\n                    "intent_search": "Finding current accounts", "research": "Researching companies",\n                    "role_plan": "Identifying relevant contacts", "contact_refit": "Checking contact relevance",\n                    "analysis": "Assessing account fit", "contacts": "Finding and verifying contacts",\n                    "drafts": "Writing and checking email drafts", "partial": "Campaign results ready",\n                    "complete": "Campaign results ready", "completed": "Campaign results ready",\n                    "reused": "Results already available for this week", "interrupted": "Campaign interrupted",\n                    "failed": "Campaign preparation needs attention", "cancelled": "Campaign cancelled",\n                    "recovery": "Finishing campaign preparation",\n                    "cancelling": "Stopping campaign preparation"}\n        if status == "awaiting_revenue_confirmation":\n            stage = status\n            stage_label[stage] = "Confirm revenue research to continue"\n        label = stage_label.get(stage, str(stage).replace("_", " ").capitalize())\n        if stage == "contacts":\n            label = contact_phase_label(snapshot)\n        if recovering:\n            label = "Finishing campaign preparation"\n        if snapshot.get("cancellation_pending_requests"):\n            label = "Cancelling — finishing the current request"\n        if status in {"complete", "completed"} and not drafts and total:\n            label = "Finished without email sequences"\n        left.markdown(f"**{label}**")\n        elapsed = max(0, int(snapshot.get("elapsed_seconds") or 0))\n        minutes, seconds = divmod(elapsed, 60)\n        left.caption(f"Elapsed {minutes:,}m {seconds:02d}s" +\n                     (f" - reporting week {snapshot[\'reporting_week\']}" if snapshot.get("reporting_week") else ""))\n        settling = bool(snapshot.get("cancellation_pending_requests"))\n        if status not in TERMINAL or recovering or settling:\n            cancel_control(api, f"/campaign-runs/{run_id}/cancel", f"campaign_{run_id}", label="Cancel campaign",\n                           cancelling=status == "cancelling" or settling)\n        else:\n            cancel_control(api, "", f"campaign_{run_id}", terminal=True)\n        ready_accounts = counts.get("ready_accounts")\n        labels = ["Accounts ready", "Verified contacts", "Emails ready"] if ready_accounts is not None else ["Accounts processed", "Contacts", "Email sequences ready"]\n        values = [f"{ready_accounts:,}", f"{counts.get(\'contacts\', 0):,}", f"{drafts * 3:,}"] if ready_accounts is not None else [f"{completed:,} / {total:,}", f"{counts.get(\'contacts\', 0):,}", f"{drafts:,}"]\n        for column, metric_label, value in zip(st.columns(3), labels, values):\n            column.metric(metric_label, value)\n        if status not in TERMINAL or recovering:\n            if recovering:\n                recovery = snapshot.get("recovery") or {}\n                recovery_total = recovery.get("total", 0)\n                if recovery_total:\n                    st.progress(min(1.0, max(0.0, recovery.get("completed", 0) / recovery_total)),\n                                text="Finishing campaign preparation")\n                st.caption("Available results are kept while campaign preparation finishes.")\n            elif snapshot.get("mode") == "redraft":\n                recovery_total = counts.get("draft_recovery_total", 0)\n                recovery_completed = counts.get("draft_recovery_completed", 0)\n                if recovery_total:\n                    st.progress(min(1.0, recovery_completed / recovery_total),\n                                text="Finishing campaign preparation")\n            elif total:\n                st.progress(min(1.0, completed / total))\n        if st.session_state.get("campaign_control_error"):\n            st.error(public_service_message(st.session_state.campaign_control_error["message"]))\n        if st.session_state.get("campaign_status_error"):\n            st.warning(public_service_message(st.session_state.campaign_status_error["message"]) +\n                       " Showing the last confirmed campaign update.")\n            st.button("Refresh status", on_click=_refresh_status)\n        if status == "awaiting_revenue_confirmation" and snapshot.get("base_job_id"):\n            pending = snapshot.get("revenue_pending") or {}\n            st.warning(f"Revenue research needs confirmation for {pending.get(\'uncached_domains\', \'many\')} new company checks before proceeding. Research charges apply.")\n            st.button("Continue revenue research", key=f"revenue_{run_id}", on_click=_revenue_continue,\n                      args=(api, snapshot["base_job_id"]))\n        raw_reason = snapshot.get("error") or (snapshot.get("message") if status == "failed" else "")\n        reason = _preparation_notice(raw_reason) if status == "failed" or _setup_blocker(raw_reason) else ""\n        if reason:\n            st.error(reason)\n        for raw_warning in dict.fromkeys(snapshot.get("warnings") or []):\n            warning = _preparation_notice(raw_warning)\n            if warning and warning != reason and _setup_blocker(raw_warning):\n                st.warning(warning)\n        if status not in TERMINAL or recovering or settling:\n            return\n        complete = status in {"complete", "completed"}\n        if not drafts and total:\n            st.caption("No outreach emails are available for this selection.")\n        if not continuous:\n            st.caption("Email sequences for Day 1, Day 4 and Day 7. Schedule and delivery status appear below."\n                   if drafts and capabilities.get("delivery_mode") == "apollo_native" else\n                   "Email drafts for Day 1, Day 4 and Day 7. Test sending is available below."\n                   if drafts and capabilities.get("sending_mode") == "test_only" else\n                   "Email drafts for Day 1, Day 4 and Day 7. No emails are sent." if drafts else "Email drafts only. No emails are sent.")\n        if snapshot.get("source_available", False):\n            signature = fingerprint([run_id, snapshot.get("export_version", 0), "outreach-export-v2"])\n            full_package = complete and bool(drafts)\n            build = st.session_state.get("campaign_build_snapshot") or {}\n            if continuous and build.get("download_error"):\n                st.caption("Your campaign is saved. Prepare its download below.")\n            if continuous and build.get("export_ready", True) and st.session_state.get("campaign_download_signature") != signature and st.session_state.get("campaign_download_attempt") != signature:\n                st.session_state.campaign_download_attempt = signature\n                with st.spinner("Preparing your campaign download…"):\n                    response = api("GET", f"/campaign-runs/{run_id}/excel", timeout=60, error_state="campaign_export_error")\n                if response is not None:\n                    st.session_state.campaign_download = response.content\n                    st.session_state.campaign_download_signature = signature\n                    st.session_state.pop("campaign_download_presentation", None)\n            if st.session_state.get("campaign_download_signature") == signature:\n                st.download_button("Download outreach package" if full_package else "Download available report", st.session_state.campaign_download, file_name="intent_to_outreach_campaign.xlsx",\n                    mime="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet", on_click="ignore", key=f"download_{run_id}", type="secondary",\n                    help="Includes account research, priorities, buying roles, contacts, email drafts and supporting evidence.")\n            elif st.button("Prepare download" if full_package else "Prepare available report", key=f"export_{run_id}", type="secondary"):\n                response = api("GET", f"/campaign-runs/{run_id}/excel", timeout=600)\n                if response is not None:\n                    st.session_state.campaign_download = response.content\n                    st.session_state.campaign_download_signature = signature\n                    st.session_state.pop("campaign_download_presentation", None)\n                    st.rerun()\n        else:\n            st.caption("Report download is unavailable for this saved run.")\n\n    live()\n\n\ndef _review_rows(api, run_id, view, page, limit=20):\n    snapshot = st.session_state.get("campaign_run_snapshot") or {}\n    signature = fingerprint([run_id, snapshot.get("export_version", 0), view, page, limit])\n    key = f"campaign_review_rows_{view}"\n    cached = st.session_state.get(key) or {}\n    if cached.get("signature") == signature:\n        return cached["data"]\n    data = _call(api, "GET", f"/campaign-runs/{run_id}/results",\n                 params={"view": view, "offset": page * limit, "limit": limit},\n                 error_state=f"email_review_error_{run_id}")\n    if data is not None:\n        st.session_state[key] = {"signature": signature, "data": data}\n    return data\n\n\ndef _email_contact_label(row):\n    company = row.get("Company Name") or row.get("Domain") or row.get("domain") or "Company"\n    name = row.get("name") or "Contact"\n    title = str(row.get("title") or "").strip()\n    return f"{company}  |  {name}" + (f" [{title}]" if title else "")\n\n\ndef _email_preview(api, run_id):\n    page_key = f"email_review_page_{run_id}"\n    page = int(st.session_state.get(page_key, 0))\n    data = _review_rows(api, run_id, "sequences", page)\n    if data is None:\n        st.warning("Email previews are temporarily unavailable. Your drafts remain saved.")\n        return\n    rows = data.get("rows") or []\n    total = int(data.get("total") or 0)\n    if not rows:\n        st.info("No ready email sequences are available for this selection.")\n        return\n    contact_column, day_column = st.columns([3, 1])\n    index = contact_column.selectbox("Company and contact", list(range(len(rows))), key=f"email_review_contact_{run_id}_{page}",\n        format_func=lambda n: _email_contact_label(rows[n]))\n    row = rows[index]\n    location = row.get("location") or ", ".join(str(row.get(key) or "") for key in ("city", "state", "country") if row.get(key))\n    if location:\n        st.caption("Contact location: " + str(location))\n    tier = {"exact": "Signal area", "nearby": "Nearby area", "company": "Elsewhere in company"}.get(row.get("match_tier"))\n    signals = row.get("signal_metros") or ([row["metro"]] if row.get("metro") else [])\n    if tier:\n        st.caption("Found in: " + tier + (" · Signal metros: " + "; ".join(map(str, signals)) if signals else ""))\n    offering = row.get("offering") or row.get("Offering")\n    sub = row.get("sub_offering") or row.get("Sub-offering")\n    if offering:\n        st.caption("Offering: " + str(offering) + (" · " + str(sub) if sub and sub != offering else ""))\n    day = day_column.segmented_control("Email", [1, 4, 7], default=1, format_func=lambda n: f"Day {n}",\n                                      key=f"email_review_day_{run_id}_{page}_{index}") or 1\n    with st.container(border=True):\n        st.caption("Subject")\n        st.text(str(row.get(f"subject_day_{day}") or row.get(f"Subject Day {day}") or "Subject unavailable"))\n        st.text(str(row.get(f"email_day_{day}") or row.get(f"Email Day {day}") or "Email text unavailable"))\n    if total > 20:\n        previous, middle, following = st.columns([1, 3, 1])\n        if previous.button("Previous contacts", disabled=page == 0, key=f"email_review_previous_{run_id}"):\n            st.session_state[page_key] = page - 1\n            st.rerun()\n        middle.caption(f"Contacts {page * 20 + 1}–{min((page + 1) * 20, total)} of {total:,}")\n        if following.button("Next contacts", disabled=(page + 1) * 20 >= total, key=f"email_review_next_{run_id}"):\n            st.session_state[page_key] = page + 1\n            st.rerun()\n\n\ndef _coverage_rows(api, run_id, snapshot):\n    signature = fingerprint([run_id, snapshot.get("export_version", 0)])\n    cached = st.session_state.get("campaign_coverage_rows") or {}\n    if cached.get("signature") == signature:\n        return cached["rows"]\n    ready = []\n    page = 0\n    while True:\n        data = _review_rows(api, run_id, "summary", page)\n        if data is None:\n            return None\n        rows = data.get("rows") or []\n        ready.extend(row for row in rows if int(row.get("Sequences") or 0) > 0)\n        if not rows or (page + 1) * 20 >= int(data.get("total") or 0):\n            break\n        page += 1\n    st.session_state["campaign_coverage_rows"] = {"signature": signature, "rows": ready}\n    return ready\n\n\ndef _coverage_review(api, run_id, snapshot):\n    rows = _coverage_rows(api, run_id, snapshot)\n    if rows is None:\n        st.warning("Coverage is temporarily unavailable. Try again shortly.")\n        return\n    if not rows:\n        st.info("No accounts with ready emails.")\n        return\n    total = len(rows)\n    page_key = f"coverage_review_page_{run_id}"\n    page = max(0, min(int(st.session_state.get(page_key, 0)), (total - 1) // 20))\n    st.session_state[page_key] = page\n    for row in rows[page * 20:(page + 1) * 20]:\n        name = row.get("Company Name") or row.get("Domain") or "Company"\n        sequences = int(row.get("Sequences") or 0)\n        contacts = int(row.get("Contacts") or 0)\n        label = f"{name} · {sequences * 3:,} emails ready"\n        with st.expander(label, expanded=False):\n            st.caption(f"{contacts:,} verified contacts · {sequences:,} ready sequences")\n            reason = row.get("Skip Reason") or row.get("skip_reason") or row.get("Error")\n            if reason:\n                st.write(public_service_message(reason))\n    if total > 20:\n        previous, middle, following = st.columns([1, 3, 1])\n        if previous.button("Previous accounts", disabled=page == 0, key=f"coverage_previous_{run_id}"):\n            st.session_state[page_key] = page - 1\n            st.rerun()\n        middle.caption(f"Accounts {page * 20 + 1}–{min((page + 1) * 20, total)} of {total:,}")\n        if following.button("Next accounts", disabled=(page + 1) * 20 >= total, key=f"coverage_next_{run_id}"):\n            st.session_state[page_key] = page + 1\n            st.rerun()\n\n\ndef _final_review(api, run_id, snapshot, options):\n    drafts = (snapshot.get("counts") or {}).get("drafts", (snapshot.get("counts") or {}).get("sequences", 0))\n    choices = ["Schedule", "Emails", "Coverage"] if drafts and options.get("delivery", {}).get("enabled") else ["Emails", "Coverage"] if drafts else ["Coverage"]\n    section_key = f"campaign_result_section_{run_id}"\n    section = st.segmented_control("Review campaign", choices, default=choices[0], key=section_key) or choices[0]\n    if section == "Emails":\n        _email_preview(api, run_id)\n    elif section == "Schedule":\n        from frontend.delivery import render_delivery\n        render_delivery(api, run_id, snapshot, options.get("delivery"))\n    else:\n        _coverage_review(api, run_id, snapshot)\n\n\ndef render_campaign_workspace(api, options, draft, job_id=None, job=None, *, continuous=False):\n    _clear_sender_overrides()\n    capabilities = options.get("campaigns") or {}\n    if options.get("delivery", {}).get("enabled"):\n        capabilities = {**capabilities, "sending_mode": "test_only", "delivery_mode": options["delivery"].get("mode")}\n    if not capabilities.get("enabled"):\n        return\n    if st.session_state.get("campaign_run_id"):\n        _run_status(api, capabilities, continuous=continuous)\n        snapshot = st.session_state.get("campaign_run_snapshot") or {}\n        if (snapshot.get("status") in TERMINAL and not recovery_active(snapshot)\n                and not snapshot.get("cancellation_pending_requests")):\n            _final_review(api, st.session_state.campaign_run_id, snapshot, options)\n        base_job_id = snapshot.get("base_job_id") or st.session_state.get("campaign_run_base_job_id")\n        if not continuous and job_id and job and job.get("status") == "complete" and job_id != base_job_id:\n            panel = st.expander("Prepare another campaign", expanded=False,\n                                key="campaign_new_setup_panel", on_change="rerun")\n            if panel.open:\n                with panel:\n                    _campaign_start(api, capabilities, job_id, job, draft)\n    elif not continuous:\n        _campaign_start(api, capabilities, job_id, job, draft)\n', 'frontend.delivery': '"""Compact, explicit controls for the fixed-recipient email test schedule."""\n\nfrom datetime import date, datetime, time, timedelta, timezone\nfrom math import ceil\nimport csv\nfrom io import StringIO\nfrom zoneinfo import ZoneInfo, ZoneInfoNotFoundError\n\nimport streamlit as st\nfrom frontend import access\nfrom frontend.presentation import SENDERS, SENDER_NAMES, TEST_RECIPIENT, TEST_RECIPIENTS, TEST_RECIPIENT_LABEL\nfrom frontend.controls import cancel_control\n\n\nPAGE_SIZE = 20\nSTATUS_LABELS = {\n    "pending": "Scheduled", "scheduled": "Scheduled", "waiting": "Waiting for the earlier email",\n    "creating": "Preparing email", "drafted": "Preparing to send",\n    "blocked_timezone": "Choose a time zone", "drafting": "Preparing email", "preparing": "Preparing email",\n    "claimed": "Preparing to send", "submitting": "Submitting to Apollo", "sending": "Submitting to Apollo",\n    "queued": "Queued by Apollo", "accepted": "Queued by Apollo", "sent": "Sent", "delivered": "Delivered",\n    "opened": "Opened", "replied": "Replied", "bounced": "Bounced", "unsubscribed": "Unsubscribed",\n    "cancelled": "Cancelled", "canceled": "Cancelled", "stopped": "Stopped", "skipped": "Not scheduled",\n    "failed": "Needs attention", "blocked": "Needs attention", "uncertain": "Checking send status",\n    "ambiguous": "Checking send status", "attention": "Needs attention", "reconciling": "Checking send status",\n    "upload_pending": "Preparing schedule", "uploading": "Adding to Apollo", "needs_timezone": "Choose a time zone",\n    "paused": "Paused", "send_requested": "Send requested",\n    "awaiting_approval": "Awaiting your approval",\n}\nACTIVE_PLAN_STATES = {"active", "running", "started"}\n\n\ndef parse_time(value):\n    if isinstance(value, datetime):\n        return value if value.tzinfo else None\n    try:\n        result = datetime.fromisoformat(str(value).replace("Z", "+00:00"))\n        return result if result.tzinfo else None\n    except (TypeError, ValueError):\n        return None\n\n\ndef due_labels(item, native=False):\n    """Never silently assign a zone to an ambiguous/missing timestamp."""\n    confirmed = parse_time(item.get("confirmed_due_at"))\n    due = confirmed or parse_time(item.get("due_at"))\n    zone_name = item.get("timezone") or item.get("time_zone") or ""\n    if not due:\n        return "Time zone needed" if not zone_name else "Not scheduled", ""\n    try:\n        local = due.astimezone(ZoneInfo(zone_name))\n    except (ValueError, ZoneInfoNotFoundError):\n        return "Local time unavailable", ""\n    day = local.strftime("%a %d %b %Y")\n    if native and not (confirmed or item.get("due_at_confirmed")):\n        try:\n            start = time.fromisoformat(item.get("delivery_window_start") or "10:00")\n            end = time.fromisoformat(item.get("delivery_window_end") or "11:00")\n        except (TypeError, ValueError):\n            return "Delivery window unavailable", day\n        first = datetime.combine(local.date(), start, tzinfo=local.tzinfo)\n        last = datetime.combine(local.date(), end, tzinfo=local.tzinfo)\n        if last <= first:\n            last += timedelta(days=1)\n        first_format = "%a %d %b, %I:%M" if first.strftime("%p") == last.strftime("%p") else "%a %d %b, %I:%M %p"\n        label = first.strftime(first_format) + "–" + last.strftime("%I:%M %p")\n        return f"Planned {label} ({zone_name})", day\n    prefix = "Apollo: " if native else ""\n    return prefix + local.strftime("%a %d %b, %I:%M %p") + f" ({zone_name})", day\n\n\ndef status_label(value):\n    return STATUS_LABELS.get(value, "Status unavailable")\n\n\ndef local_send_at(day, clock, zone):\n    value = datetime.combine(day, clock, tzinfo=zone)\n    if value.astimezone(timezone.utc).astimezone(zone).replace(tzinfo=None) != value.replace(tzinfo=None):\n        raise ValueError("That local time is skipped when the clocks change. Choose another send time.")\n    if value.replace(fold=0).utcoffset() != value.replace(fold=1).utcoffset():\n        raise ValueError("That local time occurs twice when the clocks change. Choose an unambiguous send time.")\n    return value.isoformat()\n\n\ndef _polling(plan):\n    if plan.get("approval_required") and not int((plan.get("counts") or {}).get("accepted") or 0) and not plan.get("pending_operation"):\n        return False\n    if plan.get("pending_operation"):\n        return True\n    if (plan.get("background_job") or {}).get("status") in {"queued", "uploading", "waiting"}:\n        return True\n    if _native(plan):\n        counts = plan.get("counts") or {}\n        if plan.get("active"):\n            return True\n        if _native_finished(plan):\n            return False\n        return bool(plan.get("status") != "paused" and _native_remaining(plan))\n    if "active" in plan:\n        return bool(plan["active"])\n    return plan.get("status") in ACTIVE_PLAN_STATES or bool((plan.get("counts") or {}).get("queued"))\n\n\ndef _native(plan):\n    return plan.get("ownership") == "apollo"\n\n\ndef _native_finished(plan):\n    counts = plan.get("counts") or {}\n    total = int(counts.get("total") or 0)\n    return bool(total and int(counts.get("sent") or 0) + int(counts.get("stopped") or 0) >= total)\n\n\ndef _native_remaining(plan):\n    counts = plan.get("counts") or {}\n    if "scheduled" in counts or "queued" in counts:\n        return int(counts.get("scheduled") or 0) + int(counts.get("queued") or 0)\n    return max(0, int(counts.get("accepted") or 0) - sum(int(counts.get(key) or 0) for key in ("sent", "stopped", "attention")))\n\n\ndef _native_incomplete(value):\n    return bool(value.get("partial") or value.get("status") in {"attention", "blocked", "uncertain", "partial"}\n                or any(_native_incomplete(group) for group in value.get("groups") or []))\n\n\ndef account_options(accounts):\n    values = {}\n    for item in accounts or []:\n        if isinstance(item, str):\n            values[item] = item\n        elif isinstance(item, dict) and item.get("domain"):\n            domain = item["domain"]\n            company = item.get("company") or item.get("name") or domain\n            values[domain] = f"{company} ({domain})" if company != domain else domain\n    return dict(sorted(values.items(), key=lambda item: item[1].casefold()))\n\n\ndef _call(api, method, path, key, **kwargs):\n    st.session_state.pop(key, None)\n    response = api(method, path, error_state=key, **kwargs)\n    if response is None:\n        return None\n    if getattr(response, "ok", True) is False:\n        detail = response.json().get("detail")\n        st.session_state[key] = {"message": detail if isinstance(detail, str) else "This action could not finish. Try again."}\n        return None\n    return response.json()\n\n\ndef _error(key, fallback=None):\n    value = st.session_state.get(key) or {}\n    if value or fallback:\n        st.error(str(value.get("message") or fallback))\n\n\ndef _notice(run_id):\n    notice = st.session_state.pop(f"delivery_notice_{run_id}", None)\n    if notice:\n        st.info(notice)\n\n\ndef _action(api, run_id, path, payload=None, notice=None, method="POST", invalidate_run=False):\n    key = f"delivery_action_error_{run_id}"\n    result = _call(api, method, path, key, json=payload or {})\n    if result is not None:\n        if invalidate_run:\n            st.session_state.pop("campaign_run_snapshot", None)\n        st.session_state[f"delivery_notice_{run_id}"] = notice if notice is not None else "Schedule updated."\n        st.rerun()\n    _error(key)\n\n\ndef _recipients_match(options):\n    reported = options.get("test_recipients") or [options.get("test_recipient")]\n    return bool(TEST_RECIPIENTS) and set(reported) == set(TEST_RECIPIENTS)\n\n\ndef _ready(options):\n    # The server also enforces these values. A conflicting older response must\n    # never expose an enabled send control in this client.\n    locked = _recipients_match(options)\n    if options.get("mode") == "apollo_native":\n        senders = options.get("senders") or []\n        addresses = [item.get("email") if isinstance(item, dict) else item for item in senders]\n        locked = locked and bool(addresses) and set(addresses) == set(SENDERS)\n    else:\n        locked = locked and options.get("sender") in SENDERS\n    return bool(options.get("ready")) and locked\n\n\ndef _can_queue(options):\n    # The backend must explicitly support a durable job with the approved\n    # envelope; an unavailable or unverified transport alone is not enough.\n    return bool(options.get("can_queue") is True\n                and options.get("mode") == "apollo_native"\n                and options.get("autonomous_verified") is True\n                and _ready({**options, "ready": True}))\n\n\ndef _cooldown_until(plan, options):\n    now = datetime.now(timezone.utc)\n    values = [options.get("next_retry_at"), plan.get("next_retry_at"),\n              (options.get("cooldown") or {}).get("next_retry_at"),\n              (plan.get("background_job") or {}).get("next_retry_at")]\n    for group in plan.get("groups") or []:\n        if group.get("superseded_for_utc"):\n            continue\n        values.append(group.get("next_retry_at"))\n        for field in ("sync_failure", "failure", "recovery_failure"):\n            failure = group.get(field) or {}\n            if failure.get("code") == "apollo_cooldown" or failure.get("status_code") == 429:\n                values.append(failure.get("next_retry_at"))\n    future = [instant for value in values if (instant := parse_time(value)) and instant > now]\n    return max(future) if future else None\n\n\ndef _current_setup(api, run_id, plan, initial):\n    key = f"delivery_setup_snapshot_{run_id}"\n    saved = st.session_state.get(key) or {"options": initial, "checked_at": 0}\n    options = saved["options"]\n    # Refresh a blocked connection after its reported cooldown, not on every\n    # five-second plan poll. A successful check never approves or sends emails.\n    if options.get("code") == "apollo_cooldown" and not _cooldown_until(plan, options):\n        now = datetime.now(timezone.utc).timestamp()\n        if now - saved.get("checked_at", 0) >= 60:\n            result = _call(api, "GET", "/delivery/options", f"delivery_setup_error_{run_id}")\n            saved = {"options": result if result is not None else options, "checked_at": now}\n            st.session_state[key] = saved\n            options = saved["options"]\n    return options\n\n\ndef _setup_notice(options, plan=None):\n    if not _ready(options):\n        if _can_queue(options):\n            return\n        if options.get("code") == "apollo_cooldown" and _recipients_match(options):\n            st.info("Apollo scheduling is temporarily unavailable because of its API request limit.")\n            until = _cooldown_until(plan or {}, options)\n            if until:\n                # Round up rather than suggesting a retry before the deadline.\n                shown = until.astimezone(timezone.utc)\n                if shown.second or shown.microsecond:\n                    shown = shown.replace(second=0, microsecond=0) + timedelta(minutes=1)\n                st.caption("Next availability check: " + shown.strftime("%d %b %Y, %H:%M UTC") + ".")\n            else:\n                st.caption("Checking Apollo availability automatically. You can also check again below.")\n            st.caption("After Apollo is available, update any expired proposed dates, review the schedule, then approve.")\n            return\n        native = options.get("mode") == "apollo_native"\n        fallback = ("Email sending needs setup. Check the approved sender mailboxes in Apollo." if native else\n                    "Email sending needs setup. Connect the authorized sender in Apollo before starting.")\n        reason = options.get("reason") or fallback\n        if not _recipients_match(options):\n            reason = "Sending is blocked because the test recipient or sender does not match the approved addresses."\n        st.warning(reason)\n        if native:\n            st.caption("You can review the emails here. Emails not yet accepted by Apollo remain unscheduled until setup is complete.")\n        else:\n            st.caption("You can still review and prepare the schedule. Sending begins only after setup is ready and you explicitly start the schedule or choose Send now.")\n\n\ndef _native_controls(api, run_id, plan, options):\n    counts = plan.get("counts") or {}\n    job = plan.get("background_job") or {}\n    job_status = job.get("status")\n    total = int(counts.get("total") or 0)\n    accepted = int(counts.get("accepted") or 0)\n    sent = int(counts.get("sent") or 0)\n    pending = int(counts.get("pending_handoff") or 0)\n    attention = int(counts.get("attention") or 0)\n    stopped = int(counts.get("stopped") or 0)\n    pending_operation = plan.get("pending_operation") or {}\n    operation = bool(pending_operation)\n    incomplete = _native_incomplete(plan)\n    stalled = [group for group in plan.get("groups") or [] if group.get("status") in {"blocked", "uncertain", "needs_timezone"}]\n    ready_to_continue = bool(plan.get("can_retry") and stalled\n                             and all(group.get("schedule_confirmed") and not group.get("failure") for group in stalled))\n    if plan.get("approval_required"):\n        st.markdown("**Proposed email schedule**")\n        st.caption("Review this campaign’s test copies and schedule before starting in Apollo." if not accepted else\n                   f"{pending:,} unsubmitted test copies await approval. The {accepted:,} already accepted copies keep their current schedule.")\n        summaries = plan.get("sender_summary") or []\n        if summaries:\n            for column, sender in zip(st.columns(len(summaries)), summaries):\n                column.markdown(f"**{sender.get(\'name\') or SENDER_NAMES.get(sender.get(\'email\')) or \'Sender\'}**")\n                column.caption(f"{int(sender.get(\'accounts\') or 0):,} companies · {int(sender.get(\'ready_contacts\') or 0):,} contacts")\n        if plan.get("schedule_stale"):\n            st.info("Some proposed dates have passed. Update them and review the new schedule before approving.")\n            if st.button("Update proposed dates", key=f"delivery_refresh_dates_{plan[\'id\']}"):\n                _action(api, run_id, f"/delivery/plans/{plan[\'id\']}/refresh-schedule", notice="Proposed dates updated. Review them before approving.")\n        if _can_queue(options):\n            st.caption("Reviewed dates are the earliest planned times. If Apollo or a mailbox reaches its limit, emails move to the next allowed local sending window; follow-up spacing is preserved.")\n        can_approve = _ready(options) or _can_queue(options)\n        if not can_approve:\n            if st.button("Check Apollo availability", key=f"delivery_check_setup_{plan[\'id\']}"):\n                st.rerun()\n        approval_label = "Approve & queue in Apollo" if _can_queue(options) and not _ready(options) else "Approve & start in Apollo"\n        if st.button(approval_label, type="primary", key=f"delivery_approve_{plan[\'id\']}",\n                     disabled=not can_approve or not plan.get("can_start") or not plan.get("approval_token") or bool(plan.get("schedule_stale"))):\n            approval = {"approval_token": plan["approval_token"]}\n            if _can_queue(options):\n                approval["background_policy"] = "next-local-window-v1"\n            _action(api, run_id, f"/delivery/plans/{plan[\'id\']}/start", approval, notice="")\n        return\n    if operation:\n        if pending_operation.get("kind") == "pause":\n            st.markdown("**Pause requested**")\n            st.caption("The remaining upload is paused. Already accepted emails may still send until Apollo confirms the pause.")\n        else:\n            st.markdown("**Confirming schedule changes with Apollo**")\n            st.caption("The existing schedule remains in effect until the change is confirmed.")\n    elif job_status == "paused":\n        st.markdown("**Schedule paused**")\n    elif job_status in {"queued", "uploading", "waiting"}:\n        st.markdown("**Submitted**")\n    elif job_status == "attention":\n        st.markdown("**Schedule needs attention**")\n    elif ready_to_continue:\n        st.markdown("**Ready to continue campaign**")\n    elif plan.get("retry_waiting"):\n        st.markdown("**Submitted**")\n    elif pending and plan.get("active"):\n        st.markdown("**Submitted**")\n    elif incomplete:\n        st.markdown("**Schedule needs attention**")\n    elif plan.get("status") == "paused":\n        st.markdown("**Schedule paused**")\n    elif total and sent + stopped >= total:\n        st.markdown("**Schedule finished**")\n    elif pending:\n        st.markdown("**Submitted**")\n    elif attention:\n        st.markdown("**Schedule needs attention**")\n    elif accepted:\n        st.markdown("**Scheduled in Apollo**")\n    else:\n        st.markdown("**Submitted**")\n    if operation:\n        pass\n    elif job_status in {"queued", "uploading", "waiting"}:\n        pass\n    elif job_status == "paused":\n        st.caption("Resume the schedule when you are ready.")\n    elif ready_to_continue:\n        st.caption("The sending windows are verified. Continue this approved campaign when you are ready.")\n    elif plan.get("retry_waiting"):\n        pass\n    elif pending and plan.get("active"):\n        pass\n    elif incomplete:\n        st.caption("Scheduling is incomplete or still needs confirmation. Review the sender details below; accepted emails and confirmed delivery history remain available.")\n    elif _native_finished(plan):\n        st.caption("No emails remain scheduled. Confirmed outcomes are available in History.")\n    elif accepted and plan.get("status") == "paused":\n        st.caption("Accepted emails remain in Apollo. Sending is paused.")\n    elif accepted and _native_remaining(plan):\n        pass\n    elif accepted:\n        st.caption("Accepted emails are recorded in History. Review any emails that need attention before continuing.")\n    summaries = plan.get("sender_summary") or []\n    if summaries:\n        with st.container(border=True):\n            columns = st.columns(min(3, len(summaries)))\n            for index, sender in enumerate(summaries):\n                with columns[index % len(columns)]:\n                    email = sender.get("email") or ""\n                    st.markdown(f"**{sender.get(\'name\') or SENDER_NAMES.get(email) or \'Sender\'}**")\n                    st.caption(f"{int(sender.get(\'accounts\') or 0):,} companies · {int(sender.get(\'ready_contacts\') or 0):,} ready contacts")\n                    st.caption(f"{int(sender.get(\'accepted\') or 0):,} accepted · {int(sender.get(\'sent\') or 0):,} sent")\n                    if sender.get("error") and sender.get("status") not in {"upload_pending", "uploading", "queued", "waiting"}:\n                        st.warning(sender["error"])\n    st.caption(f"{accepted:,} accepted in total · {sent:,} confirmed sent · {stopped:,} stopped")\n    if attention and not ready_to_continue:\n        if stalled:\n            st.warning(f"{len(stalled)} sender schedule(s) need attention; {attention:,} test copies are affected. See the sender details above.")\n        else:\n            st.warning(f"{attention:,} test copies need attention. Open an email below to see the reason.")\n    if plan.get("error"):\n        st.error(plan["error"])\n    actions = [("can_pause", "Pause schedule", "pause", "Pause requested. The schedule changes only after Apollo confirms it."),\n               ("can_resume", "Resume schedule", "start", ""),\n               ("can_retry", "Continue approved campaign" if ready_to_continue else "Retry scheduling", "retry", "")]\n    for capability, label, endpoint, notice in actions:\n        if plan.get(capability) and st.button(label, disabled=operation or (capability != "can_pause" and not (_ready(options) or _can_queue(options))),\n                                             key=f"delivery_native_{endpoint}_{plan[\'id\']}"):\n            _action(api, run_id, f"/delivery/plans/{plan[\'id\']}/{endpoint}", notice=notice)\n\n\ndef _plan_controls(api, run_id, plan, options):\n    if _native(plan):\n        _native_controls(api, run_id, plan, options)\n        return\n    status = plan.get("status", "paused")\n    counts = plan.get("counts") or {}\n    pending = int(counts.get("pending") or 0)\n    if status in ACTIVE_PLAN_STATES and (pending or counts.get("queued")):\n        st.markdown("**Test schedule is running**")\n        st.caption("Emails will be submitted at their scheduled times while the service is running. A reply, bounce or unsubscribe stops later emails for that contact.")\n        if st.button("Pause schedule", key=f"delivery_pause_{plan[\'id\']}"):\n            _action(api, run_id, f"/delivery/plans/{plan[\'id\']}/pause", notice="Schedule paused. Emails already submitted to Apollo may still be sent.")\n    elif not pending and counts.get("queued"):\n        st.markdown("**Waiting for delivery confirmation**")\n    elif status == "complete" or not pending and counts.get("total"):\n        st.markdown("**Schedule finished**" if not counts.get("attention") else "**Schedule needs attention**")\n    else:\n        st.markdown("**Schedule paused**")\n        st.caption("Review the schedule, then start when you are ready. You can also send the next eligible email now.")\n        label = "Resume test schedule" if plan.get("started_at") else "Start test schedule"\n        if st.button(label, disabled=not _ready(options) or not pending or bool(plan.get("unresolved")), key=f"delivery_start_{plan[\'id\']}"):\n            _action(api, run_id, f"/delivery/plans/{plan[\'id\']}/start", notice="Test schedule started. Upcoming emails will go only to the test inbox.")\n    if counts.get("attention"):\n        st.warning(f"{int(counts[\'attention\']):,} email(s) need attention. Open History below to see the reason before taking another action.")\n    sent = int(counts.get("sent") or 0)\n    queued = int(counts.get("queued") or 0)\n    stopped = int(counts.get("stopped") or 0)\n    st.caption(f"{pending:,} scheduled · {queued:,} awaiting confirmation · {sent:,} sent · {stopped:,} stopped")\n    if plan.get("error"):\n        st.error(plan["error"])\n\n\ndef _timezone_choices(plan, options, unresolved):\n    overrides = dict(plan.get("timezone_overrides") or {})\n    zones = [value for value in options.get("timezones") or [] if isinstance(value, str)]\n    locations = {str(item.get("timezone_key") or item.get("metro") or ""): item\n                 for item in unresolved if isinstance(item, dict)}\n    for key, item in sorted(locations.items()):\n        label = item.get("location_label") or item.get("metro") or "unspecified location"\n        if item.get("can_select_timezone") is False:\n            st.caption(f"{item.get(\'contact_name\') or \'Contact\'}: {item.get(\'reason\') or \'Location unavailable.\'}")\n            continue\n        current = overrides.get(key)\n        selected = st.selectbox(f"Time zone for {label}", zones,\n            index=zones.index(current) if current in zones else None, placeholder="Choose the contact\'s local time zone",\n            key=f"delivery_zone_{plan[\'id\']}_{key}")\n        if selected:\n            overrides[key] = selected\n    return overrides\n\n\ndef _schedule_settings(api, run_id, plan, options):\n    native = _native(plan)\n    accounts = account_options(plan.get("accounts"))\n    unresolved = plan.get("unresolved") or plan.get("unresolved_timezones") or []\n    if unresolved:\n        st.warning("Some contact locations need a time zone or a complete location before their emails can be scheduled. Check Schedule settings.")\n    panel = st.expander("Schedule settings", expanded=False, key=f"delivery_settings_{plan[\'id\']}", on_change="rerun")\n    if not panel.open:\n        return\n    with panel:\n        counts = plan.get("counts") or {}\n        can_edit = plan.get("can_edit", plan.get("status") == "paused" and\n                            not any(counts.get(key) for key in ("sent", "queued", "stopped", "attention")))\n        if not can_edit:\n            if native and plan.get("can_update_timezones") and unresolved:\n                st.caption("Choose time zones for the remaining emails. Emails already accepted keep their schedule.")\n                with st.form(f"delivery_zones_form_{plan[\'id\']}"):\n                    overrides = _timezone_choices(plan, options, unresolved)\n                    if st.form_submit_button("Save time zones"):\n                        _action(api, run_id, f"/delivery/plans/{plan[\'id\']}", {"timezone_overrides": overrides}, method="PATCH",\n                                notice="Time zones submitted. Scheduling continues for eligible emails.")\n                return\n            st.caption("Emails already accepted by Apollo keep their schedule. Open an upcoming email to see its available controls."\n                       if native else "The schedule has started. Pause it to change individual upcoming emails; emails already submitted remain in the history.")\n            return\n        current_domains = plan.get("selected_domains") or list(accounts)\n        current_domains = [domain for domain in current_domains if domain in accounts]\n        try:\n            initial_date = date.fromisoformat(str(plan.get("local_start_date")))\n        except (TypeError, ValueError):\n            initial_date = None\n        try:\n            initial_time = time.fromisoformat(str(plan.get("local_send_time") or options.get("local_send_time") or "10:00"))\n        except (TypeError, ValueError):\n            initial_time = time(10, 0)\n        with st.form(f"delivery_settings_form_{plan[\'id\']}"):\n            selected = st.multiselect("Companies in schedule", list(accounts), default=current_domains,\n                                      format_func=lambda value: accounts[value], key=f"delivery_include_{plan[\'id\']}")\n            st.caption("This selection controls which companies\' drafts are scheduled. The Company filter below only changes what you see.")\n            left, middle, right = st.columns([1, 1, 1])\n            start = left.date_input("Start on or after", value=initial_date, key=f"delivery_start_date_{plan[\'id\']}", help="Leave blank to use the next available date in each contact\'s time zone.")\n            if native:\n                hour = middle.selectbox("Local delivery window", list(range(23)), index=min(initial_time.hour, 22),\n                    format_func=lambda value: f"{value:02d}:00–{value + 1:02d}:00", key=f"delivery_local_hour_{plan[\'id\']}")\n                local_time = time(hour, 0)\n            else:\n                local_time = middle.time_input("Local send time", value=initial_time, key=f"delivery_local_time_{plan[\'id\']}")\n            window = right.selectbox("Sending days", ["weekdays", "daily"],\n                                     index=0 if plan.get("window", "weekdays") == "weekdays" else 1,\n                                     format_func=lambda value: "Weekdays" if value == "weekdays" else "Every day",\n                                     key=f"delivery_window_{plan[\'id\']}")\n            st.caption("Day 1, Day 4 and Day 7, within the selected delivery window in each contact\'s location. Apollo confirms the delivery dates; weekday schedules skip weekends."\n                       if native else "Day 1, Day 4 and Day 7, at the selected local time in each contact\'s location. Weekend dates move to the next weekday when Weekdays is selected.")\n            overrides = _timezone_choices(plan, options, unresolved)\n            if st.form_submit_button("Save schedule", disabled=not accounts):\n                if not selected:\n                    st.error("Select at least one company for the schedule.")\n                else:\n                    _action(api, run_id, f"/delivery/plans/{plan[\'id\']}",\n                        {"selected_domains": selected, "local_start_date": start.isoformat() if start else None,\n                         "local_send_time": local_time.strftime("%H:%M"), "window": window,\n                         "timezone_overrides": overrides}, method="PATCH",\n                        notice="Schedule changes requested. Check the times and acceptance status below." if native else\n                               "Schedule updated and paused. Review the confirmed times before starting.")\n\n\ndef _message(api, run_id, item, ready, native=False):\n    local, _ = due_labels(item, native)\n    company = item.get("company") or item.get("domain") or "Company"\n    person = item.get("name") or "Contact"\n    day = item.get("day", "?")\n    state = "Send requested" if item.get("manual_requested") and item.get("status") == "pending" else status_label(item.get("status"))\n    if native and item.get("status") == "accepted":\n        state = "Accepted by Apollo"\n    if native and item.get("status") == "scheduled":\n        state = "Accepted · schedule unconfirmed" if item.get("schedule_unconfirmed") else "Scheduled in Apollo"\n    label = f"{company} · {person} · Day {day} · {state}"\n    panel = st.expander(label, expanded=False, key=f"delivery_email_{item[\'id\']}", on_change="rerun")\n    if not panel.open:\n        return\n    with panel:\n        st.caption(local)\n        if item.get("schedule_delay_reason"):\n            st.caption(str(item["schedule_delay_reason"]))\n        st.write(str(item.get("subject") or "Subject unavailable"))\n        sender = item.get("sender") or "Sender to be confirmed"\n        st.caption(f"To: {item.get(\'test_recipient\') or TEST_RECIPIENT_LABEL} · From: {sender}")\n        original = item.get("original_email")\n        if original:\n            st.caption(f"Draft prepared for {person} at {company} ({original}). This person will not receive the test email.")\n        if item.get("contact_location"):\n            st.caption(f"Contact location: {item[\'contact_location\']}")\n        signals = item.get("signal_metros") or ([item["metro"]] if item.get("metro") else [])\n        if signals:\n            tier = {"exact": "Exact metro", "nearby": "Nearby", "company": "Company-wide"}.get(item.get("match_tier"))\n            st.caption("Signal metros: " + "; ".join(signals) + (f" · Contact match: {tier}" if tier else ""))\n        st.text(str(item.get("body") or "Email text unavailable"))\n        if item.get("error"):\n            st.warning(item["error"])\n        if item.get("pending_operation"):\n            st.caption("A change has been requested. Waiting for Apollo to confirm the result.")\n        elif native and item.get("status") in {"accepted", "scheduled"}:\n            st.caption("Apollo has received this email, but its schedule still needs confirmation." if item.get("schedule_unconfirmed") else\n                       "Apollo has accepted this email. It has not been confirmed as sent.")\n        elif item.get("status") in {"uncertain", "ambiguous", "reconciling", "queued", "accepted"}:\n            st.caption("Waiting for Apollo to confirm what happened. This email will not be submitted again automatically.")\n        if item.get("can_send_now"):\n            left, right = st.columns([1, 3])\n            if left.button("Send now", disabled=not ready or bool(item.get("pending_operation")), key=f"delivery_send_{item[\'id\']}",\n                           help=f"Send this email only to {item.get(\'test_recipient\') or TEST_RECIPIENT_LABEL}. Its scheduled send is removed."):\n                _action(api, run_id, f"/delivery/messages/{item[\'id\']}/send-now",\n                        notice="Send requested for the test inbox. This email will not be sent again at its scheduled time. Track the confirmed outcome in History.")\n            right.caption("Sends this email once, instead of its scheduled time.")\n        if native or item.get("status") in {"pending", "scheduled", "blocked_timezone"}:\n            if item.get("can_reschedule", not native and not item.get("manual_requested")):\n                _reschedule(api, run_id, item, native)\n            if item.get("can_cancel", not native) and not item.get("pending_operation"):\n                cancel_control(api, f"/delivery/messages/{item[\'id\']}/cancel", f"email_{item[\'id\']}",\n                    label="Cancel this and later emails", noun="this email and its later follow-ups",\n                    message="Requesting cancellation from Apollo." if native else "Removing these emails from the schedule.",\n                    confirm_note="Sent emails stay in the delivery history.",\n                    pending_note="Upcoming emails stay scheduled until Apollo confirms the cancellation." if native else\n                                 "The schedule will update after cancellation is confirmed.")\n\n\ndef _reschedule(api, run_id, item, native=False):\n    zone_name = item.get("timezone") or item.get("time_zone")\n    try:\n        zone = ZoneInfo(zone_name)\n    except (TypeError, ValueError, ZoneInfoNotFoundError):\n        st.caption("Choose this contact location\'s time zone in Schedule settings before setting a send time.")\n        return\n    due = parse_time(item.get("confirmed_due_at")) or parse_time(item.get("due_at")) or datetime.now(timezone.utc)\n    due = due.astimezone(zone)\n    with st.form(f"delivery_reschedule_{item[\'id\']}"):\n        left, right = st.columns(2)\n        selected_date = left.date_input("Send date", value=due.date(), key=f"delivery_date_{item[\'id\']}")\n        selected_time = right.time_input(f"Send time ({zone_name})", value=due.time().replace(tzinfo=None),\n                                         key=f"delivery_time_{item[\'id\']}")\n        st.caption("Later follow-ups may move to preserve the gap between emails." +\n                   (" The change takes effect only after Apollo confirms it." if native else ""))\n        if st.form_submit_button("Change send time", disabled=bool(item.get("pending_operation"))):\n            try:\n                value = local_send_at(selected_date, selected_time, zone)\n            except ValueError as exc:\n                st.error(str(exc))\n            else:\n                _action(api, run_id, f"/delivery/messages/{item[\'id\']}/reschedule", {"due_at": value},\n                        notice="Time change requested. Check the schedule for Apollo\'s confirmed delivery time." if native else\n                               "Send time updated. The confirmed local time appears in the schedule.")\n\n\ndef _agenda(api, run_id, plan, options):\n    native = _native(plan)\n    accounts = account_options(plan.get("accounts"))\n    left, right = st.columns([2, 1])\n    domain = left.selectbox("Company", [""] + list(accounts), format_func=lambda value: accounts.get(value, "All companies"),\n                            key=f"delivery_company_{plan[\'id\']}")\n    view = right.segmented_control("Emails", ["Upcoming", "History"], default="Upcoming", selection_mode="single",\n                                   key=f"delivery_view_{plan[\'id\']}") or "Upcoming"\n    scope = f"{plan[\'id\']}_{domain}_{view}"\n    page_key = f"delivery_page_{scope}"\n    page = int(st.session_state.get(page_key, 0))\n    data = _call(api, "GET", f"/delivery/plans/{plan[\'id\']}", f"delivery_agenda_error_{run_id}",\n                 params={"domain": domain, "status": view.lower(), "offset": page * PAGE_SIZE, "limit": PAGE_SIZE})\n    if data is None:\n        _error(f"delivery_agenda_error_{run_id}", "The schedule is temporarily unavailable.")\n        return\n    rows = data.get("items") or []\n    total = int(data.get("total") or 0)\n    pages = max(1, ceil(total / PAGE_SIZE))\n    if page >= pages:\n        st.session_state[page_key] = pages - 1\n        st.rerun()\n    if not rows:\n        st.caption("No upcoming emails for this selection." if view == "Upcoming" else "No delivery history for this selection yet.")\n        return\n    if native:\n        first = plan.get("delivery_window_start") or plan.get("local_send_time") or "10:00"\n        last = plan.get("delivery_window_end") or "11:00"\n        st.caption(f"Planned dates use a {first}–{last} delivery window in each contact\'s location.")\n    else:\n        st.caption("Scheduled in each contact\'s local time zone. Open an email to read it or change its send time.")\n    with st.container(height=390, border=False):\n        previous_day = None\n        for item in rows:\n            item = {**item}\n            if native:\n                group = next((group for group in plan.get("groups") or [] if group.get("id") == item.get("group_id")), None)\n                item["schedule_unconfirmed"] = _native_incomplete(group if group is not None else plan)\n            for key in ("delivery_window_start", "delivery_window_end"):\n                if key not in item and plan.get(key):\n                    item[key] = plan[key]\n            local, day = due_labels(item, native)\n            heading = day or "Time to be confirmed"\n            if heading != previous_day:\n                st.markdown(f"**{heading}**")\n                previous_day = heading\n            # The time remains visible without requiring a preview click.\n            st.caption(local)\n            approved_item = item.get("status") in {"accepted", "scheduled", "queued", "sent", "delivered"}\n            _message(api, run_id, item, _ready(options) and (not plan.get("approval_required") or approved_item), native)\n    if pages > 1:\n        previous, counter, following = st.columns([1, 3, 1])\n        if previous.button("Previous", disabled=page == 0, key=f"delivery_previous_{scope}"):\n            st.session_state[page_key] = page - 1\n            st.rerun()\n        counter.caption(f"Page {page + 1} of {pages} · {total:,} emails")\n        if following.button("Next", disabled=page + 1 >= pages, key=f"delivery_next_{scope}"):\n            st.session_state[page_key] = page + 1\n            st.rerun()\n\n\ndef schedule_csv(items, plan):\n    """Literal spreadsheet text, with every scheduled occurrence represented."""\n    output = StringIO(newline="")\n    writer = csv.writer(output)\n    writer.writerow(["Company", "Domain", "Contact", "Contact location", "Signal metros", "Location match", "Day", "Sender", "Subject", "Local schedule", "Time zone", "Status", "Test recipient"])\n    def literal(value):\n        text = str(value or "")\n        return "\'" + text if text.lstrip().startswith(("=", "+", "-", "@")) or text.startswith(("\\t", "\\r")) else text\n    for item in items:\n        local, _ = due_labels({**{k: plan[k] for k in ("delivery_window_start", "delivery_window_end") if k in plan}, **item}, _native(plan))\n        writer.writerow([literal(value) for value in (item.get("company") or item.get("domain"), item.get("domain"),\n            item.get("name"), item.get("contact_location") or "",\n            "; ".join(item.get("signal_metros") or ([item["metro"]] if item.get("metro") else [])),\n            {"exact": "Exact metro", "nearby": "Nearby", "company": "Company-wide"}.get(item.get("match_tier"), ""),\n            item.get("day"), item.get("sender"), item.get("subject"), local,\n            item.get("timezone") or item.get("time_zone"), status_label(item.get("status")), item.get("test_recipient") or TEST_RECIPIENT_LABEL)])\n    return output.getvalue().encode("utf-8-sig")\n\n\ndef _schedule_download(api, run_id, plan):\n    key = f"schedule_export_local_{plan[\'id\']}"\n    panel = st.expander("Download schedule", expanded=False, key=f"schedule_download_panel_{plan[\'id\']}", on_change="rerun")\n    if not panel.open:\n        return\n    with panel:\n        st.caption("Includes every company and email in this schedule, with local times, senders and status.")\n        if st.button("Prepare schedule download", key=f"schedule_export_prepare_{plan[\'id\']}"):\n            items, offset, expected = [], 0, None\n            with st.spinner("Preparing the full schedule…"):\n                while expected is None or offset < expected:\n                    page = _call(api, "GET", f"/delivery/plans/{plan[\'id\']}", f"schedule_export_error_{run_id}",\n                                 params={"offset": offset, "limit": 200})\n                    if page is None:\n                        break\n                    rows = page.get("items") or []\n                    expected = int(page.get("total") or 0)\n                    if not rows and offset < expected:\n                        st.session_state[f"schedule_export_error_{run_id}"] = {"message": "The schedule changed while preparing the download. Please try again."}\n                        break\n                    items.extend(rows)\n                    offset += len(rows)\n                    if offset >= expected:\n                        if len({item.get("id") for item in items}) != len(items):\n                            st.session_state[f"schedule_export_error_{run_id}"] = {"message": "The schedule changed while preparing the download. Please try again."}\n                            break\n                        st.session_state[key] = {"bytes": schedule_csv(items, plan), "rows": len(items)}\n                        st.rerun()\n            _error(f"schedule_export_error_{run_id}")\n        saved = st.session_state.get(key)\n        if saved:\n            st.download_button("Download schedule CSV", saved["bytes"], file_name="campaign_email_schedule.csv", mime="text/csv", on_click="ignore")\n            st.caption(f"{saved[\'rows\']:,} emails. Prepare again to include later status changes.")\n\n\ndef _auto_resolve_timezones(api, run_id, plan, options):\n    version = options.get("timezone_resolution")\n    unresolved = plan.get("unresolved") or plan.get("unresolved_timezones")\n    if not version or not unresolved or plan.get("pending_operation"):\n        return plan\n    key = f"delivery_timezone_attempt_{plan[\'id\']}_{version}"\n    now = datetime.now(timezone.utc).timestamp()\n    if now - st.session_state.get(key, 0) < 60:\n        return plan\n    st.session_state[key] = now\n    with st.spinner("Resolving local time zones…"):\n        resolved = _call(api, "POST", f"/delivery/plans/{plan[\'id\']}/resolve-timezones",\n                         f"delivery_timezone_error_{run_id}", json={}, timeout=600)\n    if resolved is None:\n        return plan\n    resolved = resolved.get("plan") or resolved\n    remaining = resolved.get("unresolved") or resolved.get("unresolved_timezones") or []\n    if remaining != unresolved:\n        st.session_state.pop(f"schedule_export_local_{plan[\'id\']}", None)\n    return resolved\n\n\ndef render_delivery(api, run_id, snapshot=None, capabilities=None):\n    """Render delivery independently of the source report\'s in-memory lifetime.\n\n    Missing local zones are resolved automatically for unsubmitted proposals.\n    The user explicitly approves the current proposal;\n    viewing a plan never starts it or recreates its emails.\n    """\n    if not run_id:\n        return\n    options = _call(api, "GET", "/delivery/options", f"delivery_setup_error_{run_id}")\n    if options is None:\n        _error(f"delivery_setup_error_{run_id}", "Email scheduling is temporarily unavailable.")\n        return\n    st.markdown("**Email schedule**")\n    st.info(f"Test mode · Every email goes only to {TEST_RECIPIENT_LABEL}. No emails go to prospects.")\n    st.session_state[f"delivery_setup_snapshot_{run_id}"] = {\n        "options": options, "checked_at": datetime.now(timezone.utc).timestamp()}\n    data = _call(api, "GET", "/delivery/plans", f"delivery_plans_error_{run_id}", params={"run_id": run_id})\n    if data is None:\n        _error(f"delivery_plans_error_{run_id}", "Your email schedule is temporarily unavailable.")\n        return\n    plans = data.get("plans") or []\n    plan = plans[0] if plans else None\n    if not plan:\n        _setup_notice(options)\n        _notice(run_id)\n        if options.get("mode") == "apollo_native":\n            if (snapshot or {}).get("delivery_preparing"):\n                @st.fragment(run_every=5)\n                def preparing():\n                    access.require_session()\n                    st.caption("Preparing the schedule for your ready emails…")\n                    current = _call(api, "GET", f"/campaign-runs/{run_id}", f"delivery_preparing_error_{run_id}")\n                    if current is not None and not current.get("delivery_preparing"):\n                        st.rerun()\n                    if current is None:\n                        _error(f"delivery_preparing_error_{run_id}", "Schedule updates are temporarily unavailable.")\n                preparing()\n            elif (snapshot or {}).get("can_retry_delivery"):\n                st.warning("The email schedule could not be prepared. Your ready drafts are still available.")\n                if st.button("Retry scheduling", key=f"delivery_retry_prepare_{run_id}"):\n                    _action(api, run_id, "/delivery/plans", {"run_id": run_id}, invalidate_run=True,\n                            notice="Schedule preparation requested. Check its acceptance status below.")\n            else:\n                st.caption("Prepare the proposed schedule, review the emails and times, then approve starting in Apollo.")\n                if st.button("Prepare proposed schedule", key=f"delivery_prepare_{run_id}"):\n                    _action(api, run_id, "/delivery/plans", {"run_id": run_id}, invalidate_run=True,\n                            notice="Proposed schedule prepared. Review it before approving.")\n            return\n        st.caption("Prepare a schedule from ready email drafts. It will remain paused until you start it.")\n        if st.button("Prepare test schedule", key=f"delivery_prepare_{run_id}"):\n            _action(api, run_id, "/delivery/plans", {"run_id": run_id}, notice="Schedule prepared and paused. Review it before starting.")\n        return\n    linked_key = f"delivery_linked_plan_{run_id}"\n    linked = st.session_state.get(linked_key)\n    if linked:\n        existing = _call(api, "GET", f"/delivery/plans/{linked}", f"delivery_linked_error_{run_id}", params={"limit": 1})\n        if st.button("Back to this run\'s schedule", key=f"delivery_back_{run_id}"):\n            st.session_state.pop(linked_key, None)\n            st.rerun()\n        if existing is None:\n            _error(f"delivery_linked_error_{run_id}", "The existing schedule could not be loaded.")\n            return\n        st.caption("Showing the existing schedule for these emails. Each email remains scheduled only once.")\n        plan = existing.get("plan") or existing\n    elif plan.get("already_planned"):\n        st.caption(f"{int(plan[\'already_planned\']):,} emails already have a schedule and have not been added again.")\n        references = list(dict.fromkeys(plan.get("existing_plan_ids") or []))\n        for index, identity in enumerate(references):\n            label = "Open existing schedule" + (f" {index + 1}" if len(references) > 1 else "")\n            if st.button(label, key=f"delivery_existing_{run_id}_{identity}"):\n                st.session_state[linked_key] = identity\n                st.rerun()\n        if not (plan.get("counts") or {}).get("total"):\n            return\n    polling = _polling(plan) or options.get("code") == "apollo_cooldown"\n    if options.get("mode") == "apollo_native" and not _native(plan):\n        st.caption("Earlier schedule · these emails retain their existing controls and have not been added to a new schedule.")\n\n    @st.fragment(run_every=5 if polling else None)\n    def live():\n        access.require_session()\n        current = _call(api, "GET", f"/delivery/plans/{plan[\'id\']}", f"delivery_plan_error_{run_id}", params={"limit": 1})\n        if current is None:\n            _error(f"delivery_plan_error_{run_id}", "Schedule updates are temporarily unavailable.")\n            return\n        current = current.get("plan") or current\n        current_options = _current_setup(api, run_id, current, options)\n        current = _auto_resolve_timezones(api, run_id, current, current_options)\n        still_polling = _polling(current) or current_options.get("code") == "apollo_cooldown"\n        if polling and not still_polling:\n            st.rerun()\n        _notice(run_id)\n        _setup_notice(current_options, current)\n        _plan_controls(api, run_id, current, current_options)\n        _agenda(api, run_id, current, current_options)\n        _schedule_download(api, run_id, current)\n\n    live()\n', 'frontend.builds': '"""Continuous account-to-campaign workspace; delivery needs final approval."""\nfrom copy import deepcopy\nfrom datetime import datetime, timezone\nimport time\nimport uuid\n\nimport streamlit as st\nfrom frontend import access\n\nfrom frontend.campaigns import (BRIEF_ACTIVE, BRIEF_READY, _brief_context_is_stale, _clear_sender_overrides,\n    _activate_run, public_service_message, render_campaign_workspace, contact_phase_label,\n    campaign_name_input, _campaign_name_candidate, products_confirmed, recovery_active)\nfrom frontend.controls import cancel_control\nfrom frontend.progress import duration, display_count, progress_view\nfrom frontend.state import search_payload\nfrom frontend.buyer_personas import snapshot_persona_preferences, persona_preparation_fields, persona_preparation_ready\nfrom frontend.topic_mapping import uploaded_mapping_payload\n\nTERMINAL = {"complete", "partial", "failed", "cancelled", "interrupted"}\nPREPARATION_APPROVAL = "awaiting_preparation_approval"\nSTAGES = {\n    "queued": "Preparing your campaign", "searching": "Finding matching accounts",\n    "preview": "Finding matching accounts", "week_alignment": "Checking the reporting week",\n    "exclusions": "Checking account eligibility", "details": "Applying your company filters",\n    "metros": "Checking location scores", "geography": "Checking surge locations",\n    "revenue": "Checking company revenue", "previous_week": "Comparing last week\'s signals",\n    "mapping": "Matching topics to your offerings", "excel": "Preparing account results",\n    "waiting_for_customer_context": "Preparing the product brief", "role_plan": "Identifying relevant contacts",\n    "contacts": "Finding and verifying contacts", "research": "Researching reachable companies",\n    "analysis": "Assessing account fit", "contact_refit": "Checking contact relevance",\n    "drafts": "Writing and checking emails", "building": "Preparing your campaign",\n    "packaging": "Preparing your campaign download", "recovery": "Finishing campaign preparation",\n    "waiting_for_confirmation": "Confirm revenue research to continue", "cancelling": "Cancelling campaign preparation",\n    PREPARATION_APPROVAL: "Ready to prepare your campaign",\n    "complete": "Campaign ready to review", "partial": "Available campaign results are ready",\n    "failed": "Campaign preparation needs attention", "cancelled": "Campaign preparation cancelled",\n    "interrupted": "Campaign preparation interrupted",\n}\n\n\ndef enabled(options):\n    return bool((options.get("campaign_builds") or {}).get("enabled"))\n\n\ndef _read(api, method, path, **kwargs):\n    response = api(method, path, **kwargs)\n    return response.json() if response is not None and getattr(response, "ok", True) else None\n\n\ndef _working(snapshot):\n    return (snapshot.get("status") not in TERMINAL | {PREPARATION_APPROVAL}\n            or recovery_active(snapshot.get("campaign") or snapshot)\n            or bool(snapshot.get("cancellation_pending_requests")))\n\n\ndef _polling(snapshot, build_id):\n    cancellation = st.session_state.get(f"cancel_state_build_{build_id}") or {}\n    return _working(snapshot) or (snapshot.get("status") not in TERMINAL\n                                 and cancellation.get("phase") in {"requesting", "sent"})\n\n\ndef render_build_action(api, options, draft):\n    _clear_sender_overrides()\n    record = st.session_state.get("campaign_brief_record") or {}\n    caps = options.get("campaigns") or {}\n    dirty = bool(st.session_state.get("campaign_brief_dirty"))\n    stale = _brief_context_is_stale(caps, draft)\n    # Products must be explicitly confirmed for the current seller source and topic mapping.\n    usable = products_confirmed(options)\n    configured = all(caps.get(key) for key in ("anthropic_configured", "openai_configured", "apollo_configured"))\n    preferences = snapshot_persona_preferences(st.session_state.get("buyer_personas"))\n    fields = {"brief_id": record.get("id") or record.get("brief_id"), "search": search_payload(draft),\n              **persona_preparation_fields(caps, preferences)}\n    mapping_upload = uploaded_mapping_payload(draft)\n    mapping_ready = bool(mapping_upload) and caps.get("uploaded_topic_mapping_version", 0) >= 1\n    if mapping_upload:\n        fields["uploaded_topic_mapping"] = mapping_upload\n    default_name = (record.get("brief") or {}).get("customer_name") or "Account campaign"\n    pending = st.session_state.get("campaign_build_submission") or {}\n    reuse = bool(pending.get("request_id") and pending.get("uncertain", True) and pending.get("body") == {\n        "name": _campaign_name_candidate(default_name), **fields})\n    name, name_ready = campaign_name_input(api, default_name, reuse=reuse)\n    if not usable:\n        st.info("Confirm the products on Seller Offerings before building.")\n    if not configured:\n        st.warning("Campaign research and contact sourcing need setup before you can build.")\n    if not mapping_upload:\n        st.info("Upload your topic, offering and sub-offering mapping on Select Intent Topics before building.")\n    elif not mapping_ready:\n        st.info("Topic mapping preparation is temporarily unavailable. Refresh and try again.")\n    personas_ready = persona_preparation_ready(caps, preferences)\n    can_start = usable and configured and bool(name) and name_ready and mapping_ready and bool(draft.get("topics")) and personas_ready\n    if st.button("Build campaign", type="primary", disabled=not can_start, key="continuous_build_start") and can_start:\n        body = {"name": name, **fields}\n        if pending.get("body") != body:\n            pending = {"request_id": uuid.uuid4().hex, "body": deepcopy(body)}\n            st.session_state.campaign_build_submission = pending\n        # A lost response may already have created this campaign; recover that exact request.\n        pending["uncertain"] = True\n        result = _read(api, "POST", "/campaign-builds", json={"request_id": pending["request_id"], **body},\n                       error_state="campaign_build_start_error")\n        error_status = (st.session_state.get("campaign_build_start_error") or {}).get("status")\n        if result is None and error_status is not None and 400 <= error_status < 500:\n            pending["uncertain"] = False\n        if result:\n            if result.get("name") and result["name"] != body["name"]:\n                st.session_state.notice = f"That campaign name was taken. Saved as {result[\'name\']}."\n            st.session_state.campaign_build_id = result.get("id") or result.get("build_id")\n            st.query_params["build"] = st.session_state.campaign_build_id\n            st.session_state.campaign_build_snapshot = result\n            st.session_state.campaign_build_request = deepcopy(body)\n            for key in ("campaign_run_id", "campaign_run_snapshot", "campaign_download", "campaign_download_signature",\n                        "job_id", "job_progress_snapshot", "download", "download_signature"):\n                st.session_state.pop(key, None)\n            st.rerun()\n    error = st.session_state.get("campaign_build_start_error") or {}\n    if error:\n        st.error(public_service_message(error.get("message")))\n        st.caption("Your selections are kept. Try Build campaign again to recover the same request.")\n\n\ndef stage_label(snapshot, request):\n    status = snapshot.get("status") or "queued"\n    if status != "cancelling" and recovery_active(snapshot.get("campaign") or snapshot):\n        return "Finishing campaign preparation"\n    if status in TERMINAL or status in {"cancelling", "waiting_for_confirmation", PREPARATION_APPROVAL}:\n        return STAGES[status]\n    stage = snapshot.get("stage") or status\n    if stage == "contacts":\n        return contact_phase_label(snapshot.get("campaign") or snapshot)\n    if stage == "exclusions":\n        data = (request or {}).get("search") or {}\n        domain = bool(data.get("suppressed_domains") or data.get("suppression_list_ids"))\n        edu = bool(data.get("exclude_edu"))\n        if domain and edu:\n            return "Applying domain and education exclusions"\n        if domain:\n            return "Applying your domain exclusions"\n        if edu:\n            return "Excluding .edu domains"\n        return "Checking account eligibility"\n    return STAGES.get(stage, "Preparing your campaign")\n\n\ndef _elapsed(snapshot):\n    if isinstance(snapshot.get("elapsed_seconds"), (float, int)):\n        return snapshot["elapsed_seconds"]\n    try:\n        start = datetime.fromisoformat(str(snapshot.get("created_at")).replace("Z", "+00:00"))\n        return max(0, (datetime.now(timezone.utc) - start).total_seconds()) if start.tzinfo else None\n    except (TypeError, ValueError):\n        return None\n\n\ndef _last_update(snapshot):\n    try:\n        value = snapshot.get("last_progress_at") or snapshot.get("updated_at")\n        if isinstance(value, (int, float)):\n            updated = datetime.fromtimestamp(value, timezone.utc)\n        else:\n            updated = datetime.fromisoformat(str(value).replace("Z", "+00:00"))\n        return max(0, (datetime.now(timezone.utc) - updated).total_seconds()) if updated.tzinfo else None\n    except (TypeError, ValueError, OverflowError, OSError):\n        return None\n\n\ndef _progress(snapshot, request, *, preparation_approval_required=False):\n    search = snapshot.get("search") or {}\n    campaign = snapshot.get("campaign") or {}\n    counts = campaign.get("counts") or snapshot.get("counts") or {}\n    recovering = recovery_active(campaign or snapshot)\n    if _working(snapshot):\n        st.status(stage_label(snapshot, request), state="running", expanded=False)\n    else:\n        st.markdown(f"**{stage_label(snapshot, request)}**")\n    st.caption(f"Elapsed {duration(_elapsed(snapshot))}" +\n               (f" · Reporting week {campaign[\'reporting_week\']}" if campaign.get("reporting_week") else "") +\n               (f" · Last progress update {duration(_last_update(snapshot))} ago" if _last_update(snapshot) is not None else ""))\n    if snapshot.get("run_id") or campaign:\n        matched = counts.get("accounts_total", counts.get("accounts"))\n        contacts = counts.get("contacts", 0)\n        sequences = counts.get("drafts", counts.get("sequences", 0))\n        checked = counts.get("contact_checked_accounts")\n        contactable = counts.get("contactable_accounts")\n        ready = counts.get("ready_accounts")\n        for col, label, value in zip(st.columns(3), ("Accounts with contacts", "Verified contacts", "Emails ready"),\n                                    (contactable, contacts, sequences * 3)):\n            col.metric(label, display_count(value))\n        summary = [f"{display_count(matched)} matched accounts"]\n        if checked is not None:\n            summary.append(f"{display_count(checked)} checked for contacts")\n        if ready is not None:\n            summary.append(f"{display_count(ready)} ready for outreach")\n        st.caption(" · ".join(summary))\n        completed = counts.get("accounts_completed", counts.get("completed", 0) + counts.get("failed", 0))\n        if recovering:\n            recovery = (campaign or snapshot).get("recovery") or {}\n            if recovery.get("total"):\n                st.progress(min(1.0, max(0.0, recovery.get("completed", 0) / recovery["total"])),\n                            text="Finishing campaign preparation")\n            st.caption("Available results are kept while campaign preparation finishes.")\n        elif matched:\n            st.progress(min(1.0, completed / matched), text=f"{completed:,} of {matched:,} accounts finished")\n        activity = campaign.get("activity_counts") or snapshot.get("activity_counts") or {}\n        active = []\n        for stages, label in (((\'role_plan\', \'contacts\', \'contact_refit\'), "checking contacts"),\n                              ((\'research\', \'analysis\'), "researching companies"), ((\'drafts\',), "preparing emails")):\n            count = sum(int(activity.get(stage) or 0) for stage in stages)\n            if count:\n                active.append(f"{count:,} {label}")\n        if recovering:\n            return\n        if active:\n            st.caption("In progress: " + " · ".join(active))\n        elif snapshot.get("status") not in TERMINAL | {"cancelling"}:\n            st.caption("The current step is still running. Counts update when a check finishes.")\n    else:\n        view = progress_view(search, now=time.time())\n        hints = ("Accounts that match every filter applied so far. This narrows as each filter is checked.", None, None)\n        for col, label, value, hint in zip(st.columns(3), ("Matching accounts", "Verified contacts", "Emails ready"),\n                                           (view["current"]["accounts"], None, None), hints):\n            col.metric(label, display_count(value), help=hint)\n        revenue = view.get("revenue")\n        if revenue and revenue.get("total"):\n            done, total = revenue.get("completed") or 0, revenue["total"]\n            st.progress(min(1.0, done / total), text=f"Revenue checked for {done:,} of {total:,} companies")\n        elif search.get("telemetry"):\n            finished = [stage for stage in search["telemetry"].get("stages", []) if stage.get("status") == "complete"]\n            if finished:\n                st.caption("Latest completed step: " + STAGES.get(finished[-1]["id"], "Account checks"))\n        if search.get("status") not in TERMINAL and snapshot.get("status") != "cancelling":\n            st.caption("The account search is running. You\'ll review the account count and estimated time before preparation begins."\n                       if preparation_approval_required else\n                       "The account search is running. Contact checks and email preparation will follow automatically.")\n\n\ndef _preparation_review(api, build_id, snapshot):\n    """A paused, read-only checkpoint until the displayed proposal is approved."""\n    approval = snapshot.get("preparation_approval") or {}\n    approval_id = approval.get("id")\n    error_key = f"campaign_build_preparation_error_{build_id}"\n    cancellation = st.session_state.get(f"cancel_state_build_{build_id}") or {}\n    cancelling = bool(snapshot.get("cancellation_pending_requests"))\n    can_approve = bool(approval_id and snapshot.get("can_approve_preparation")\n                       and not cancelling and not cancellation.get("phase"))\n    with st.container(border=True):\n        st.markdown("**Ready to prepare your campaign**")\n        st.write(f"Up to {display_count(approval.get(\'account_count\'))} accounts")\n        minimum, maximum = approval.get("estimate_min_minutes"), approval.get("estimate_max_minutes")\n        estimate = display_count(minimum) if minimum == maximum else f"{display_count(minimum)}–{display_count(maximum)}"\n        st.write(f"Rough time estimate: {estimate} minutes")\n        st.caption("Estimate includes finding contacts, account research and email preparation.")\n        st.caption("Waiting for your approval. Preparation has not started.")\n        # The proposal identity is part of the widget identity. If a status read\n        # replaces a stale proposal, a click on the old button cannot approve it.\n        if st.button("Approve & start preparation", type="primary", disabled=not can_approve,\n                     key=f"build_preparation_approve_{build_id}_{approval_id}") and can_approve:\n            result = _read(api, "POST", f"/campaign-builds/{build_id}/approve-preparation",\n                           json={"approval_id": approval_id}, error_state=error_key)\n            if result:\n                st.session_state.campaign_build_snapshot = result\n                st.rerun()\n            # A lost response can follow an accepted request. Reconcile with a\n            # read; never repeat an approval automatically after an error.\n            latest = _read(api, "GET", f"/campaign-builds/{build_id}", error_state="campaign_build_status_error")\n            if latest:\n                st.session_state.campaign_build_snapshot = latest\n                if latest.get("status") != PREPARATION_APPROVAL:\n                    st.session_state.pop(error_key, None)\n            st.rerun()\n        error = st.session_state.get(error_key) or {}\n        if error:\n            st.error(public_service_message(error.get("message")))\n            st.caption("Approval was not confirmed. Review the current account count and estimate before trying again.")\n        if not snapshot.get("can_approve_preparation"):\n            st.warning("The account selection needs to be checked before approval.")\n            if st.button("Check account selection", key=f"build_preparation_check_{build_id}"):\n                latest = _read(api, "GET", f"/campaign-builds/{build_id}", error_state="campaign_build_status_error")\n                if latest:\n                    st.session_state.campaign_build_snapshot = latest\n                    st.rerun()\n        cancel_control(api, f"/campaign-builds/{build_id}/cancel", f"build_{build_id}", cancelling=cancelling,\n                       confirm_note="The account report stays available. Contact sourcing and campaign preparation will not start.")\n\n\ndef _account_download(api, snapshot):\n    job_id = snapshot.get("job_id")\n    search = snapshot.get("search") or {}\n    if not job_id or search.get("status") != "complete":\n        return\n    with st.expander("Account report", expanded=False):\n        st.caption("The account report keeps all companies that passed your filters.")\n        key = f"build_account_download_{job_id}"\n        if key in st.session_state:\n            st.download_button("Download account report", st.session_state[key], file_name="intent_accounts.xlsx",\n                mime="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet", on_click="ignore")\n        elif st.button("Prepare account download", key=f"build_account_export_{job_id}"):\n            response = api("GET", f"/jobs/{job_id}/excel", timeout=600)\n            if response is not None:\n                st.session_state[key] = response.content\n                st.rerun()\n\n\ndef render_build_workspace(api, options, draft):\n    build_id = st.session_state.get("campaign_build_id")\n    saved = st.session_state.get("campaign_build_snapshot") or {}\n    polling = _polling(saved, build_id)\n    requires_approval = bool((options.get("campaign_builds") or {}).get("preparation_approval_required"))\n\n    @st.fragment(run_every=2 if polling else None)\n    def live():\n        access.require_session()\n        snapshot = st.session_state.get("campaign_build_snapshot") or {}\n        if polling or not snapshot or snapshot.get("status") == PREPARATION_APPROVAL:\n            result = _read(api, "GET", f"/campaign-builds/{build_id}", error_state="campaign_build_status_error")\n            if result:\n                st.session_state.campaign_build_snapshot = snapshot = result\n                if polling != _polling(result, build_id):\n                    st.rerun()\n            elif not snapshot:\n                st.error("Campaign progress is temporarily unavailable. Your build has not been started again.")\n                return\n        if not _working(snapshot):\n            return\n        cancel_state = st.session_state.get(f"cancel_state_build_{build_id}") or {}\n        visible = {**snapshot, "status": "cancelling"} if cancel_state.get("phase") in {"requesting", "sent"} else snapshot\n        _progress(visible, st.session_state.get("campaign_build_request") or {}, preparation_approval_required=requires_approval)\n        if st.session_state.get("campaign_build_status_error"):\n            st.warning("Live status could not refresh. Showing the last confirmed update.")\n        cancelling = snapshot.get("status") == "cancelling" or bool(snapshot.get("cancellation_pending_requests"))\n        cancel_control(api, f"/campaign-builds/{build_id}/cancel", f"build_{build_id}", cancelling=cancelling)\n        if snapshot.get("status") == "waiting_for_confirmation" and not cancelling:\n            pending = (snapshot.get("search") or {}).get("revenue_pending") or {}\n            st.warning(f"Revenue research needs confirmation for {pending.get(\'uncached_domains\', \'many\')} company checks. Research charges apply.")\n            if st.button("Continue revenue research", key=f"build_revenue_{build_id}"):\n                result = _read(api, "POST", f"/campaign-builds/{build_id}/confirm-revenue", json={}, error_state="campaign_build_action_error")\n                if result:\n                    st.session_state.campaign_build_snapshot = result\n                    st.rerun()\n        error = st.session_state.get("campaign_build_action_error") or {}\n        if error:\n            st.error(public_service_message(error.get("message")))\n\n    live()\n    snapshot = st.session_state.get("campaign_build_snapshot") or {}\n    if _working(snapshot):\n        return\n    if snapshot.get("status") == PREPARATION_APPROVAL:\n        _preparation_review(api, build_id, snapshot)\n        if st.session_state.get("campaign_build_status_error"):\n            st.warning("Build status could not refresh. Approval will be checked against the latest account selection.")\n        _account_download(api, snapshot)\n        return\n    cancel_control(api, "", f"build_{build_id}", terminal=True)\n    search = snapshot.get("search") or {}\n    if snapshot.get("job_id"):\n        st.session_state.job_id = snapshot["job_id"]\n        st.session_state.job_progress_snapshot = search\n    if snapshot.get("run_id") and snapshot.get("campaign"):\n        selected = st.session_state.get("campaign_build_selected_run")\n        if selected != snapshot["run_id"]:\n            _activate_run(snapshot.get("campaign_id"), {"base_job_id": snapshot.get("job_id"), **snapshot["campaign"]})\n            st.session_state.campaign_build_selected_run = snapshot["run_id"]\n        render_campaign_workspace(api, options, draft, job_id=snapshot.get("job_id"), job=search, continuous=True)\n    else:\n        _progress(snapshot, st.session_state.get("campaign_build_request") or {}, preparation_approval_required=requires_approval)\n        if snapshot.get("status") == "complete":\n            st.info("No accounts passed your filters. No contact sourcing or campaign research was needed.")\n        elif snapshot.get("status") == "failed" and snapshot.get("error"):\n            st.error(public_service_message(snapshot["error"]))\n    _account_download(api, snapshot)\n    with st.expander("Start another campaign", expanded=False):\n        st.caption("Your current results stay available in saved campaigns.")\n        if st.button("Return to filters", key="build_new_filters"):\n            st.query_params.pop("build", None)\n            for key in ("campaign_build_id", "campaign_build_snapshot", "campaign_build_submission", "campaign_build_selected_run",\n                        "campaign_run_id", "campaign_run_snapshot", "job_id", "job_progress_snapshot"):\n                st.session_state.pop(key, None)\n            st.session_state.step = 1\n            st.rerun()\n', 'frontend.topic_selection': '"""Website suggestions and simple topic-list imports using the existing API."""\nimport csv\nimport hashlib\nfrom io import BytesIO, StringIO\nimport re\nimport unicodedata\nfrom xml.sax.saxutils import escape\nfrom zipfile import ZIP_DEFLATED, ZipFile\n\nimport streamlit as st\n\nfrom frontend import access\nfrom frontend.campaigns import customer_website, customer_context_enabled, _clear_sender_overrides\nfrom frontend.presentation import normalize_customer_website\nfrom frontend.seller_cache import SELLER_RESEARCH_PAUSED, saved_products, persist_seller\n\n\n_GENERIC = {"business", "company", "customer", "data", "management", "platform", "product",\n            "service", "software", "solution", "technology"}\n\n\ndef _words(value):\n    value = unicodedata.normalize("NFKD", str(value)).encode("ascii", "ignore").decode().lower()\n    return re.findall(r"[a-z0-9]+", value)\n\n\ndef _singular(word):\n    if len(word) > 4 and word.endswith("ies"):\n        return word[:-3] + "y"\n    if len(word) > 4 and word.endswith("s") and not word.endswith(("ss", "is", "us", "ics")):\n        return word[:-1]\n    return word\n\n\ndef suggest_topics(brief, catalog, limit=25):\n    """Rank existing catalog labels against researched products, never invent labels."""\n    sections = [(2, brief.get("description", ""))]\n    for offering in brief.get("offerings") or []:\n        sections.extend([(5, offering.get("name", "")), (3, offering.get("description", ""))])\n        sections.extend((2, c.get("text", "")) for c in offering.get("capabilities") or [] if isinstance(c, dict))\n        for sub in offering.get("sub_offerings") or []:\n            sections.extend([(4, sub.get("name", "")), (3, sub.get("description", ""))])\n    evidence = []\n    for weight, value in sections:\n        if not isinstance(value, str):\n            continue\n        for sentence in re.split(r"[.!?;\\n]+", value):\n            words = [_singular(w) for w in _words(sentence)]\n            if words:\n                evidence.append((weight, " " + " ".join(words) + " "))\n    scores = []\n    for topic in sorted(set(catalog)):\n        variants = [topic, re.sub(r"\\([^)]*\\)", "", topic).strip()]\n        variants.extend(alias for alias in re.findall(r"\\(([^)]+)\\)", topic)\n                        if re.fullmatch(r"[A-Z][A-Z0-9]{2,7}", alias) or alias in {"AI", "VR", "AR"})\n        best = 0\n        for variant in variants:\n            words = [_singular(w) for w in _words(variant)]\n            if not words or all(w in _GENERIC or len(w) < 2 for w in words):\n                continue\n            phrase = " " + " ".join(words) + " "\n            matches = [weight for weight, text in evidence if phrase in text]\n            if matches:\n                best = max(best, 4 * max(matches) + min(len(words), 6) + min(len(matches), 4))\n        if best:\n            scores.append((best, topic))\n    return [topic for _, topic in sorted(scores, key=lambda row: (-row[0], row[1]))[:limit]]\n\n\ndef topic_template(catalog, kind="csv"):\n    rows = [["Topic"]] + [[name] for name in list(catalog)[:2]]\n    if kind == "csv":\n        output = StringIO(newline="")\n        csv.writer(output).writerows(rows)\n        return output.getvalue().encode("utf-8-sig")\n    if kind != "xlsx":\n        raise ValueError("Choose CSV or Excel.")\n    ns = "http://schemas.openxmlformats.org/spreadsheetml/2006/main"\n    rel = "http://schemas.openxmlformats.org/officeDocument/2006/relationships"\n    cells = "".join(f\'<row r="{i}"><c r="A{i}" t="inlineStr"><is><t>{escape(row[0])}</t></is></c></row>\'\n                    for i, row in enumerate(rows, 1))\n    files = {\n        "[Content_Types].xml": \'<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types">\'\n            \'<Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/>\'\n            \'<Default Extension="xml" ContentType="application/xml"/>\'\n            \'<Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/>\'\n            \'<Override PartName="/xl/worksheets/sheet1.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/></Types>\',\n        "_rels/.rels": \'<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">\'\n            f\'<Relationship Id="rId1" Type="{rel}/officeDocument" Target="xl/workbook.xml"/></Relationships>\',\n        "xl/workbook.xml": f\'<workbook xmlns="{ns}" xmlns:r="{rel}"><sheets><sheet name="Topics" sheetId="1" r:id="rId1"/></sheets></workbook>\',\n        "xl/_rels/workbook.xml.rels": \'<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">\'\n            f\'<Relationship Id="rId1" Type="{rel}/worksheet" Target="worksheets/sheet1.xml"/></Relationships>\',\n        "xl/worksheets/sheet1.xml": f\'<worksheet xmlns="{ns}"><cols><col min="1" max="1" width="55" customWidth="1"/></cols><sheetData>{cells}</sheetData></worksheet>\',\n    }\n    output = BytesIO()\n    with ZipFile(output, "w", ZIP_DEFLATED) as archive:\n        for name, value in files.items():\n            archive.writestr(name, \'<?xml version="1.0" encoding="UTF-8" standalone="yes"?>\' + value)\n    return output.getvalue()\n\n\ndef _select_topics(topics, draft):\n    current = st.session_state.get("topic_selection", draft.get("topics") or [])\n    selected = list(dict.fromkeys([*current, *topics]))\n    added = len(set(selected) - set(current))\n    st.session_state.setdefault("pending_widget_values", {})["topic_selection"] = selected\n    st.session_state.draft["topics"] = selected\n    return added\n\n\ndef _finish_generation(job, catalog, draft, website):\n    if job.get("applied") or job.get("website") != website or job.get("status") not in {"complete", "approved"}:\n        return False\n    matches = suggest_topics(job.get("brief") or {}, catalog)\n    job.update(applied=True, matches=matches)\n    if matches:\n        added = _select_topics(matches, draft)\n        st.session_state.notice = f"Added {added} matching topics. Review your selection below."\n    return True\n\n\ndef render_topic_website(api, options, draft, catalog):\n    _clear_sender_overrides()\n    website_column, action_column = st.columns([4, 1], vertical_alignment="bottom")\n    website = website_column.text_input("Generate Topics", value=customer_website(), key="campaign_website",\n        placeholder="https://example.com", help="Generate a list of topics from your website. Suggestions match your researched products and services to the topic catalog.")\n    st.session_state.campaign_context_website = website.strip()\n    persist_seller()\n    try:\n        normalized = normalize_customer_website(website)\n    except ValueError:\n        normalized = None\n    job = st.session_state.get("topic_generation") or {}\n    pending = job.get("status") == "running"\n    if SELLER_RESEARCH_PAUSED:\n        products = saved_products()\n        st.caption("Seller research is paused. Topic suggestions use the saved seller products.")\n        if action_column.button("Generate Topics", type="primary", key="generate_website_topics", disabled=not products):\n            matches = suggest_topics(products, catalog)\n            if matches:\n                added = _select_topics(matches, draft)\n                st.session_state.notice = f"Added {added} matching topics from the saved seller products."\n                st.rerun()\n            else:\n                st.info("No matching catalog topics found. Select topics below or upload a list.")\n        return\n    if action_column.button("Generate Topics", type="primary", key="generate_website_topics",\n                            disabled=not normalized or pending or not customer_context_enabled(options)):\n        response = api("POST", "/customer-briefs", json={"website": normalized, "topics": [], "mappings": [],\n            "retry": job.get("website") == normalized and job.get("status") in {"failed", "cancelled", "unavailable"}},\n            error_state="topic_generation_error")\n        if response is not None:\n            job = {**response.json(), "website": normalized, "applied": False}\n            st.session_state.topic_generation = job\n            pending = job.get("status") == "running"\n    if _finish_generation(job, catalog, draft, normalized):\n        st.rerun()\n    if pending:\n        @st.fragment(run_every=3)\n        def waiting():\n            access.require_session()\n            current = st.session_state.get("topic_generation") or {}\n            identity = current.get("brief_id") or current.get("id")\n            if not identity or current.get("status") != "running":\n                return\n            response = api("GET", f"/customer-briefs/{identity}", error_state="topic_generation_error")\n            if response is not None:\n                current = {**current, **response.json()}\n                st.session_state.topic_generation = current\n            elif (st.session_state.get("topic_generation_error") or {}).get("status") == 404:\n                current["status"] = "unavailable"\n            if current.get("status") != "running":\n                st.rerun(scope="app")\n            st.caption("Finding topics from the website…")\n            if st.session_state.get("topic_generation_error"):\n                st.caption("Checking progress again shortly.")\n        waiting()\n    elif job.get("website") == normalized and job.get("status") in {"failed", "cancelled", "unavailable"}:\n        st.warning("Topic generation didn\'t finish. Try Generate Topics again, or select topics below.")\n    elif job.get("website") == normalized and job.get("applied") and not job.get("matches"):\n        st.info("No matching catalog topics found. Select topics below or upload a list.")\n    elif st.session_state.get("topic_generation_error"):\n        st.warning("Couldn\'t start topic generation. Try again shortly.")\n\n\ndef render_topic_upload(api, draft, catalog):\n    with st.expander("Upload topic list", expanded=False, key="topic_upload_panel", on_change="rerun"):\n        csv_column, excel_column = st.columns(2)\n        csv_column.download_button("CSV template", topic_template(catalog, "csv"), "topic_template.csv",\n                                   "text/csv", on_click="ignore", key="topic_csv_template")\n        excel_column.download_button("Excel template", topic_template(catalog, "xlsx"), "topic_template.xlsx",\n            "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet", on_click="ignore", key="topic_excel_template")\n        upload = st.file_uploader("Choose or Upload File", type=["xlsx", "csv"], key="topic_list_upload",\n                                 help="One topic per row. Matching topics are added automatically.")\n        if upload is None:\n            for key in ("topic_upload_signature", "topic_upload_unmatched", "topic_upload_error", "topic_upload_match_count"):\n                st.session_state.pop(key, None)\n        else:\n            content = upload.getvalue()\n            signature = hashlib.sha256(upload.name.encode() + b"\\0" + content).hexdigest()\n            if st.session_state.get("topic_upload_signature") != signature:\n                # Each file applies once. Later manual topic edits remain in control.\n                st.session_state.topic_upload_signature = signature\n                st.session_state.pop("topic_upload_error", None)\n                st.session_state.pop("topic_upload_match_count", None)\n                st.session_state.topic_upload_unmatched = []\n                response = api("POST", "/topics/match", files={"file": (upload.name, content)},\n                               error_state="topic_upload_error")\n                if response is not None:\n                    result = response.json()\n                    st.session_state.topic_upload_unmatched = [row["input"] for row in result.get("unmatched") or []\n                        if row.get("input", "").strip().casefold() not in {"topic", "topics", "intent topic"}]\n                    matches = result.get("matched") or []\n                    st.session_state.topic_upload_match_count = len(set(matches))\n                    if matches:\n                        added = _select_topics(matches, draft)\n                        st.session_state.notice = (f"Added {added} topics from your file." if added else\n                                                   "Uploaded topics are already selected.")\n                    st.rerun()\n    # Keep failures and unmatched topics visible even when the upload panel is closed.\n    if st.session_state.get("topic_upload_error"):\n        st.error("Couldn\'t read that file. Your selected topics are kept. Use the template or retry the upload.")\n        if upload is not None and st.button("Retry upload", key="topic_upload_retry"):\n            st.session_state.pop("topic_upload_signature", None)\n            st.rerun()\n    elif st.session_state.get("topic_upload_match_count") == 0:\n        st.warning("No matching catalog topics found in this file. Your selected topics are kept.")\n    unmatched = st.session_state.get("topic_upload_unmatched") or []\n    if unmatched:\n        st.warning("Not found in the catalog: " + ", ".join(unmatched[:8]) +\n                   (f" and {len(unmatched)-8} more." if len(unmatched) > 8 else "."))\n', 'frontend.seller_cache': '"""Durable workspace seller products and frontend selections."""\nfrom copy import deepcopy\nimport hashlib\nimport json\nimport os\nfrom pathlib import Path\nimport tempfile\nimport threading\n\nimport streamlit as st\nfrom frontend.settings import ConfigurationError, load_settings\n\nSELLER_RESEARCH_PAUSED = False\n_LOCK = threading.RLock()\n_KEYS = ("campaign_brief_record", "campaign_brief_edit", "campaign_brief_dirty",\n         "campaign_brief_revision", "campaign_brief_context_version", "campaign_brief_saved_context",\n         "campaign_brief_input_signature", "campaign_context_website", "product_mapping", "buyer_personas",\n         "topic_mapping_upload", "manual_product_draft")\n\n\ndef _path():\n    settings = load_settings()\n    identity = hashlib.sha256((settings.api_url + "\\n" + settings.key_id).encode()).hexdigest()[:24]\n    root = Path(os.environ.get("XDG_STATE_HOME") or Path.home() / ".local" / "state")\n    return root / "finq" / "seller-products" / (identity + ".json")\n\n\ndef _identity(record):\n    return (record or {}).get("id") or (record or {}).get("brief_id")\n\n\ndef _snapshot(state):\n    return {key: deepcopy(state[key]) for key in _KEYS if key in state}\n\n\ndef _load(path):\n    if not path.exists():\n        return None\n    value = json.loads(path.read_text())\n    if value.get("version") != 1 or not isinstance(value.get("state"), dict):\n        raise ValueError("Invalid seller snapshot")\n    return value["state"]\n\n\ndef _save(path, state):\n    path.parent.mkdir(parents=True, exist_ok=True, mode=0o700)\n    data = json.dumps({"version": 1, "state": state}, sort_keys=True, ensure_ascii=False)\n    fd, temporary = tempfile.mkstemp(prefix=".seller-", dir=path.parent)\n    try:\n        with os.fdopen(fd, "w") as stream:\n            stream.write(data)\n            stream.flush()\n            os.fsync(stream.fileno())\n        os.replace(temporary, path)\n    finally:\n        if os.path.exists(temporary):\n            os.unlink(temporary)\n\n\ndef capture_existing_seller():\n    """Compatibility hook; explicit workspace snapshots replace session adoption."""\n    return\n\n\ndef restore_seller():\n    """Restore once after authentication, without replacing an active seller."""\n    if st.session_state.get("_seller_snapshot_loaded"):\n        return\n    try:\n        with _LOCK:\n            saved = _load(_path())\n            current = _snapshot(st.session_state)\n            if saved and not current:\n                for key, value in saved.items():\n                    st.session_state[key] = deepcopy(value)\n                st.session_state.pop("campaign_brief_seed", None)\n            st.session_state._seller_snapshot_loaded = True\n            st.session_state._seller_last_persisted = json.dumps(_snapshot(st.session_state), sort_keys=True)\n            st.session_state.pop("seller_snapshot_error", None)\n    except (OSError, ValueError, TypeError, ConfigurationError):\n        st.session_state.seller_snapshot_error = "Couldn\'t restore saved seller products. Your current session is kept."\n\n\ndef persist_seller():\n    """Save current selections, including a new mapping before research starts."""\n    try:\n        with _LOCK:\n            snapshot = _snapshot(st.session_state)\n            if not snapshot:\n                return\n            encoded = json.dumps(snapshot, sort_keys=True)\n            if encoded == st.session_state.get("_seller_last_persisted"):\n                return\n            _save(_path(), snapshot)\n            st.session_state._seller_last_persisted = encoded\n            st.session_state.pop("seller_snapshot_error", None)\n    except (OSError, ValueError, TypeError, ConfigurationError):\n        st.session_state.seller_snapshot_error = "Couldn\'t save seller products for reloads. Your current session is kept."\n\n\ndef saved_products():\n    record = st.session_state.get("campaign_brief_record") or {}\n    edit = st.session_state.get("campaign_brief_edit") or {}\n    return (edit.get("brief") if edit.get("id") == _identity(record) else None) or record.get("brief") or {}\n', 'frontend.product_mapping': '"""Seller product editing, source selection and bounded CSV/Excel imports."""\nfrom copy import deepcopy\nimport csv\nimport hashlib\nfrom io import BytesIO, StringIO\nimport posixpath\nimport re\nimport uuid\nfrom xml.etree import ElementTree as ET\nfrom xml.sax.saxutils import escape\nfrom zipfile import BadZipFile, ZIP_DEFLATED, ZipFile\n\nimport pandas as pd\nimport streamlit as st\nfrom frontend.seller_cache import persist_seller\nfrom frontend.presentation import normalize_customer_website\n\nCOLUMNS = ["Offering", "Sub-offering", "Description", "Capability"]\nTEMPLATE_COLUMNS = ["Product", "Description", "Capability"]\nMAX_BYTES = 10 * 1024 * 1024\nMAX_ROWS = 500\n_NS = "{http://schemas.openxmlformats.org/spreadsheetml/2006/main}"\n\n\ndef product_rows(rows):\n    """Project old topic-mapping rows without duplicating identical products."""\n    result, seen = [], set()\n    for row in rows or []:\n        item = {name: str(row.get(name) or "") for name in COLUMNS}\n        identity = tuple(item.values())\n        if any(identity) and identity not in seen:\n            result.append(item)\n            seen.add(identity)\n    return result\n\n\ndef current_rows(brief, mappings=None):\n    """Display one row per product; mapped sub-offerings stay in the brief."""\n    return [{"Offering": item.get("name", ""), "Sub-offering": "",\n             "Description": item.get("description", ""),\n             "Capability": ", ".join(cap.get("text", "") for cap in item.get("capabilities") or [])}\n            for item in brief.get("offerings") or []]\n\n\ndef template(kind="csv", products=None):\n    rows = [TEMPLATE_COLUMNS] + ([[name, "", ""] for name in products] if products else\n                                [["Example product", "What this product does", "Capability one, Capability two"]])\n    if kind == "csv":\n        output = StringIO(newline="")\n        csv.writer(output).writerows(rows)\n        return output.getvalue().encode("utf-8-sig")\n    if kind != "xlsx":\n        raise ValueError("Choose CSV or Excel.")\n    ns = _NS[1:-1]\n    rel = "http://schemas.openxmlformats.org/officeDocument/2006/relationships"\n    data = "".join(\'<row r="%d">%s</row>\' % (i, "".join(\n        f\'<c r="{chr(65+j)}{i}" t="inlineStr"><is><t>{escape(cell)}</t></is></c>\'\n        for j, cell in enumerate(row))) for i, row in enumerate(rows, 1))\n    files = {\n        "[Content_Types].xml": \'<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types">\'\n            \'<Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/>\'\n            \'<Default Extension="xml" ContentType="application/xml"/>\'\n            \'<Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/>\'\n            \'<Override PartName="/xl/worksheets/sheet1.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/></Types>\',\n        "_rels/.rels": \'<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">\'\n            f\'<Relationship Id="rId1" Type="{rel}/officeDocument" Target="xl/workbook.xml"/></Relationships>\',\n        "xl/workbook.xml": f\'<workbook xmlns="{ns}" xmlns:r="{rel}"><sheets><sheet name="Products" sheetId="1" r:id="rId1"/></sheets></workbook>\',\n        "xl/_rels/workbook.xml.rels": \'<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">\'\n            f\'<Relationship Id="rId1" Type="{rel}/worksheet" Target="worksheets/sheet1.xml"/></Relationships>\',\n        "xl/worksheets/sheet1.xml": f\'<worksheet xmlns="{ns}"><cols><col min="1" max="1" width="28" customWidth="1"/>\'\n            f\'<col min="2" max="3" width="55" customWidth="1"/></cols><sheetData>{data}</sheetData></worksheet>\',\n    }\n    output = BytesIO()\n    with ZipFile(output, "w", ZIP_DEFLATED) as archive:\n        for name, content in files.items():\n            archive.writestr(name, \'<?xml version="1.0" encoding="UTF-8"?>\' + content)\n    return output.getvalue()\n\n\ndef _xml(content):\n    if b"<!DOCTYPE" in content.upper():\n        raise ValueError("Use a standard Excel workbook without XML document declarations.")\n    return ET.fromstring(content)\n\n\ndef _excel_rows(content):\n    try:\n        with ZipFile(BytesIO(content)) as archive:\n            if sum(item.file_size for item in archive.infolist()) > 50 * 1024 * 1024:\n                raise ValueError("The expanded workbook is too large.")\n            workbook = _xml(archive.read("xl/workbook.xml"))\n            relationships = _xml(archive.read("xl/_rels/workbook.xml.rels"))\n            targets = {item.get("Id"): item.get("Target") for item in relationships\n                       if item.get("TargetMode") != "External"}\n            sheet = workbook.find(_NS + "sheets")[0]\n            target = targets[sheet.get("{http://schemas.openxmlformats.org/officeDocument/2006/relationships}id")]\n            path = target.lstrip("/") if target.startswith("/") else posixpath.normpath("xl/" + target)\n            shared = []\n            if "xl/sharedStrings.xml" in archive.namelist():\n                shared = ["".join(node.text or "" for node in item.iter(_NS + "t"))\n                          for item in _xml(archive.read("xl/sharedStrings.xml")).findall(_NS + "si")]\n            rows = []\n            for row in _xml(archive.read(path)).iter(_NS + "row"):\n                cells = {}\n                for cell in row.findall(_NS + "c"):\n                    letters = re.match(r"[A-Z]+", cell.get("r", "").upper())\n                    if not letters:\n                        continue\n                    column = 0\n                    for letter in letters[0]:\n                        column = column * 26 + ord(letter) - 64\n                    if column > 100:\n                        continue\n                    kind = cell.get("t")\n                    value = cell.findtext(_NS + "v", "")\n                    if kind == "inlineStr":\n                        value = "".join(node.text or "" for node in cell.iter(_NS + "t"))\n                    elif kind == "s":\n                        value = shared[int(value)]\n                    if cell.find(_NS + "f") is not None:\n                        raise ValueError("Use plain text product values, without Excel formulas.")\n                    cells[column - 1] = str(value).strip()\n                if any(cells.values()):\n                    rows.append([cells.get(i, "") for i in range(max(cells) + 1)])\n                    if len(rows) > MAX_ROWS + 1:\n                        raise ValueError("Use at most 500 product rows.")\n            return rows\n    except (BadZipFile, KeyError, IndexError, TypeError, ET.ParseError) as error:\n        raise ValueError("Couldn\'t read this Excel file. Use the template and try again.") from error\n\n\ndef read_mapping(filename, content):\n    if len(content) > MAX_BYTES:\n        raise ValueError("Use a file smaller than 10 MB.")\n    if filename.lower().endswith(".xlsx"):\n        rows = _excel_rows(content)\n    elif filename.lower().endswith(".csv"):\n        try:\n            text = content.decode("utf-8-sig")\n            try:\n                dialect = csv.Sniffer().sniff(text[:8192], delimiters=",;\\t")\n            except csv.Error:\n                dialect = csv.excel\n            rows = [row for row in csv.reader(StringIO(text), dialect) if any(cell.strip() for cell in row)]\n        except (UnicodeDecodeError, csv.Error) as error:\n            raise ValueError("Use a UTF-8 CSV file matching the template.") from error\n    else:\n        raise ValueError("Upload an Excel (.xlsx) or CSV file.")\n    if not rows or len(rows) < 2:\n        raise ValueError("Add at least one product below the template header.")\n    if len(rows) > MAX_ROWS + 1:\n        raise ValueError("Use at most 500 product rows.")\n    normalize = lambda value: re.sub(r"[^a-z]", "", str(value).lower())\n    headers = [normalize(value) for value in rows[0]]\n    # Accept previously downloaded templates without changing stored product keys.\n    headers = ["product" if value == "offering" else value for value in headers]\n    required = [normalize(value) for value in TEMPLATE_COLUMNS]\n    if any(headers.count(value) != 1 for value in required) or headers.count("suboffering") > 1:\n        raise ValueError("Use these three column headers: " + ", ".join(TEMPLATE_COLUMNS) + ". Include each header once.")\n    indices = [headers.index(value) if value in headers else None\n               for value in ("product", "suboffering", "description", "capability")]\n    result = []\n    for number, row in enumerate(rows[1:], 2):\n        item = {name: str(row[index]).strip() if index is not None and index < len(row) else ""\n                for name, index in zip(COLUMNS, indices)}\n        if not any(item.values()):\n            continue\n        if not item["Offering"]:\n            raise ValueError(f"Row {number}: add a Product.")\n        result.append(item)\n    if not result:\n        raise ValueError("Add at least one product below the template header.")\n    return product_rows(result)\n\n\ndef _manual_id(kind, *parts):\n    return "manual_" + hashlib.sha256((kind + "\\n" + "\\n".join(parts)).encode()).hexdigest()[:20]\n\n\ndef _capability_texts(text, known):\n    """Keep whole researched claims, including commas, when other claims change."""\n    values = []\n    remaining = text.strip()\n    candidates = sorted((value for value in known if value), key=len, reverse=True)\n    while remaining:\n        matched = next((value for value in candidates if remaining.startswith(value)\n                        and (len(remaining) == len(value) or remaining[len(value)] == ",")), None)\n        if matched is not None:\n            value, remaining = matched, remaining[len(matched):]\n        else:\n            value, _, remaining = remaining.partition(",")\n        value = value.strip()\n        if value and value not in values:\n            values.append(value)\n        remaining = remaining.lstrip(", ")\n    return values\n\n\ndef apply_product_rows(brief, rows, mappings):\n    """Translate the table into approved claims, preserving unchanged evidence."""\n    result = deepcopy(brief)\n    existing = {item.get("name", "").casefold(): item for item in brief.get("offerings") or []}\n    if not rows or len(rows) > MAX_ROWS:\n        raise ValueError("Keep at least one product and use at most 500 rows.")\n    offerings, names = [], set()\n    for row in rows:\n        name = str(row.get("Offering") or "").strip()\n        if not name or name.casefold() in names:\n            raise ValueError("Give every product a unique name.")\n        names.add(name.casefold())\n        old = existing.get(name.casefold()) or {}\n        item = deepcopy(old)\n        item.update(id=old.get("id") or _manual_id("product", result.get("website", ""), name),\n                    name=name, description=str(row.get("Description") or "").strip())\n        original_caps = old.get("capabilities") or []\n        text = str(row.get("Capability") or "").strip()\n        if text == ", ".join(cap.get("text", "") for cap in original_caps):\n            item["capabilities"] = deepcopy(original_caps)\n        else:\n            by_text = {cap.get("text", ""): cap for cap in original_caps}\n            values = _capability_texts(text, by_text)\n            item["capabilities"] = [deepcopy(by_text[value]) if value in by_text else\n                {"id": _manual_id("capability", item["id"], value), "text": value,\n                 "source_ids": [], "supporting_quotes": [], "user_approved": True} for value in values]\n        # These labels belong to the uploaded topic map, even though the editor\n        # intentionally displays only Product, Description and Capability.\n        subs = deepcopy(old.get("sub_offerings") or [])\n        sub_names = {sub.get("name") for sub in subs}\n        for mapping in mappings or []:\n            label = str(mapping.get("sub_offering") or "").strip()\n            if mapping.get("offering") == name and label and label not in sub_names:\n                subs.append({"id": _manual_id("sub", item["id"], label), "name": label, "description": ""})\n                sub_names.add(label)\n        item["sub_offerings"] = subs\n        offerings.append(item)\n    exact_names = {item["name"] for item in offerings}\n    missing = sorted({row.get("offering") for row in mappings or [] if row.get("offering")} - exact_names)\n    if missing:\n        raise ValueError("Keep the products used in your topic mapping: " + ", ".join(missing) +\n                         ". To rename or remove them, update the mapping on Select Intent Topics first.")\n    result["offerings"] = offerings\n    return result\n\n\ndef source_state():\n    state = st.session_state.get("product_mapping") or {}\n    if state.get("live_flow_version") != 1:\n        # Retain the saved brief, but never silently reveal the former frozen\n        # seller when moving from the preview flow to live research.\n        state = {"live_flow_version": 1, "mode": None, "revision": state.get("revision", 0) + 1,\n                 "rows": [], "table_loaded": False, "generation_phase": "website", "website": ""}\n        st.session_state.pop("product_mapping_seed", None)\n        st.session_state.pop("products_generation_website", None)\n    st.session_state.product_mapping = state\n    return state\n\n\ndef invalidate_products():\n    """Discard products from a previous website or topic mapping."""\n    state = source_state()\n    for field in ("brief_id", "approved_brief_id", "rows", "auto_rows", "uploaded_rows", "confirmed_rows", "upload_signature", "upload_error"):\n        state.pop(field, None)\n    state.update(table_loaded=False, generation_phase="website", revision=state.get("revision", 0) + 1)\n    st.session_state.pop("product_mapping_seed", None)\n    # A replaced upload must not be silently applied to the new seller.\n    state["upload_revision"] = state.get("upload_revision", 0) + 1\n\n\ndef begin_visit():\n    """Require source and website entry on visits while retaining approved context."""\n    state = source_state()\n    record = st.session_state.get("campaign_brief_record") or {}\n    identity = record.get("id") or record.get("brief_id")\n    if state.get("table_loaded") and state.get("mode") in {"auto", "upload"}:\n        state["auto_rows" if state["mode"] == "auto" else "uploaded_rows"] = deepcopy(state.get("rows") or [])\n        if record.get("status") == "approved" and state.get("brief_id") == identity:\n            state["approved_brief_id"] = identity\n    state.update(mode=None, generation_phase="website", table_loaded=False)\n    st.session_state.pop("products_generation_website", None)\n    st.session_state.pop("product_mapping_seed", None)\n    persist_seller()\n\n\ndef render_source(*, regenerate=None):\n    """Render source controls before a research record exists."""\n    state = source_state()\n    if state.get("mode") not in {"auto", "upload"}:\n        st.markdown("""<style>\n        .st-key-product_source_choices button {min-height:88px; border-radius:14px;\n            justify-content:flex-start; padding:1.15rem 1.4rem; border:1px solid #cbd5e1;}\n        .st-key-product_source_choices button p {font-size:1.05rem; font-weight:600;}\n        .st-key-product_source_choices button:hover {border-color:#00a443; background:rgba(0,164,67,.06);}\n        </style>""", unsafe_allow_html=True)\n        with st.container(key="product_source_choices"):\n            auto, upload = st.columns(2)\n            choose_auto = auto.button("Auto generate", icon=":material/auto_awesome:", width="stretch", key="products_auto_generate")\n            choose_upload = upload.button("Upload it yourself", icon=":material/upload_file:", width="stretch", key="products_upload")\n        if choose_auto or choose_upload:\n            state.update(mode="auto" if choose_auto else "upload",\n                         generation_phase="website" if choose_auto else "upload", table_loaded=False)\n            record = st.session_state.get("campaign_brief_record") or {}\n            if bool(record.get("source") == "manual_upload") != bool(choose_upload):\n                st.session_state.campaign_brief_dirty = True\n            st.session_state.pop("products_generation_website", None)\n            persist_seller()\n            st.rerun()\n        return state\n    st.markdown("""<style>\n    .st-key-products_change_source button {min-width:7rem; background:#00a443; border-color:#00a443; color:white;}\n    .st-key-products_change_source button:hover {background:#008c39; border-color:#008c39; color:white;}\n    </style>""", unsafe_allow_html=True)\n    record = st.session_state.get("campaign_brief_record") or {}\n    can_regenerate = (regenerate is not None and state["mode"] == "auto"\n                      and state.get("generation_phase") != "website"\n                      and record.get("source") != "manual_upload"\n                      and record.get("status") in {"complete", "approved"} and bool(record.get("brief")))\n    refresh = False\n    with st.container(border=True, width="content", horizontal=True, vertical_alignment="center", gap="medium", key="product_source_control"):\n        st.markdown(":material/auto_awesome: **Auto generate**" if state["mode"] == "auto" else\n                    ":material/upload_file: **Upload it yourself**", width="content")\n        change = st.button("Change", icon=":material/swap_horiz:", type="primary", width="content", key="products_change_source")\n        if can_regenerate:\n            refresh = st.button("Regenerate", icon=":material/refresh:", width="content", key="products_regenerate",\n                                help="Research this seller again using the current website and topic mapping.")\n    if change:\n        state.update(mode=None, generation_phase="website", table_loaded=False)\n        st.session_state.pop("products_generation_website", None)\n        persist_seller()\n        st.rerun()\n    if refresh and regenerate():\n        invalidate_products()\n        source_state()["generation_phase"] = "research"\n        persist_seller()\n        st.rerun()\n    return state\n\n\ndef website_prompt(state):\n    """Return a valid website only after explicit form submission."""\n    with st.form("products_website_form", border=False):\n        website_column, action_column = st.columns([4, 1], vertical_alignment="bottom")\n        website = website_column.text_input("Seller website", value=state.get("website", ""),\n            placeholder="https://example.com", key="products_generation_website")\n        label = "Research seller" if state.get("mode") == "auto" else "Continue"\n        generate = action_column.form_submit_button(label, type="primary", width="stretch", key="products_generate_submit")\n    if generate:\n        try:\n            return normalize_customer_website(website)\n        except ValueError as error:\n            st.error(str(error))\n    return None\n\n\ndef bind_products(record):\n    state = source_state()\n    identity = record.get("id") or record.get("brief_id")\n    if state.get("brief_id") != identity:\n        state.update(brief_id=identity, rows=[], table_loaded=False, revision=state.get("revision", 0) + 1)\n        for field in ("approved_brief_id", "uploaded_rows", "auto_rows", "confirmed_rows", "upload_signature", "upload_error"):\n            state.pop(field, None)\n        st.session_state.pop("product_mapping_seed", None)\n    if state.get("generation_phase") != "ready":\n        state["generation_phase"] = "ready"\n        rows = (state.get("auto_rows") or current_rows(record.get("brief") or {})) if state.get("mode") == "auto" else state.get("uploaded_rows")\n        state.update(rows=deepcopy(rows or []), table_loaded=bool(rows), revision=state.get("revision", 0) + 1)\n        st.session_state.pop("product_mapping_seed", None)\n    return state\n\n\ndef render_editor(record, draft):\n    identity = record.get("id") or record.get("brief_id")\n    state = bind_products(record)\n    candidate = st.session_state.get("campaign_brief_edit") or {}\n    brief = deepcopy(candidate.get("brief") if candidate.get("id") == identity else record.get("brief") or {})\n    if state.get("mode") == "upload":\n        csv_column, excel_column = st.columns(2)\n        csv_column.download_button("CSV template", template("csv"), "products_template.csv", "text/csv", on_click="ignore", key="products_csv_template")\n        excel_column.download_button("Excel template", template("xlsx"), "products_template.xlsx",\n            "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet", on_click="ignore", key="products_excel_template")\n        upload = st.file_uploader("Upload products", type=["csv", "xlsx"], key=f"products_mapping_upload_{state.get(\'upload_revision\', 0)}",\n            help="Use Product, Description and Capability. Separate multiple capabilities with commas. Keep the product names from your topic mapping.")\n        if upload is not None:\n            signature = hashlib.sha256(upload.name.encode() + upload.getvalue()).hexdigest()\n            if state.get("upload_signature") != signature:\n                state["upload_signature"] = signature\n                try:\n                    rows = read_mapping(upload.name, upload.getvalue())\n                    apply_product_rows(brief, rows, draft.get("topic_mappings") or [])\n                    state.update(rows=rows, uploaded_rows=deepcopy(rows), revision=state.get("revision", 0) + 1, table_loaded=True)\n                    state.pop("upload_error", None)\n                    st.session_state.campaign_brief_dirty = True\n                    persist_seller()\n                    st.rerun()\n                except ValueError as error:\n                    state["upload_error"] = str(error)\n            if state.get("upload_error"):\n                st.error(state["upload_error"])\n    if not state.get("table_loaded"):\n        persist_seller()\n        return None, False, False\n    st.space("small")\n    revision = st.session_state.get("campaign_brief_revision", 0)\n    key = f"brief_{identity}_{revision}_mapping"\n    name = st.columns(2)[0].text_input("Seller name", value=brief.get("customer_name", ""), key=key + "_name")\n    description = st.text_area("What the seller offers", value=brief.get("description", ""), height=90, key=key + "_description")\n    edited = deepcopy(brief)\n    edited.update(customer_name=name.strip(), description=description.strip())\n    table_key = f"product_mapping_{identity}_{state[\'revision\']}"\n    seed = st.session_state.get("product_mapping_seed") or {}\n    if seed.get("key") != table_key:\n        seed = {"key": table_key, "rows": deepcopy(state["rows"])}\n        st.session_state.product_mapping_seed = seed\n    table = st.data_editor(pd.DataFrame(seed["rows"], columns=COLUMNS), num_rows="dynamic", hide_index=True,\n        width="stretch", height=420, key=table_key,\n        column_config={"Offering": st.column_config.TextColumn("Offering"), "Sub-offering": None,\n            "Capability": st.column_config.TextColumn("Capability", help="Separate multiple capabilities with commas.")})\n    rows = [{column: str(row.get(column) or "").strip() for column in COLUMNS} for row in table.fillna("").to_dict("records")]\n    state["rows"] = [row for row in rows if any(row.values())]\n    state["auto_rows" if state.get("mode") == "auto" else "uploaded_rows"] = deepcopy(state["rows"])\n    valid = not state.get("upload_error")\n    try:\n        edited = apply_product_rows(edited, state["rows"], draft.get("topic_mappings") or [])\n    except ValueError as error:\n        st.warning(str(error))\n        valid = False\n    saved = record.get("brief") or {}\n    changed = any(edited.get(field) != saved.get(field) for field in ("customer_name", "description", "offerings"))\n    st.session_state.campaign_brief_edit = {"id": identity, "brief": edited}\n    st.session_state.campaign_brief_dirty = changed or not valid\n    persist_seller()\n    return edited, changed, valid\n\n\n\ndef _empty_manual_brief(draft):\n    return {"customer_name": "", "website": "", "description": "", "offerings": [],\n            "taxonomy": [{"topic": topic, "classification": "ambiguous", "reason": "User-uploaded product mapping"}\n                         for topic in sorted(set(draft.get("topics") or []))],\n            "facts": [], "sources": [], "gaps": []}\n\n\ndef _manual_state(draft):\n    value = st.session_state.get("manual_product_draft") or {}\n    if value.get("version") != 1:\n        value = {"version": 1, "key": uuid.uuid4().hex, "revision": 0, "upload_revision": 0,\n                 "brief": _empty_manual_brief(draft), "rows": []}\n        st.session_state.manual_product_draft = value\n    # The user\'s current topic upload owns these relationships. Keep seller text\n    # for review, but confirmation will create a new exact manual context.\n    value["brief"]["taxonomy"] = _empty_manual_brief(draft)["taxonomy"]\n    return value\n\n\ndef _manual_file_changed(widget_key):\n    manual = st.session_state.get("manual_product_draft") or {}\n    if st.session_state.get(widget_key) is None:\n        revision = manual.get("upload_revision", 0)\n        st.session_state.manual_product_draft = {"version": 1, "key": uuid.uuid4().hex,\n            "revision": manual.get("revision", 0) + 1, "upload_revision": revision,\n            "brief": _empty_manual_brief(st.session_state.get("draft") or {}), "rows": []}\n        state = source_state()\n        for field in ("approved_brief_id", "brief_id", "confirmed_rows"):\n            state.pop(field, None)\n        state.update(table_loaded=False, rows=[])\n    else:\n        manual["pending_upload"] = True\n    st.session_state.campaign_brief_dirty = True\n    persist_seller()\n\n\ndef render_manual_editor(draft):\n    """Upload and review products without borrowing a researched seller identity."""\n    state = source_state()\n    manual = _manual_state(draft)\n    products = list(dict.fromkeys(row.get("offering") for row in draft.get("topic_mappings") or [] if row.get("offering")))\n    csv_column, excel_column = st.columns(2)\n    csv_column.download_button("CSV template", template("csv", products), "products_template.csv", "text/csv",\n                               on_click="ignore", key="products_csv_template")\n    excel_column.download_button("Excel template", template("xlsx", products), "products_template.xlsx",\n        "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet", on_click="ignore", key="products_excel_template")\n    upload_key = f"products_manual_upload_{manual.get(\'upload_revision\', 0)}"\n    upload = st.file_uploader("Upload products", type=["csv", "xlsx"], key=upload_key,\n        on_change=_manual_file_changed, args=(upload_key,),\n        help="Use Product, Description and Capability. Separate multiple capabilities with commas. Keep the product names from your topic mapping.")\n    if upload is not None:\n        signature = hashlib.sha256(upload.name.encode() + upload.getvalue()).hexdigest()\n        if manual.get("upload_signature") != signature:\n            manual["upload_signature"] = signature\n            try:\n                rows = read_mapping(upload.name, upload.getvalue())\n                # A replaced file starts with a clean identity and no old claims.\n                brief = apply_product_rows(_empty_manual_brief(draft), rows, draft.get("topic_mappings") or [])\n                manual = {"version": 1, "key": uuid.uuid4().hex, "revision": manual.get("revision", 0) + 1,\n                    "upload_revision": manual.get("upload_revision", 0), "upload_signature": signature,\n                    "filename": upload.name, "brief": brief, "rows": rows}\n                st.session_state.manual_product_draft = manual\n                for field in ("approved_brief_id", "brief_id", "confirmed_rows"):\n                    state.pop(field, None)\n                state.update(table_loaded=True, generation_phase="ready", rows=deepcopy(rows))\n                st.session_state.campaign_brief_dirty = True\n                persist_seller()\n                st.rerun()\n            except ValueError as error:\n                manual["upload_error"] = str(error)\n        manual.pop("pending_upload", None)\n    if manual.get("upload_error"):\n        st.error(manual["upload_error"])\n    if not manual.get("rows"):\n        state.update(table_loaded=False)\n        st.session_state.campaign_brief_dirty = True\n        persist_seller()\n        return None, False, False\n    brief = deepcopy(manual["brief"])\n    key = "manual_product_" + manual["key"]\n    st.space("small")\n    name = st.columns(2)[0].text_input("Seller name", value=brief.get("customer_name", ""), key=key + "_name")\n    description = st.text_area("What the seller offers", value=brief.get("description", ""), height=90,\n                               key=key + "_description")\n    table_key = key + "_rows_" + str(manual.get("revision", 0))\n    if manual.get("seed_key") != table_key:\n        manual.update(seed_key=table_key, seed_rows=deepcopy(manual["rows"]))\n    table = st.data_editor(pd.DataFrame(manual["seed_rows"], columns=COLUMNS), num_rows="dynamic", hide_index=True,\n        width="stretch", height=420, key=table_key,\n        column_config={"Offering": st.column_config.TextColumn("Offering"), "Sub-offering": None,\n            "Capability": st.column_config.TextColumn("Capability", help="Separate multiple capabilities with commas.")})\n    rows = [{column: str(row.get(column) or "").strip() for column in COLUMNS}\n            for row in table.fillna("").to_dict("records")]\n    rows = [row for row in rows if any(row.values())]\n    edited = _empty_manual_brief(draft)\n    # Only this manual draft can preserve its manual IDs/claims; no research record\n    # or prior source is used while accepting a product file.\n    edited["offerings"] = deepcopy(brief.get("offerings") or [])\n    edited.update(customer_name=name.strip(), description=description.strip())\n    valid = not manual.get("upload_error") and not manual.get("pending_upload")\n    try:\n        edited = apply_product_rows(edited, rows, draft.get("topic_mappings") or [])\n    except ValueError as error:\n        st.warning(str(error))\n        valid = False\n    mapped = {row.get("offering") for row in draft.get("topic_mappings") or []}\n    if valid and not any(item.get("name") in mapped and\n            (str(item.get("description") or "").strip() or item.get("capabilities"))\n            for item in edited.get("offerings") or []):\n        st.warning("Add a description or capability for at least one mapped product.")\n        valid = False\n    manual.update(brief=edited, rows=deepcopy(rows))\n    record = st.session_state.get("campaign_brief_record") or {}\n    same_record = (record.get("source") == "manual_upload" and manual.get("approved_id")\n                   and manual["approved_id"] == (record.get("id") or record.get("brief_id")))\n    saved = record.get("brief") or {}\n    changed = not same_record or any(edited.get(field) != saved.get(field)\n        for field in ("customer_name", "description", "offerings"))\n    state.update(rows=deepcopy(rows), table_loaded=bool(rows), generation_phase="ready",\n                 brief_id=manual.get("approved_id") or "manual-draft-" + manual["key"])\n    st.session_state.campaign_brief_dirty = changed or not valid\n    persist_seller()\n    return edited, changed, valid\n\n\ndef confirm_mapping():\n    state = source_state()\n    state["confirmed_rows"] = deepcopy(state.get("rows") or [])\n    state["approved_brief_id"] = state.get("brief_id")\n    persist_seller()\n\n\n', 'frontend.buyer_personas': '"""Saved buyer-persona preferences for additional AI-generated buying roles.\n\nManagement-level values verified 2026-11-13 against our contacts integration and:\nhttps://docs.apollo.io/reference/people-api-search\nFunction/title examples follow Apollo\'s persona and buying-group guides:\nhttps://knowledge.apollo.io/hc/en-us/articles/4409500253837-Create-and-Use-a-Persona\nhttps://www.apollo.io/insights/how-to-find-leads-with-a-specific-job-title-or-department\nThese function labels describe buying roles, not an Apollo API department enum.\n"""\nimport re\nfrom urllib.parse import urlsplit\n\nimport streamlit as st\nfrom frontend.presentation import normalize_customer_website\nfrom frontend.seller_cache import persist_seller, saved_products\n\nSENIORITIES = {\n    "owner": "Owner", "founder": "Founder", "c_suite": "C-suite", "partner": "Partner",\n    "vp": "Vice President", "head": "Head", "director": "Director", "manager": "Manager",\n    "senior": "Senior", "entry": "Entry level", "intern": "Intern",\n}\n# Apollo accepts job titles as free text; these are editable examples, not an enum.\nFUNCTION_TITLES = {\n    "Sales": ["Chief Revenue Officer", "VP Sales", "Sales Director", "Head of Sales", "Sales Manager", "Account Executive", "Sales Development Representative"],\n    "Revenue Operations": ["VP Revenue Operations", "Director of Revenue Operations", "Revenue Operations Manager", "Revenue Operations Analyst", "Sales Operations Manager"],\n    "Marketing": ["Chief Marketing Officer", "VP Marketing", "Marketing Director", "Marketing Manager", "Marketing Operations Manager", "Demand Generation Manager"],\n    "Finance": ["Chief Financial Officer", "VP Finance", "Finance Director", "Finance Manager", "FP&A Director", "FP&A Manager", "Controller"],\n    "Operations": ["Chief Operating Officer", "VP Operations", "Operations Director", "Operations Manager"],\n    "Engineering": ["Chief Technology Officer", "VP Engineering", "Engineering Director", "Engineering Manager", "Software Engineer"],\n    "Information Technology": ["Chief Information Officer", "IT Director", "IT Manager", "Solutions Architect"],\n    "Security": ["Chief Information Security Officer", "Information Security Director", "Security Manager"],\n    "Human Resources": ["Chief Human Resources Officer", "VP Human Resources", "Human Resources Director", "Human Resources Manager", "Talent Acquisition Manager"],\n    "Procurement": ["Chief Procurement Officer", "Procurement Director", "Procurement Manager", "Vendor Manager", "Sourcing Manager"],\n    "Legal": ["General Counsel", "Legal Director", "Legal Operations Manager"],\n}\nKEYWORDS = {\n    "Sales": ["sales", "crm", "pipeline", "salesforce", "sales forecasting", "account management"],\n    "Revenue Operations": ["revenue operations", "revops", "revenue intelligence", "sales operations", "sales forecasting", "crm", "pipeline"],\n    "Marketing": ["marketing", "advertising", "demand generation", "campaign", "seo", "content management"],\n    "Finance": ["finance", "financial", "accounting", "budget", "budgeting", "expense", "payments", "fp&a"],\n    "Operations": ["supply chain", "logistics", "manufacturing", "inventory", "business operations"],\n    "Engineering": ["developer", "developers", "software development", "engineering", "devops", "api", "apis"],\n    "Information Technology": ["information technology", "it management", "cloud infrastructure", "enterprise integration", "it operations"],\n    "Security": ["cybersecurity", "security", "identity management", "threat", "access management"],\n    "Human Resources": ["human resources", "recruiting", "recruitment", "payroll", "talent", "employee engagement"],\n    "Procurement": ["procurement", "sourcing", "vendor management", "purchasing"],\n    "Legal": ["legal", "contract management", "contract lifecycle", "litigation"],\n}\n\n\ndef _unique(values):\n    result, seen = [], set()\n    for value in values:\n        value = str(value).strip()\n        if value and value.casefold() not in seen:\n            result.append(value)\n            seen.add(value.casefold())\n    return result\n\n\n\ndef snapshot_persona_preferences(state):\n    """Copy only campaign preparation fields; never include website or UI state."""\n    state = state if isinstance(state, dict) else {}\n    def values(name):\n        items = state.get(name) or []\n        if not isinstance(items, (list, tuple)):\n            return []\n        return sorted(_unique(value for value in items if isinstance(value, str)), key=str.casefold)\n    return {"functions": values("functions"), "seniorities": values("seniorities"),\n            "titles": values("titles"), "include_similar_titles": state.get("include_similar_titles", True) is not False}\n\n\ndef persona_preferences_active(preferences):\n    return bool(preferences["functions"] or preferences["seniorities"] or preferences["titles"]\n                or not preferences["include_similar_titles"])\n\n\ndef persona_preparation_fields(capabilities, preferences):\n    """Older backends can still prepare campaigns with no selected preferences."""\n    if capabilities.get("buyer_persona_preferences_version", 0) >= 1 and persona_preferences_active(preferences):\n        return {"buyer_persona_preferences": snapshot_persona_preferences(preferences)}\n    return {}\n\n\ndef persona_preparation_ready(capabilities, preferences):\n    supported = capabilities.get("buyer_persona_preferences_version", 0) >= 1\n    if persona_preferences_active(preferences) and not supported:\n        st.info("Buyer persona targeting is temporarily unavailable. Refresh the page shortly before preparing this campaign.")\n        return False\n    return True\n\n\ndef persona_preferences_summary(state):\n    preferences = snapshot_persona_preferences(state)\n    parts = list(preferences["functions"])\n    parts.extend(SENIORITIES.get(level, level) for level in preferences["seniorities"])\n    parts.extend(preferences["titles"])\n    if not preferences["include_similar_titles"]:\n        parts.append("Strict title matching")\n    return " · ".join(parts) if parts else "No additional preferences"\n\n\ndef suggest_personas(brief):\n    """Conservative, editable suggestions from existing product research only."""\n    text = [brief.get("description", "")]\n    for offering in brief.get("offerings") or []:\n        text.extend([offering.get("name", ""), offering.get("description", "")])\n        text.extend(cap.get("text", "") for cap in offering.get("capabilities") or [])\n        for sub in offering.get("sub_offerings") or []:\n            text.extend([sub.get("name", ""), sub.get("description", "")])\n    context = " ".join(str(value) for value in text).casefold()\n    ranked = []\n    for function, keywords in KEYWORDS.items():\n        score = sum(1 + (" " in phrase) for phrase in keywords if re.search(r"\\b" + re.escape(phrase) + r"\\b", context))\n        if score:\n            ranked.append((score, function))\n    functions = [function for _, function in sorted(ranked, key=lambda row: (-row[0], row[1]))[:3]]\n    return {"functions": functions, "titles": _unique(title for function in functions for title in FUNCTION_TITLES[function][:3]),\n            "seniorities": ["c_suite", "vp", "director", "manager"] if functions else []}\n\n\ndef _website(value):\n    try:\n        return normalize_customer_website(value)\n    except ValueError:\n        return None\n\n\ndef render_buyer_personas():\n    st.subheader("Set Buyer Personas")\n    products = saved_products()\n    record = st.session_state.get("campaign_brief_record") or {}\n    saved_website = _website(products.get("website") or record.get("website") or "")\n    state = st.session_state.setdefault("buyer_personas", {\n        "website": saved_website or "", "functions": [], "seniorities": [], "titles": [], "include_similar_titles": True,\n    })\n    function_column, level_column = st.columns(2)\n    functions = function_column.multiselect("Departments & Job Function", list(FUNCTION_TITLES),\n        default=None if "buyer_persona_functions" in st.session_state else state.get("functions") or [], key="buyer_persona_functions", placeholder="Select departments or job functions",\n        help="Guide additional AI personas within these functions. Bombora-derived personas stay eligible. Leave blank for no function restriction.")\n    levels = level_column.multiselect("Management Level / Seniority", list(SENIORITIES),\n        default=None if "buyer_persona_seniorities" in st.session_state else state.get("seniorities") or [], format_func=SENIORITIES.get, key="buyer_persona_seniorities",\n        placeholder="Select management levels", help="Limit additional AI personas to these levels. Leave blank for no seniority restriction.")\n    choices = _unique([*(title for function in (functions or FUNCTION_TITLES) for title in FUNCTION_TITLES[function]),\n                       *(state.get("titles") or []), *st.session_state.get("buyer_persona_titles", [])])\n    titles = st.multiselect("Job Titles", choices, default=None if "buyer_persona_titles" in st.session_state else state.get("titles") or [], key="buyer_persona_titles",\n        accept_new_options=True, placeholder="Select or add job titles", help="Guide additional AI personas with these titles. Leave blank to generate relevant titles within the selected functions and levels.")\n    similar = st.checkbox("Include people with similar titles", value=state.get("include_similar_titles", True),\n        key="buyer_persona_similar", help="Allow equivalent titles for additional AI personas while keeping the selected functions and management levels.")\n    state.update(functions=list(functions), seniorities=list(levels), titles=_unique(titles), include_similar_titles=bool(similar))\n    persist_seller()\n\n', 'frontend.topic_mapping': '"""Required, user-owned topic to product mappings and reusable upload templates."""\nfrom copy import deepcopy\nimport csv\nimport hashlib\nfrom io import BytesIO, StringIO\nfrom pathlib import PurePosixPath\nimport re\nfrom xml.sax.saxutils import escape\nfrom zipfile import ZIP_DEFLATED, ZipFile\n\nimport pandas as pd\nimport streamlit as st\nfrom frontend.seller_cache import persist_seller, saved_products\n\n\nHEADERS = ["Topic", "Offering", "Sub-offering"]\nMAX_BYTES = 10 * 1024 * 1024\nMAX_MAPPINGS = 10_000\nMAX_TOPICS = 500\n\n\ndef _key(value):\n    return " ".join(str(value or "").split()).casefold()\n\n\ndef validate_mapping_filename(filename):\n    filename = str(filename or "").strip()\n    if (not filename or len(filename) > 255 or "/" in filename or "\\\\" in filename\n            or PurePosixPath(filename).suffix.casefold() not in {".csv", ".xlsx"}):\n        raise ValueError("Use a CSV or Excel filename of at most 255 characters, without a folder path.")\n    return filename\n\n\ndef confirmed_product_names():\n    record = st.session_state.get("campaign_brief_record") or {}\n    identity = record.get("id") or record.get("brief_id")\n    preview = st.session_state.get("product_mapping") or {}\n    rows = None\n    if preview.get("brief_id") == identity:\n        if "confirmed_rows" in preview:\n            rows = preview["confirmed_rows"]\n        elif preview.get("table_loaded"):\n            rows = preview.get("rows") or []\n    values = ([row.get("Offering") or row.get("Product") for row in rows] if rows is not None else\n              [item.get("name") for item in saved_products().get("offerings") or []])\n    names = {}\n    for value in values:\n        value = str(value or "").strip()\n        if value:\n            names.setdefault(_key(value), value)\n    return list(names.values())\n\n\ndef mapping_template(products, kind="csv"):\n    rows = [HEADERS] + [["", name, ""] for name in products]\n    if len(rows) == 1:\n        rows.append(["", "", ""])\n    if kind == "csv":\n        output = StringIO(newline="")\n        csv.writer(output).writerows(rows)\n        return output.getvalue().encode("utf-8-sig")\n    if kind != "xlsx":\n        raise ValueError("Choose CSV or Excel.")\n    ns = "http://schemas.openxmlformats.org/spreadsheetml/2006/main"\n    rel = "http://schemas.openxmlformats.org/officeDocument/2006/relationships"\n    cells = "".join(\'<row r="%d">%s</row>\' % (index, "".join(\n        f\'<c r="{chr(65 + column)}{index}" t="inlineStr"><is><t>{escape(str(value))}</t></is></c>\'\n        for column, value in enumerate(row))) for index, row in enumerate(rows, 1))\n    files = {\n        "[Content_Types].xml": \'<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types">\'\n            \'<Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/>\'\n            \'<Default Extension="xml" ContentType="application/xml"/>\'\n            \'<Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/>\'\n            \'<Override PartName="/xl/worksheets/sheet1.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/></Types>\',\n        "_rels/.rels": \'<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">\'\n            f\'<Relationship Id="rId1" Type="{rel}/officeDocument" Target="xl/workbook.xml"/></Relationships>\',\n        "xl/workbook.xml": f\'<workbook xmlns="{ns}" xmlns:r="{rel}"><sheets><sheet name="Topic mapping" sheetId="1" r:id="rId1"/></sheets></workbook>\',\n        "xl/_rels/workbook.xml.rels": \'<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">\'\n            f\'<Relationship Id="rId1" Type="{rel}/worksheet" Target="worksheets/sheet1.xml"/></Relationships>\',\n        "xl/worksheets/sheet1.xml": f\'<worksheet xmlns="{ns}"><cols><col min="1" max="3" width="42" customWidth="1"/></cols>\'\n            f\'<sheetData>{cells}</sheetData></worksheet>\',\n    }\n    output = BytesIO()\n    with ZipFile(output, "w", ZIP_DEFLATED) as archive:\n        for path, content in files.items():\n            archive.writestr(path, \'<?xml version="1.0" encoding="UTF-8"?>\' + content)\n    return output.getvalue()\n\n\ndef validate_mapping_result(result, products, catalog):\n    """Accept an entire import or none of it; retain only user-uploaded relationships."""\n    if not isinstance(result, dict):\n        raise ValueError("The mapping file could not be checked. Retry the upload.")\n    if result.get("invalid"):\n        first = result["invalid"][0]\n        number = f"Row {first[\'row\']}: " if first.get("row") else ""\n        raise ValueError(number + str(first.get("message") or "Add a Topic and Offering to every used row."))\n    if result.get("unmatched"):\n        names = list(dict.fromkeys(str(row.get("input") or "") for row in result["unmatched"]))\n        raise ValueError("Topics not found in the catalog: " + ", ".join(names[:5]) +\n                         (f" and {len(names) - 5} more." if len(names) > 5 else "."))\n    rows = result.get("mappings")\n    if not isinstance(rows, list) or not rows:\n        raise ValueError("Add at least one Topic and Offering, then upload the completed template.")\n    if len(rows) > MAX_MAPPINGS:\n        raise ValueError("Use at most 10,000 topic mapping rows.")\n    # Uploaded labels define the seller products to research on the following step.\n    offerings = {}\n    topics = {_key(name): name for name in catalog}\n    mappings, seen, children = [], set(), {}\n    for row in rows:\n        if not isinstance(row, dict):\n            raise ValueError("Use the Topic, Offering and Sub-offering template columns.")\n        topic, offering, sub = (str(row.get(field) or "").strip() for field in\n                                ("topic", "offering", "sub_offering"))\n        if not topic or not offering:\n            raise ValueError("A Topic and Offering are required in every used row.")\n        if any(len(value) > 500 for value in (topic, offering, sub)):\n            raise ValueError("Keep each Topic, Offering and Sub-offering within 500 characters.")\n        if _key(topic) not in topics:\n            raise ValueError(f"Topic not found in the catalog: {topic}.")\n        offerings.setdefault(_key(offering), offering)\n        mapping = {"topic": topics[_key(topic)], "offering": offerings[_key(offering)], "sub_offering": sub}\n        child_key = (mapping["offering"].casefold(), sub.casefold())\n        if child_key in children and children[child_key] != sub:\n            raise ValueError("Use one spelling for each Sub-offering within its Offering.")\n        children[child_key] = sub\n        identity = tuple(mapping.values())\n        if identity not in seen:\n            mappings.append(mapping)\n            seen.add(identity)\n    if len({row["topic"] for row in mappings}) > MAX_TOPICS:\n        raise ValueError("Use at most 500 different topics.")\n    if len({row["offering"].casefold() for row in mappings}) > 500:\n        raise ValueError("Use at most 500 products in the uploaded mapping.")\n    return mappings\n\n\ndef _accepted_mapping(*, allow_blocked=False):\n    state = st.session_state.get("topic_mapping_upload") or {}\n    accepted = state.get("accepted") or {}\n    if (state.get("version") != 1 or (state.get("blocked") and not allow_blocked) or not accepted.get("mappings")\n            or not re.fullmatch(r"[0-9a-f]{64}", str(accepted.get("file_sha256") or ""))):\n        return None\n    try:\n        validate_mapping_filename(accepted.get("filename"))\n        mappings = validate_mapping_result({"mappings": accepted["mappings"]}, [], accepted.get("topics") or [])\n    except (ValueError, TypeError, KeyError):\n        return None\n    topics = list(dict.fromkeys(row["topic"] for row in mappings))\n    if accepted.get("mappings") != mappings or accepted.get("topics") != topics:\n        return None\n    return accepted\n\n\ndef _selected_topics(accepted=None):\n    state = st.session_state.get("topic_mapping_upload") or {}\n    return list(dict.fromkeys(state.get("selected_topics", (accepted or {}).get("topics", []))))\n\n\ndef _selected_mappings(accepted, topics):\n    selected = set(topics)\n    return [deepcopy(row) for row in (accepted or {}).get("mappings", []) if row["topic"] in selected]\n\n\ndef reconcile_mapping_catalog(draft, catalog):\n    """Silently remove retired topics from a previously accepted mapping.\n\n    A ready taxonomy workbook is authoritative. Loading/error/fallback catalogs\n    never replace accepted input. Rejected file replacements stay rejected.\n    """\n    if not isinstance(catalog, dict) or catalog.get("status") != "ready" or catalog.get("source") != "taxonomy":\n        return None\n    revision = catalog.get("sha256")\n    names = catalog.get("topics")\n    if (not re.fullmatch(r"[0-9a-f]{64}", str(revision or ""))\n            or not isinstance(names, list) or not names\n            or any(not isinstance(name, str) or not name.strip() for name in names)):\n        return None\n    state = st.session_state.get("topic_mapping_upload") or {}\n    accepted = _accepted_mapping(allow_blocked=True)\n    if not accepted or state.get("catalog_revision") == revision:\n        return None\n    previous = deepcopy(accepted)\n    lookup = {_key(name): name for name in names}\n    state["selected_topics"] = list(dict.fromkeys(lookup[_key(topic)] for topic in _selected_topics(accepted)\n                                                 if _key(topic) in lookup))\n    rows, seen = [], set()\n    for row in accepted["mappings"]:\n        topic = lookup.get(_key(row["topic"]))\n        if topic is None:\n            continue\n        item = {**row, "topic": topic}\n        identity = tuple(item[field] for field in ("topic", "offering", "sub_offering"))\n        if identity not in seen:\n            rows.append(item)\n            seen.add(identity)\n    state["catalog_revision"] = revision\n    if rows == accepted["mappings"]:\n        restore_mapping_upload(draft)\n        persist_seller()\n        return None\n    if rows:\n        accepted.update(mappings=rows, topics=list(dict.fromkeys(row["topic"] for row in rows)))\n        current = deepcopy(accepted)\n    else:\n        state.pop("accepted", None)\n        current = None\n        if not state.get("blocked"):\n            # Drop the old uploader widget too, so the removed file cannot be\n            # reparsed as a fresh invalid upload on the next render.\n            state["revision"] = state.get("revision", 0) + 1\n            state.pop("attempt", None)\n    restore_mapping_upload(draft)\n    persist_seller()\n    return {"previous": previous, "current": current}\n\n\ndef mapping_upload_ready(draft):\n    accepted = _accepted_mapping()\n    topics = _selected_topics(accepted)\n    return bool(accepted and topics and len(topics) <= MAX_TOPICS\n                and set(topics) <= set(accepted["topics"]) and draft.get("topics") == topics\n                and draft.get("topic_mappings") == _selected_mappings(accepted, topics))\n\n\ndef restore_mapping_upload(draft):\n    state = st.session_state.get("topic_mapping_upload") or {}\n    accepted = _accepted_mapping(allow_blocked=True)\n    if accepted is None and "selected_topics" not in state:\n        return False\n    topics = _selected_topics(accepted)\n    draft.update(topics=topics, topic_mappings=_selected_mappings(accepted, topics))\n    return bool(accepted and not state.get("blocked"))\n\n\ndef uploaded_mapping_payload(draft):\n    if not mapping_upload_ready(draft):\n        return None\n    accepted = st.session_state.topic_mapping_upload["accepted"]\n    return {"topics": deepcopy(draft["topics"]), "mappings": deepcopy(draft["topic_mappings"]),\n            "file_sha256": accepted["file_sha256"], "filename": accepted["filename"]}\n\n\ndef _clear_mapping(draft):\n    state = st.session_state.get("topic_mapping_upload") or {}\n    st.session_state.topic_mapping_upload = {"version": 1, "revision": state.get("revision", 0) + 1,\n                                           "selected_topics": []}\n    draft.update(topics=[], topic_mappings=[])\n    persist_seller()\n\n\ndef _file_changed(widget_key):\n    state = st.session_state.setdefault("topic_mapping_upload", {"version": 1})\n    if st.session_state.get(widget_key) is None:\n        _clear_mapping(st.session_state.get("draft", {}))\n    else:\n        state.update(blocked=True, attempt=None)\n        persist_seller()\n\n\ndef _topics_changed():\n    state = st.session_state.setdefault("topic_mapping_upload", {"version": 1})\n    state["selected_topics"] = list(st.session_state.get("topic_selection") or [])\n    restore_mapping_upload(st.session_state.draft)\n    persist_seller()\n\n\ndef render_topic_selector(draft, catalog):\n    """Render after import processing so this run\'s uploaded topics are selected."""\n    state = st.session_state.setdefault("topic_mapping_upload", {"version": 1})\n    selected = list(draft.get("topics") or [])\n    names = catalog.get("topics") or []\n    if (catalog.get("status") == "ready" and catalog.get("source") == "taxonomy" and names\n            and re.fullmatch(r"[0-9a-f]{64}", str(catalog.get("sha256") or ""))):\n        lookup = {_key(name): name for name in names}\n        selected = list(dict.fromkeys(lookup[_key(topic)] for topic in selected if _key(topic) in lookup))\n    state["selected_topics"] = selected\n    restore_mapping_upload(draft)\n    # The widget is instantiated only after this rerun\'s import/refresh changes.\n    st.session_state.topic_selection = selected\n    st.multiselect("Intent topics", sorted(set(names) | set(selected), key=str.casefold),\n                   key="topic_selection", max_selections=MAX_TOPICS, on_change=_topics_changed,\n                   placeholder="Search and select topics",\n                   help="Choose topics from the catalog. Uploaded topics are selected automatically.")\n    accepted = _accepted_mapping()\n    missing = [topic for topic in selected if topic not in (accepted or {}).get("topics", [])]\n    if accepted and missing:\n        st.caption("Include these topics in your mapping upload: " + ", ".join(missing[:5]) +\n                   (f" and {len(missing) - 5} more." if len(missing) > 5 else "."))\n    elif accepted and not selected:\n        st.caption("Choose at least one topic to continue.")\n    persist_seller()\n\n\ndef render_topic_mapping_upload(api, draft, catalog):\n    products = confirmed_product_names()\n    state = st.session_state.setdefault("topic_mapping_upload", {"version": 1})\n    st.caption("Upload the topics and offerings to research. Fill in Topic and Offering for each row; Sub-offering is optional.")\n    left, right = st.columns(2)\n    left.download_button("CSV template", mapping_template(products), "topic_mapping_template.csv", "text/csv",\n                         on_click="ignore", key="topic_mapping_csv_template")\n    right.download_button("Excel template", mapping_template(products, "xlsx"), "topic_mapping_template.xlsx",\n                          "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",\n                          on_click="ignore", key="topic_mapping_excel_template")\n    revision = state.get("revision", 0)\n    widget_key = f"topic_mapping_file_{revision}"\n    upload = st.file_uploader("Upload topic mapping", type=["csv", "xlsx"], key=widget_key,\n                             on_change=_file_changed, args=(widget_key,),\n                             help="Use Topic, Offering and Sub-offering columns. The next step researches these offerings on the seller\'s website.")\n    if upload is not None:\n        content = upload.getvalue()\n        signature = hashlib.sha256(content).hexdigest()\n        attempt_key = hashlib.sha256((upload.name + "\\n" + signature).encode()).hexdigest()\n        attempt = state.get("attempt") or {}\n        if attempt.get("key") != attempt_key:\n            state.update(blocked=True, attempt={"key": attempt_key})\n            try:\n                filename = validate_mapping_filename(upload.name)\n                if len(content) > MAX_BYTES:\n                    raise ValueError("Use a CSV or Excel file smaller than 10 MB.")\n                response = api("POST", "/imports/topic-mapping", files={"file": (filename, content)},\n                               error_state="topic_mapping_upload_error")\n                if response is None:\n                    raise ValueError("Couldn\'t check this file. Retry the upload.")\n                mappings = validate_mapping_result(response.json(), products, catalog)\n                accepted = {"filename": filename, "file_sha256": signature,\n                            "mappings": mappings, "topics": list(dict.fromkeys(row["topic"] for row in mappings))}\n                previous_topics = set((state.get("accepted") or {}).get("topics", []))\n                manual_topics = [topic for topic in state.get("selected_topics", draft.get("topics", []))\n                                 if topic not in previous_topics]\n                selected = list(dict.fromkeys([*manual_topics, *accepted["topics"]]))\n                if len(selected) > MAX_TOPICS:\n                    raise ValueError("Choose at most 500 topics, including the topics in your upload.")\n                state.update(version=1, accepted=accepted, blocked=False,\n                             selected_topics=selected)\n                state.pop("catalog_revision", None)\n                restore_mapping_upload(draft)\n            except (ValueError, TypeError, KeyError) as error:\n                state["attempt"]["error"] = str(error)\n            persist_seller()\n    accepted = state.get("accepted") or {}\n    attempt = state.get("attempt") or {}\n    if state.get("blocked"):\n        st.error(attempt.get("error") or "Upload a valid topic mapping to continue.")\n        if upload is not None and st.button("Retry upload", key="topic_mapping_retry"):\n            state["attempt"] = None\n            st.rerun()\n        if accepted:\n            if st.button("Use previous mapping", key="topic_mapping_previous"):\n                state.update(blocked=False, attempt=None, revision=revision + 1)\n                restore_mapping_upload(draft)\n                persist_seller()\n                st.rerun()\n    elif not accepted:\n        st.info("Upload your completed topic mapping to continue.")\n    if accepted:\n        st.caption(f"Uploaded: {accepted.get(\'filename\', \'Mapping\')} · {len(accepted.get(\'mappings\') or []):,} mappings")\n        rows = [{label: row.get(field, "") for label, field in zip(HEADERS, ("topic", "offering", "sub_offering"))}\n                for row in accepted.get("mappings") or []]\n        st.dataframe(pd.DataFrame(rows, columns=HEADERS), hide_index=True, width="stretch")\n        if st.button("Remove mapping", key="topic_mapping_remove", type="tertiary"):\n            _clear_mapping(draft)\n            st.rerun()\n    return mapping_upload_ready(draft)\n'}

import hashlib as _hashlib
import importlib.abc as _abc
import importlib.util as _util
import linecache as _linecache
import sys as _sys

# Refresh embedded modules whenever their source changes during a Streamlit rerun.
_BUNDLE_VERSION = _hashlib.sha256(repr(_FRONTEND_SOURCES).encode("utf-8")).hexdigest()

class _FrontendBundle(_abc.MetaPathFinder, _abc.Loader):
    def find_spec(self, fullname, path=None, target=None):
        if fullname == "frontend" or fullname in _FRONTEND_SOURCES:
            return _util.spec_from_loader(fullname, self, is_package=fullname == "frontend")
        return None

    def create_module(self, spec):
        return None

    def exec_module(self, module):
        if module.__name__ == "frontend":
            module.__path__ = []
            return
        source = _FRONTEND_SOURCES[module.__name__]
        filename = "<bundled " + module.__name__ + ">"
        module.__file__ = filename
        _linecache.cache[filename] = (len(source), None, source.splitlines(True), filename)
        exec(compile(source, filename, "exec"), module.__dict__)

if getattr(_sys, "_intent_frontend_bundle", None) != _BUNDLE_VERSION:
    for _name in list(_sys.modules):
        if _name == "frontend" or _name.startswith("frontend."):
            del _sys.modules[_name]
    _sys.meta_path[:] = [f for f in _sys.meta_path if not getattr(f, "_intent_bundle", False)]
    _finder = _FrontendBundle()
    _finder._intent_bundle = True
    _sys.meta_path.insert(0, _finder)
    _sys._intent_frontend_bundle = _BUNDLE_VERSION

